window.IA = {"lang": "cs", "ui": {"app_title": "ClayArena Interpreter Academy", "tagline": "Clay shooting for interpreters — from zero", "hero_p": "Twelve missions to learn the language of Parcours de Chasse – Sporting™ and Compak® Sporting: targets and how they fly, the gun, lead and shooting technique, the FITASC rules, the referee's calls and the etiquette of the sport. Then practise like on a real stand: translate the coach, recognise the target, find the lead and make the referee's call.", "missions": "Missions", "practice": "Practice", "start": "Start", "continue": "Continue", "lessons_n": "lessons", "min": "min", "back": "Back", "back_mission": "To the mission", "home": "Home", "key_points": "Key points", "coach_says": "The coach says", "listen": "Listen", "reveal": "Show meaning", "meaning": "Meaning", "say_it": "How to say it", "terms": "Terms", "rules_refs": "In the FITASC rules", "sources": "Sources", "quiz": "Check yourself", "correct": "Correct!", "wrong": "Not quite.", "next": "Next", "next_lesson": "Next lesson", "finish_lesson": "Lesson complete", "xp": "XP", "level": "Level", "levels": ["Newcomer", "Listener", "Range interpreter", "Stand interpreter", "Pro interpreter"], "done_of": "done", "game_coach": "Translate the coach", "game_coach_d": "Hear a coach's phrase in English and choose what it really means.", "game_flight": "Name the flight", "game_flight_d": "Watch a target fly and name the presentation.", "game_lead": "Lead lab", "game_lead_d": "See how lead works with each method — then pull the trigger yourself.", "game_call": "Referee's call", "game_call_d": "Real situations on the stand: what does the referee decide?", "game_terms": "Term cards", "game_terms_d": "Match the English term with the word shooters use in your language.", "game_exam": "Final exam", "game_exam_d": "30 questions from all missions. Pass with 80% and get your certificate.", "which_flight": "Which presentation is this?", "which_meaning": "What does the coach mean?", "which_term": "How do shooters say it in your language?", "which_def": "What does this term mean?", "launch": "Launch", "again": "Again", "score": "Score", "play_again": "Play again", "method": "Method", "m_maintained": "Maintained lead", "m_swing": "Swing-through", "m_pullaway": "Pull-away", "m_ambush": "Ambush", "speed": "Target speed", "distance": "Distance", "demo": "Watch the method", "try": "Your turn: press when you would shoot", "shoot": "Shoot", "hit": "Hit! The target breaks.", "behind": "Behind — the shot passed behind the target", "ahead": "In front — the shot passed ahead of the target", "perceived": "Lead you see at the decision", "actual": "Actual lead at the shot", "lab_note": "Slow motion, simplified physics for teaching: about 330 m/s average shot speed and 0.15 s from decision to shot. Real lead also depends on the shooter, the cartridge and the angle.", "exam_pass": "Passed! You can now get your certificate.", "exam_fail": "Not yet — 80% needed. Review the missions and try again.", "cert_name": "Your name for the certificate", "cert_print": "Print or save as PDF", "cert_title": "Certificate", "cert_text": "has completed the ClayArena Interpreter Academy course in the terminology, technique, FITASC rules and etiquette of Parcours de Chasse – Sporting™ and Compak® Sporting.", "cert_note": "Self-study certificate of ClayArena; it is not a FITASC qualification.", "question": "Question", "of": "of", "term_all": "In all ClayArena languages", "term_note_anglicism": "Shooters often just use the English word.", "confidence_low": "to be confirmed", "reset": "Reset progress", "reset_confirm": "Delete all progress and XP on this device?", "saved_local": "Progress is saved on this device.", "disclaimer": "ClayArena course. FITASC rules appear in our own paraphrase with links to the rule pages; only the official FITASC text is binding. Parcours de Chasse – Sporting™ and Compak® Sporting are trade marks of FITASC.", "language": "Language", "all_missions_done": "All missions done — time for the final exam!", "decision": "decision", "shot_moment": "shot", "lead_word": "lead", "unit_m": "m", "unit_ft": "ft", "unit_ms": "m/s"}, "missions": [{"id": "sport", "icon": "flag", "title": "The sport in ten minutes", "intro": "Before you translate a single coaching tip, you need the big picture: what people actually shoot at, who writes the rules, what a Parcours de Chasse – Sporting™ course and a Compak® Sporting field look like, and how a competition day runs. Five short lessons give you the map; every later mission fills in the details.", "lessons": [{"id": "sport-what-is-clay", "minutes": 5, "title": "Clays, not birds: what this sport is", "body": ["Clay shooting is a sport in which a shooter breaks small flying discs with a shotgun. The disc is called a target or a clay; shooters often call it a bird, but nobody shoots at live animals. The FITASC rules say plainly that shooting at live animals is not allowed, and safety and care for the environment come first.", "A machine called a trap throws each target. Its path through the air (or along the ground) is the trajectory. The gun is a smooth-bore shotgun: it fires a cartridge full of small pellets called shot, which spread into a small cloud. That is why the shooter points the gun where the target is going, not where it is now.", "This course is about two disciplines of the international federation FITASC. Parcours de Chasse – Sporting™ (Sporting™ for short) imitates hunting: traps are hidden in fields and woods, and targets fly like partridge, duck or pheasant, or roll like a hare. Compak® Sporting is the compact version: the same variety of targets, but on one small field with five stations in a line and six traps.", "You will also hear about Trap and Skeet. They are different disciplines with fixed, repeated trajectories; Olympic Trap and Skeet belong to another federation. Do not mix their rules with Sporting™ or Compak® Sporting.", "A hit is visible at once: the target breaks or at least a visible piece flies off. This clarity is what makes the sport easy to watch and, for you, easy to follow from the very first day."], "key_points": ["People shoot at clay targets thrown by traps, never at live animals.", "A shotgun fires a cloud of small pellets (shot), so the shooter points ahead of the target.", "Sporting™ imitates hunting over natural ground; Compak® Sporting is its compact version on one field.", "Trap and Skeet are other disciplines with their own rules."], "terms": ["target", "trap", "trajectory", "shotgun", "cartridge", "sporting", "compak-sporting"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Clay pigeon shooting", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch1-definition", "label": "1 · What Sporting is"}, {"book": "sporting", "id": "ch1-safety-environment", "label": "1 · Safety, environment and no live animals"}, {"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}], "coach_says": [{"en": "Watch this bird off trap B.", "meaning": "'Bird' is a target, not a real bird; trap B is the machine marked B.", "say": null}, {"en": "Today we walk the Sporting course, tomorrow it's Compak.", "meaning": "Two different disciplines on two different days.", "say": null}, {"en": "Point it, don't aim it.", "meaning": "A shotgun is swung and pointed with both eyes on the target, not aimed like a rifle.", "say": null}], "quiz": [{"q": "A coach says 'Watch the next bird.' What will you see?", "options": ["A live pigeon released from a box", "A clay target thrown by a trap", "A bird-shaped paper target on a board", "A drone"], "answer": 1, "why": "'Bird' is shooters' slang for a clay target; the FITASC rules forbid shooting at live animals."}, {"q": "What does a shotgun fire?", "options": ["One single bullet", "A small arrow-like dart", "A cloud of small pellets (shot)", "A ball filled with paint"], "answer": 2, "why": "The shot leaves the muzzle as a small cloud of pellets, so the shooter points ahead of the moving target."}, {"q": "Which statement about Compak® Sporting is correct?", "options": ["A compact version on one field, stations in a line", "It is the Olympic version of the Skeet discipline", "It is shot only at live game birds in the field", "It uses a single trap and a single station"], "answer": 0, "why": "Compak® Sporting brings Sporting™-style targets onto one small field with five stations and six traps."}]}, {"id": "sport-fitasc", "minutes": 5, "title": "FITASC, federations and ClayArena", "body": ["FITASC is the international federation for hunting-style clay shooting. It writes and updates the rules of Parcours de Chasse – Sporting™ and Compak® Sporting; the editions we follow are dated 01/01/2025. Compak® Sporting is also a trade mark protected by FITASC, which is why the name is always written with ®.", "The sport is built like a pyramid. Clubs and shooting grounds are at the bottom, national federations above them, and the national federations are members of FITASC. Layouts for national competitions are approved by the national federation, those for international competitions by FITASC. A federation may hand an event to a club, but it stays responsible for applying the rules.", "On the ground the rules are applied by referees. Each referee holds a certificate from a national federation, and the chief referee needs an international FITASC certificate. A jury handles protests, penalties and technical problems at international events. You will translate for all of them, so learn the titles: referee, chief referee, jury.", "Other bodies exist too. In Britain and the USA national associations run their own versions of the sport, such as English Sporting, with different rules and words. A British or American coach may use those words at a FITASC event; later missions show you how to handle that.", "ClayArena is the platform behind this course. It publishes competition calendars, a glossary and a plain-language summary of the FITASC rules, and through ClayAway it runs training tours. Remember: only the official FITASC text is binding; a summary is a guide, not the rule itself."], "key_points": ["FITASC writes the rules of Sporting™ and Compak® Sporting (editions of 01/01/2025).", "Club, national federation, FITASC: national layouts are approved by the federation, international ones by FITASC.", "Referees hold national certificates; the chief referee holds a FITASC international one; the jury hears protests.", "Only the official FITASC text is binding; ClayArena offers a summary."], "terms": ["fitasc", "national-federation", "referee", "chief-referee", "jury"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch1-discipline", "label": "1 · What Compak Sporting is"}, {"book": "sporting", "id": "ch15-layout-approval", "label": "15 · Who approves layouts"}, {"book": "sporting", "id": "ch15-delegation", "label": "15 · Delegating to a club"}, {"book": "sporting", "id": "ch5-referee-certificate", "label": "5 · Referee certificates"}, {"book": "sporting", "id": "ch15-jury-role", "label": "15 · Duties of the jury"}, {"book": "compak", "id": "ch19-referee-qualification", "label": "19 · Referee approval and qualifications"}], "coach_says": [{"en": "That's a CPSA term — under FITASC it's a simultaneous double.", "meaning": "The coach switches from British vocabulary to the FITASC name.", "say": null}, {"en": "Ask the chief referee, not the stand referee.", "meaning": "The question is for the senior official of the competition.", "say": null}, {"en": "The jury will decide this one.", "meaning": "The matter goes beyond the stand referee, to the competition jury.", "say": null}], "quiz": [{"q": "Who approves the layouts for an international Sporting™ competition?", "options": ["The local club", "The national federation", "The referee on the day", "FITASC"], "answer": 3, "why": "National layouts are approved by the national federation, international ones by FITASC."}, {"q": "What certificate must the chief referee hold?", "options": ["An international FITASC certificate", "A club membership card, nothing more", "A national coaching licence from his club", "None: any experienced shooter can do it"], "answer": 0, "why": "Stand referees need a national certificate; the chief referee needs an international one from FITASC."}, {"q": "A client shows you ClayArena's rules summary during a dispute. What is its status?", "options": ["It overrides the official FITASC text", "A guide only; the FITASC text is binding", "It is binding, but only in Compak® Sporting", "It replaces the referee's decision on the stand"], "answer": 1, "why": "A summary helps you understand the rules, but the referee and jury apply the official FITASC text."}]}, {"id": "sport-sporting-layout", "minutes": 5, "title": "A Sporting™ course: layouts, stands and traps", "body": ["In Parcours de Chasse – Sporting™ the ground is divided into layouts (in Ukrainian «майданчик»). A layout is a group of shooting stands that together give 25 targets: 15 singles and 5 doubles. Depending on the system, a layout has three, four or five stands, each with its own traps.", "A shooting stand is where the shooter stands: a 1 m square or a circle 1 m across, level and not slippery. Careful with the Ukrainian word «стенд»: it usually means the whole sport or the shooting ground, so translate stand as «позиція». The rest of the squad waits nearby, close enough to follow but never distracting the shooter.", "Traps are placed to suit the terrain, often partly hidden by bushes or trees, so that targets look like real game: crossing, incoming, going away, quartering, high or low, in the open or through trees. The traps of a stand are marked with letters A, B, C, D, read from left to right as seen from the stand.", "In front of each stand there is a target menu: it lists the traps in shooting order and shows special targets, such as a 90 mm, 70 mm or 60 mm target, a battue or a rabbit. The shooter reads it before stepping onto the stand, and you should too.", "Trajectories are graded by difficulty. Class A is broken by an average shooter more than 80% of the time, class B 60 to 80%, class C 40 to 60%. So a class C target is meant to be hard; a miss there is no disaster."], "key_points": ["A layout gives 25 targets: 15 singles and 5 doubles.", "A stand is a 1 m square or 1 m circle; translate stand as «позиція», not «стенд».", "Traps are lettered A, B, C, D from left to right as seen from the stand.", "The target menu shows the order of traps and any special targets.", "Difficulty classes: A over 80%, B 60–80%, C 40–60%."], "terms": ["layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "difficulty-class"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}], "coach_says": [{"en": "Layout three is the hard one today — lots of minis in the trees.", "meaning": "On the third layout there are many small targets flying through trees.", "say": null}, {"en": "On this stand, read the menu before you step in.", "meaning": "Check the order of traps and special targets first.", "say": null}, {"en": "Stand two is a class C target, don't worry about it.", "meaning": "The target is graded as hard; a miss is expected.", "say": null}], "quiz": [{"q": "How many targets does one Sporting™ layout give?", "options": ["10", "20", "25", "50"], "answer": 2, "why": "Every layout type gives 25 targets: 15 singles and 5 doubles."}, {"q": "A coach says 'Go to stand two.' How do you translate 'stand'?", "options": ["«стенд» (the shooting ground)", "«позиція»", "«трибуна»", "«стійка для рушниць»"], "answer": 1, "why": "In Sporting™ a stand is the 1 m shooting position; «стенд» in Ukrainian usually means the sport or the whole ground."}, {"q": "How are the traps of a Sporting™ stand identified?", "options": ["By numbers 1 to 6, counted from the right", "By colours painted on each machine", "By letters A, B, C, D from left to right", "By the name of the person releasing them"], "answer": 2, "why": "The letters A, B, C, D are read from left to right as seen from the stand, and the menu and scorecard use them."}]}, {"id": "sport-compak-layout", "minutes": 5, "title": "A Compak® Sporting field: five stations, six traps", "body": ["Compak® Sporting fits on one field. In front of the shooters there is a compulsory rectangle, 35 to 40 m wide and 25 m deep, marked by four corner stakes with flags. In still air every target must fly over it at some point.", "Five shooting stations, each a 1 m square, stand in a line with 2 to 5 m between their centres. They are numbered 1 to 5 from left to right («номер» in Ukrainian). Each station has a Firing Angle Limiter, a frame of tubes that stops the gun swinging too far sideways or up and stops the shooter stepping forward.", "Six traps, A to F from left to right, each carry a panel with their letter. They may be in front, at the sides, behind the shooters or on a tower; a trap behind the line must be at least 4 m above it. Every Compak has three compulsory targets: a left-to-right crosser, a right-to-left crosser and a going-away target.", "A round is 25 targets, five at each station. When a squad of six shoots, five shooters stand on the stations and the sixth waits behind station 1. Each shooter shoots the five targets of the station's menu in turn, starting from station 1. When station 5 has finished, that shooter goes to wait behind station 1, everyone else moves one station to the right, and the waiting shooter steps onto station 1.", "Some events shoot Compak® Sporting in line instead: every shooter starts on station 1 and finishes on station 5. Ask the organiser which system is used, because the procedure differs."], "key_points": ["A 35–40 m × 25 m rectangle that every target must cross.", "Five 1 m stations in a line, 2–5 m apart, each with a Firing Angle Limiter.", "Six traps lettered A to F from left to right; a trap behind the line sits on a tower at least 4 m high.", "25 targets per round, five per station; the squad rotates one station to the right.", "Compak® Sporting can be shot by squad or in line."], "terms": ["fly-over-rectangle", "firing-angle-limiter", "shooting-stand", "trap", "tower", "rotation", "waiting-position", "line"], "sources": [{"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Everybody move one to the right. Number five, to the waiting position.", "meaning": "The squad rotates; the shooter from station 5 goes behind station 1.", "say": null}, {"en": "Trap E is the tower — it comes over your head.", "meaning": "The target from trap E is thrown from a high tower and passes overhead.", "say": null}, {"en": "Mind the frame — don't swing past the post.", "meaning": "Respect the Firing Angle Limiter; do not swing the gun beyond it.", "say": null}], "quiz": [{"q": "How many traps and stations does one Compak® Sporting field have?", "options": ["4 traps, 3 stations", "6 traps, 5 stations", "5 traps, 6 stations", "8 traps, 8 stations"], "answer": 1, "why": "Traps A to F and stations 1 to 5."}, {"q": "In a squad of six, where is the sixth shooter while the others shoot?", "options": ["In the clubhouse", "Next to the referee at station 5", "Behind trap F", "Waiting behind station 1"], "answer": 3, "why": "The waiting shooter stands behind station 1 and steps onto it after each rotation."}, {"q": "What is the Firing Angle Limiter for?", "options": ["It limits the swing and stops stepping forward", "It measures the speed of each target thrown", "It holds the cartridges for the whole round", "It releases the targets on the shooter's call"], "answer": 0, "why": "It is a safety frame at each station limiting sideways and vertical swing."}]}, {"id": "sport-competition-day", "minutes": 5, "title": "A competition day from start to finish", "body": ["The day starts at registration: the shooter confirms the entry, receives a competitor number and pins it on the upper back, fully visible. Then everyone checks the squad lists and shooting times. Keeping to the timetable is the shooter's own responsibility.", "A squad is a group of up to six shooters, drawn by lot, who shoot together. In ClayAway the word also means a subgroup of a tour, so make clear which one you mean. In Parcours de Chasse – Sporting™ the squad shoots all the singles of a stand first, then the doubles, and the shooting order rotates from stand to stand. The first shooter of the squad sees the targets shown before anyone shoots.", "A round is 25 targets: one layout in Sporting™, one field in Compak® Sporting. An international competition is 200 targets, so eight rounds over several days. The referee marks each target on the score sheet, usually X for a hit and O for a miss. Shooters check their score when leaving a stand in Sporting™ and sign the sheet at the end of a Compak® Sporting round.", "Being late is costly. In Sporting™ the referee calls the name three times within one minute; a shooter who misses his turn gets zeros for the targets not shot. In Compak® Sporting a shooter who arrives after the first shooter of the squad has called gets 25 zeros for the round.", "If shooters tie for the top three places, there is a shoot-off: 25 targets, then sudden death. Lower ties are separated by countback, comparing the last round first. The day ends with the results board and the prize-giving."], "key_points": ["Registration, competitor number on the back, squad lists and times.", "A squad is up to six shooters drawn by lot; in Sporting™ singles first, then doubles, with rotating order.", "A round is 25 targets; international events are 200 targets.", "Lateness costs zeros; in Compak® Sporting 25 zeros for the round.", "Top-three ties: shoot-off of 25, then sudden death; lower ties: countback."], "terms": ["entry", "competitor-number", "squad", "round", "rotation", "score-sheet", "shoot-off", "countback", "prize-giving"], "sources": [{"title": "Let's Go Shooting — NSCA beginner's guide to sporting clays", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}], "coach_says": [{"en": "You're in squad twelve, starting on layout five at nine-thirty.", "meaning": "Squad number, start layout and start time.", "say": null}, {"en": "Check your card before you leave the stand.", "meaning": "Make sure the referee recorded your score correctly now; later it is too late.", "say": null}, {"en": "Twenty-two in the first round is fine — seven more to go.", "meaning": "22 out of 25 in the first round; seven rounds remain in a 200-target event.", "say": null}, {"en": "Stay close — if it's a tie, you shoot within fifteen minutes of the call.", "meaning": "A shooter who may be in a shoot-off must be ready soon after being called.", "say": null}], "quiz": [{"q": "How many targets is an international FITASC competition?", "options": ["50", "100", "150", "200"], "answer": 3, "why": "200 targets in rounds of 25."}, {"q": "In Compak® Sporting by squad, a shooter arrives after the first shooter has called for the first target. What happens?", "options": ["Nothing, he joins in", "He gets 25 zeros for that round", "He shoots the round alone later without penalty", "He loses one target"], "answer": 1, "why": "In squad Compak® Sporting a late arrival after the first call is scored 25 zeros; an appeal to the jury is possible for a valid reason."}, {"q": "Two shooters tie for 5th place. How are they separated?", "options": ["By a 25-target shoot-off", "By drawing lots after the event", "By countback from the last round", "By age, the younger first"], "answer": 2, "why": "Shoot-offs are only for the top three; below that, countback compares the 8th round, then the 7th and so on."}]}]}, {"id": "gear", "icon": "tool", "title": "Gun and equipment", "intro": "Coaches talk about the gun all day: 'raise the comb', 'check your selector', 'change chokes', 'nines in the bottom'. This mission gives you the words for the gun, its parts, chokes, cartridges and protective gear, together with the few equipment rules every interpreter must know.", "lessons": [{"id": "gear-gun-types", "minutes": 5, "title": "Types of shotgun and what the rules allow", "body": ["Every gun you will see on the stand is a smooth-bore shotgun. On almost every competition stand it is an over-and-under (O/U, in Ukrainian «вертикалка»): two barrels one above the other, opened by 'breaking' the gun on its hinge. Each barrel can carry its own choke, which matters for doubles.", "A side-by-side («горизонталка») has two barrels next to each other. It is the classic game gun and is allowed, but rarely seen in competition. Do not translate over-and-under simply as «двостволка»: that word covers both types.", "A semi-automatic («напівавтомат») has one barrel and reloads itself after each shot, throwing the empty case to the side. FITASC allows it, with conditions: no more than two cartridges in the gun, the breech open whenever it is carried, and in Compak® Sporting a device that stops ejected cases from hitting the neighbour.", "Pump-action guns, reloaded by sliding the fore-end by hand, are not allowed in Parcours de Chasse – Sporting™ or in Compak® Sporting. The rulebooks simply state the ban without giving a reason, so do not invent one when a client asks; just say it is the rule. Compak® Sporting also bans drillings, guns that combine shotgun and rifle barrels.", "Two more limits apply in both disciplines: the gauge may not be larger than 12 (so 20 gauge is fine), and barrels must be at least 66 cm long. Slings, gun-mounted cameras and any artificial aiming device are forbidden."], "key_points": ["Most competitors shoot an over-and-under («вертикалка»).", "Semi-automatics are allowed: at most two cartridges, breech open when carried, shell catcher in Compak® Sporting.", "Pump-action guns are banned in both disciplines; the rules give no reason.", "Gauge no larger than 12, barrels at least 66 cm, no slings or aiming devices."], "terms": ["shotgun", "over-and-under", "side-by-side", "semi-automatic", "pump-action", "gauge", "barrel-length", "shell-catcher"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-semi-auto", "label": "18 · Semi-automatics: shell catcher and two cartridges"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}], "coach_says": [{"en": "Bring your over-and-under and a spare set of chokes.", "meaning": "The two-barrel competition gun plus extra choke tubes.", "say": null}, {"en": "With a semi-auto, keep the bolt open until you're on the stand.", "meaning": "Safety rule: a semi-automatic is carried with the breech open.", "say": null}, {"en": "No pumps on this ground.", "meaning": "Pump-action guns are not accepted.", "say": null}], "quiz": [{"q": "Which gun is NOT allowed in FITASC Sporting™ and Compak® Sporting?", "options": ["A 20-gauge over-and-under", "A side-by-side", "A pump-action", "A semi-automatic with two cartridges"], "answer": 2, "why": "Pump-action guns are banned; the others are allowed if they meet the gauge and barrel limits."}, {"q": "How many cartridges may a semi-automatic hold?", "options": ["One", "Two", "Three", "As many as the magazine takes"], "answer": 1, "why": "Both rulebooks limit a semi-automatic to two cartridges."}, {"q": "A client asks why pumps are banned. What is the honest answer?", "options": ["The rules state the ban without explaining it", "The rulebook says they are too slow for doubles", "The rulebook says they are less safe", "They are in fact allowed in Compak® Sporting"], "answer": 0, "why": "The rulebooks give no reason; as an interpreter, report the rule and do not invent explanations."}]}, {"id": "gear-gun-parts", "minutes": 5, "title": "Parts of the gun, from shoulder to muzzle", "body": ["Coaches name the parts of the gun all the time, so learn them from back to front. The stock («приклад») goes into the shoulder. Its top edge, where the cheek rests, is the comb («гребінь»); 'raise the comb' or 'drop the comb' is about gun fit. The narrow part held by the trigger hand is the grip («шийка приклада»), and the rubber pad at the end is the recoil pad («затильник»).", "The metal centre of the gun is the receiver or action («колодка»). On top sits the top lever: push it aside and the gun opens. Behind it is the safety catch («запобіжник»), often combined with the barrel selector («перемикач стволів», 'selector'), which decides which barrel fires first. Underneath is the trigger («спусковий гачок») in its guard.", "A release trigger fires when it is let go, not when it is pressed. Such a gun must carry, as a warning, a sticker with a large 'R' on a fluorescent background on the outer side of the stock.", "Under the barrels the other hand holds the fore-end («цівка»). The barrels («стволи») have chambers at the back for the cartridges and muzzles («дула») at the front, where chokes are screwed in. Along the top runs the rib («планка») with a bead («мушка») at the end. The bead is a reference, not a sight: 'look at the target, not the bead'.", "Two false friends: rib is not «ребро», and 'break the gun' means open it, not damage it. And one safety rule linked to the parts: after a misfire or any other gun or cartridge failure the shooter must not open the gun or touch the safety until the referee has looked at it."], "key_points": ["Stock, comb, grip, recoil pad; receiver with top lever, safety and selector; trigger.", "Fore-end, barrels with chambers and muzzles, rib with bead.", "A release trigger needs an 'R' sticker on the stock.", "Rib ≠ «ребро»; break the gun = open it.", "After a misfire: do not open the gun or touch the safety before the referee checks."], "terms": ["stock", "comb", "grip", "recoil-pad", "receiver", "top-lever", "safety-catch", "barrel-selector", "trigger", "release-trigger", "fore-end", "barrel", "chamber", "muzzle", "rib", "bead"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-release-trigger-marking", "label": "7 · Release trigger: mandatory 'R' sticker"}, {"book": "compak", "id": "ch18-release-trigger-marking", "label": "18 · Release trigger: the 'R' sticker"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}], "coach_says": [{"en": "You're seeing too much rib — your head is up.", "meaning": "The eye is too high above the rib, usually because the head lifts off the comb.", "say": null}, {"en": "Check your selector — you fired the top barrel first.", "meaning": "The barrel selector is set the wrong way round.", "say": null}, {"en": "Break your gun and show me it's clear.", "meaning": "Open the gun and show empty chambers.", "say": null}, {"en": "Forget the bead — look at the target.", "meaning": "Focus on the target, not on the end of the barrel.", "say": null}], "quiz": [{"q": "A coach says 'Raise the comb'. Which part does he mean?", "options": ["The top of the stock, where the cheek rests", "The small bead at the end of the rib", "The guard around the trigger", "The choke tube at the muzzle"], "answer": 0, "why": "The comb is the top of the stock; raising it lifts the eye above the rib."}, {"q": "What must a gun with a release trigger carry?", "options": ["A red-painted barrel to warn others", "A large 'R' sticker on the stock", "A second, separate safety catch", "Nothing: no marking is required"], "answer": 1, "why": "Both rulebooks require the 'R' warning sticker, on a fluorescent background, on the outer side of the buttstock."}, {"q": "How do you translate 'Break your gun'?", "options": ["«Зламайте рушницю»", "«Розберіть рушницю на частини»", "«Відкрийте (переломіть) рушницю»", "«Почистіть стволи рушниці»"], "answer": 2, "why": "On a shooting ground 'break' means opening the gun on its hinge so it cannot fire."}]}, {"id": "gear-chokes", "minutes": 5, "title": "Chokes: what they do and how coaches talk about them", "body": ["A choke («чок», дульне звуження) is a slight narrowing of the barrel at the muzzle. It controls how quickly the shot spreads. More constriction keeps the shot together longer, giving a tighter pattern for far targets; less constriction spreads it sooner, giving a wider, more forgiving pattern for close targets.", "Most competition guns have interchangeable chokes: short tubes screwed into the muzzle with a choke key. Older guns may have fixed chokes machined into the barrel. Tubes from different makers often do not fit each other, and makers warn never to fire a multichoke gun without its tubes.", "Names come from English, from open to tight: cylinder, skeet, improved cylinder, light modified, modified, improved modified, full. Europeans often say them as fractions: quarter («чверть», improved cylinder), half («пів», modified), three-quarter («три чверті», improved modified) and full («повний»). Many Italian guns mark chokes with stars, and there the rule is upside down: more stars means a more open choke.", "Coaches say things like 'quarter and half', 'open up the bottom barrel', 'go tighter in the top' or 'change chokes for this stand'. Keep the names exactly as the coach says them; do not convert them into millimetres, which differ between makers.", "The rules differ between disciplines. In Parcours de Chasse – Sporting™ chokes may be changed between stands or between the singles and the doubles, if it causes no delay, but never once the shooter has stepped onto the stand. In Compak® Sporting the gun, barrels and chokes may not be changed within a round at all, only between rounds, except after a breakdown."], "key_points": ["A choke narrows the muzzle: tighter for far targets, more open for close ones.", "Interchangeable tubes are screwed in with a choke key; makers warn never to fire without them.", "Fractions: quarter = improved cylinder, half = modified, three-quarter = improved modified, full.", "Keep choke names as said; do not convert to millimetres.", "Sporting™: change between stands, never on the stand; Compak®: no change within a round."], "terms": ["choke", "multichoke", "fixed-choke", "choke-key", "cylinder", "skeet-choke", "improved-cylinder", "modified", "improved-modified", "full-choke", "pattern"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Beretta — Choke tubes identification", "url": "https://estore.beretta.com/en-gb/utility/choke-tubes-identification"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}], "coach_says": [{"en": "What chokes are you using? — Quarter and half.", "meaning": "Improved cylinder in one barrel, modified in the other.", "say": null}, {"en": "Put quarter in the bottom and half in the top — the second bird is longer.", "meaning": "More open choke for the first, closer target; tighter for the second, farther one.", "say": null}, {"en": "Open up — these are all close.", "meaning": "Fit more open chokes because the targets are near.", "say": null}, {"en": "Check your tubes are tight before the round.", "meaning": "Make sure the choke tubes have not loosened.", "say": null}], "quiz": [{"q": "Which choke gives the widest pattern?", "options": ["Full", "Improved modified", "Modified", "Cylinder"], "answer": 3, "why": "Cylinder has no constriction, so the shot spreads soonest."}, {"q": "In Sporting™, a shooter already standing on the stand wants to change a choke. Is it allowed?", "options": ["Yes, as long as it causes no delay", "No, not once he is on the stand", "Yes, but only before the doubles", "Only with the jury's permission"], "answer": 1, "why": "Changes are allowed between stands or between singles and doubles, without delay, but never once the shooter has stepped onto the stand."}, {"q": "On an Italian gun, a choke with five stars is…", "options": ["the most open", "the tightest", "a broken choke", "a rifle barrel"], "answer": 0, "why": "With star markings, more stars mean a more open choke."}]}, {"id": "gear-cartridges", "minutes": 5, "title": "Cartridges: gauge, shot size and the limits", "body": ["A cartridge («патрон») holds everything for one shot: the hull («гільза») with a metal head, the primer («капсуль»), powder («порох»), the wad («пиж») and the shot («дріб»). Shooters also say shell. 'Empties' are fired hulls.", "Gauge («калібр») is counted the old way: the smaller the number, the wider the bore, so 12 gauge is wider than 20. FITASC allows guns no larger than 12 gauge, and most shooters use 12. Never translate '12 gauge' as «12 мм».", "Shot size is also upside down: the bigger the number, the smaller the pellet, so No. 9 is finer than No. 7½. The same number can mean slightly different sizes in Britain, continental Europe and the USA, so say the number as given and check the millimetres on the box. 'Nines' and 'seven-and-a-halfs' are common coach words.", "The rules for Parcours de Chasse – Sporting™ and Compak® Sporting are the same: at most 28 g of lead shot, with a +2% tolerance; round pellets of 2.0 to 2.5 mm (±0.1 mm). Reloaded cartridges, dispersers, mixed shot sizes, black powder and tracers are forbidden. In Sporting™ the referee may take two cartridges to check, one from each vest pocket; in Compak® Sporting, shots fired with non-compliant cartridges before an inspection count as zero.", "Some grounds add their own environmental rules for practice, for example fibre wads only or steel shot only: check the ground's rules before the tour. Empty cases go into the bin on the stand, and shooters with semi-automatics pick up their ejected cases when they leave."], "key_points": ["Cartridge = hull, primer, powder, wad, shot.", "Gauge: smaller number, wider bore; FITASC maximum is 12 gauge.", "Shot size: bigger number, smaller pellet; numbering differs by country, check millimetres.", "Limits: 28 g lead (+2%), pellets 2.0–2.5 mm; no reloads, mixed shot, black powder or tracers.", "Empties go in the bin; semi-auto users pick up their cases."], "terms": ["cartridge", "hull", "primer", "powder", "wad", "shot-size", "load-weight", "gauge", "lead-shot", "steel-shot", "empties"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}, {"book": "compak", "id": "ch18-cartridge-bans", "label": "18 · Prohibited ammunition"}, {"book": "sporting", "id": "ch7-cartridge-check", "label": "7 · Cartridge checks by the referee"}, {"book": "compak", "id": "ch23-noncompliant-equipment", "label": "23 · Shots with non-compliant guns or ammunition"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "compak", "id": "ch18-empty-cases", "label": "18 · Disposing of empty cases"}], "coach_says": [{"en": "Nines for the close stuff, seven-and-a-halfs for the long crossers.", "meaning": "Finer No. 9 shot for near targets, larger No. 7½ for far crossing targets.", "say": null}, {"en": "Maximum twenty-eight grams on this shoot.", "meaning": "The load limit of the competition, as in the FITASC rules.", "say": null}, {"en": "Empties in the bin, please, not on the grass.", "meaning": "Put fired hulls into the container.", "say": null}, {"en": "Steel only on this ground.", "meaning": "Lead shot is not allowed on this ground (a local rule, not a FITASC one).", "say": null}], "quiz": [{"q": "Which is the finer shot?", "options": ["No. 7", "No. 7½", "No. 8", "No. 9"], "answer": 3, "why": "The bigger the shot number, the smaller the pellet."}, {"q": "What is the maximum shot load under FITASC rules?", "options": ["24 g, with no tolerance", "28 g, with a +2% tolerance", "32 g for long targets only", "No limit, any load is allowed"], "answer": 1, "why": "Both disciplines allow at most 28 g of lead shot, +2%."}, {"q": "A client says his gun is '12 gauge'. What does that mean?", "options": ["The bore size: wider than 20 gauge", "The bore is 12 millimetres across", "Twelve cartridges fit in the magazine", "The barrels are 12 inches long"], "answer": 0, "why": "Gauge is an old unit: the smaller the number, the wider the bore. It is not millimetres."}]}, {"id": "gear-protection-clothes", "minutes": 5, "title": "Protection, vest and dress code", "body": ["Hearing protection is compulsory for everyone on or near a layout: shooters, referees, staff and spectators, and that includes you. Earplugs («беруші») and ear muffs («навушники») both work; electronic muffs amplify voices and cut the bang, which helps you hear the coach and referee. A shooter who comes to the stand without protection is treated as absent.", "Safety glasses («захисні окуляри») are compulsory too, for shooters, referees and staff, and in Parcours de Chasse – Sporting™ for anyone close to a stand. Lenses come in colours (yellow, orange, purple, smoke) to help see targets in different light.", "The shooting vest («жилет») holds cartridges in two front pockets and has a shoulder pad. For Sporting™ it carries a contrasting horizontal line 25 cm below the shoulder axis: before calling, the top of the stock must stay below it, and the referee checks this. Compak® Sporting has no such line because the gun position at the call is free.", "Dress rules are the same in both disciplines: no short shorts (only long shorts ending no more than 5 cm above the knee), tops with at least short sleeves, no vest over a bare chest, and no sandals, for safety. The competitor number is worn on the back, fully visible. A breach first brings a warning, then further penalties.", "Many shooters also wear a cap with a peak against sun and rain, gloves, and carry a cartridge bag for the day's supply. These are custom, not rules."], "key_points": ["Ear protection is compulsory for everyone near a layout, interpreters included.", "Safety glasses are compulsory; without protection a shooter is treated as absent.", "Sporting™ vest: contrasting line 25 cm below the shoulder axis; Compak® has none.", "Dress: shorts no higher than 5 cm above the knee, sleeves, no bare chest under the vest, no sandals.", "Competitor number on the back, fully visible."], "terms": ["hearing-protection", "earplugs", "electronic-ear-muffs", "safety-glasses", "shooting-vest", "jacket-line", "dress-code", "competitor-number", "cartridge-bag"], "sources": [], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}], "coach_says": [{"en": "Ears and eyes on before you walk up.", "meaning": "Put on hearing protection and glasses before approaching the stand.", "say": null}, {"en": "Butt under the tape until you see the target.", "meaning": "Sporting™ gun-down rule: the stock stays below the vest line until the target appears.", "say": null}, {"en": "No marker needed here — it's Compak.", "meaning": "Compak® has no vest-line requirement.", "say": null}], "quiz": [{"q": "You are an interpreter standing near the stand. Must you wear ear protection?", "options": ["No, only the shooters on the stand", "Only during finals and shoot-offs", "Yes, everyone on or near a layout", "Only if the referee asks you to"], "answer": 2, "why": "Hearing protection is compulsory for shooters, referees, staff and spectators."}, {"q": "Where is the vest line in Sporting™?", "options": ["25 cm below the shoulder axis", "At the waist, on the belt line", "On the sleeve of the shooting arm", "There is none in Sporting™"], "answer": 0, "why": "The contrasting line is 25 cm below and parallel to the shoulder axis; the stock must stay below it before the target appears."}, {"q": "Which footwear is banned in both disciplines?", "options": ["Trail shoes", "Sandals", "Boots", "Trainers"], "answer": 1, "why": "Sandals are forbidden for safety reasons."}]}]}, {"id": "targets", "icon": "target", "title": "Targets", "intro": "A coach who says 'it's a midi off the tower, then a rabbit on report' assumes you can picture it. This mission teaches the target types, how colour and light change what the shooter sees, how traps release targets, how to read a target menu, and the one scoring question that decides everything: hit or lost.", "lessons": [{"id": "targets-types", "minutes": 5, "title": "Target types: standard, midi, mini, battue, rabbit, flash, ZZ", "body": ["The FITASC list for Parcours de Chasse – Sporting™ names seven target types: standard, midi, super mini, battue, rabbit, flash and ZZ. Compak® Sporting allows any standard or special target, and its list also names the rocket. Each type flies differently.", "The standard, the most common target, is a dome about 108–110 mm across. The midi is 90 mm: it keeps its speed well and looks further away than it is. The mini is 60 mm: it leaves the trap fast and slows quickly, so shooters tend to give it too much lead. The Sporting™ list calls the small target 'super mini', and the menu rule names both 70 mm and 60 mm sizes; the names are not used consistently, so always go by the millimetres written on the menu.", "The battue is a flat, thin 110 mm target. It flies edge-on, almost invisible, then turns to show its face and drops quickly. The rabbit is a 110 mm target with a thick, strong rim, rolled on its edge along the ground; it bounces and can hop over bumps. In Ukrainian you will hear «кролик» or «заєць»; this course uses «кролик».", "A flash target is filled with coloured powder that leaves a bright cloud when it is hit; it is scored like any other target. A ZZ target, also called helice, is a plastic propeller with a white centre cap that flies erratically. The rocket is a special target named only in the Compak® Sporting list; we give no specifications for it.", "In Sporting™, a target of the wrong colour, size or type is a No Bird and is repeated."], "key_points": ["Sporting™ list: standard, midi, super mini, battue, rabbit, flash, ZZ; Compak® allows any type, rocket included.", "Standard about 108–110 mm, midi 90 mm, mini 60 mm; the menu may also show 70 mm — go by millimetres.", "Battue: flat, edge-on, turns and drops; rabbit: thick rim, rolls and hops.", "Flash leaves a powder cloud; ZZ is a propeller target.", "Sporting™: wrong colour, size or type = No Bird."], "terms": ["standard-target", "midi", "mini", "super-mini", "battue", "rabbit", "flash-target", "zz-target", "rocket-target", "no-bird"], "sources": [{"title": "Shooting UK — Clay pigeon sizes: knowing what they are will help you improve your score", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}, {"title": "Let's Go Shooting — Types of clay targets", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/types-of-clay-targets/"}, {"title": "GUNS Magazine — Helice", "url": "https://gunsmagazine.com/discover/helice/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}], "coach_says": [{"en": "The midi looks far but it isn't — don't give it too much.", "meaning": "A 90 mm target seems further away than it is, so it needs less lead than the shooter thinks.", "say": null}, {"en": "The battue will turn and drop at the end — take it when it shows its belly.", "meaning": "Shoot the battue once it turns its flat face towards you.", "say": null}, {"en": "The mini is dying fast — shoot it early.", "meaning": "The small target loses speed quickly; do not wait.", "say": null}, {"en": "The rabbit will hop on that bump — stay under it.", "meaning": "Keep the muzzles low on the rolling target so a hop still meets the shot.", "say": null}], "quiz": [{"q": "Which target rolls along the ground?", "options": ["Midi", "Battue", "Rabbit", "Flash"], "answer": 2, "why": "The rabbit has a thick rim and is thrown on its edge along the ground."}, {"q": "The menu says '70 mm'. The coach calls it a mini. What should you translate?", "options": ["Correct it to 60 mm, since a mini is 60 mm", "Keep the coach's word and the 70 mm on the menu", "Call it a midi, since it is over 60 mm", "Ask the coach to say 'super mini' instead"], "answer": 1, "why": "The rules name 70 mm and 60 mm sizes and the name 'super mini'; trust the millimetres on the menu and do not correct the coach."}, {"q": "On a Sporting™ stand, a trap throws a midi instead of the standard shown on the menu. What happens?", "options": ["No Bird, the target is repeated", "It counts as a hit", "The shooter loses the target", "The round is cancelled"], "answer": 0, "why": "In Sporting™ a target of the wrong colour, size or type is a No Bird and is repeated."}]}, {"id": "targets-colours-visibility", "minutes": 5, "title": "Colours, light and visibility", "body": ["Both rulebooks ask the same thing: a target's colour must stand out clearly against the background. Two-colour targets are not recommended. So the colour is a choice by the course setter, made for each trajectory, not a separate target type.", "You will hear black, orange, white, yellow and pink targets. Many course setters use black against the sky and orange against trees and grass. A 'blazed' target has a bright orange painted dome. Careful: when a coach says 'the orange one', he means a colour, not a size. A black midi and an orange standard can come from the same stand.", "If a target of the wrong colour is thrown, the referee calls No Bird and it is repeated. In Compak® Sporting the rules add that bad weather is never a reason for a No Bird: a broken target counts and a missed one is lost, whatever the conditions. In Parcours de Chasse – Sporting™ the referee may pause shooting for a short, violent storm or downpour.", "Light changes everything. Coaches talk about backlight (the sun behind the target), flat light on grey days, shadows under trees and the background behind the target: sky, tree line or ground. A target can 'disappear' against dark trees and 'pop out' against the sky. This is why shooters change lens colour during the day.", "When you translate, keep colour words and light words exact and short: 'it's coming out of the dark trees', 'you lose it in the sun'. They explain why a shooter missed, so they matter."], "key_points": ["A target's colour must stand out against the background; two-colour targets are not recommended.", "Colour is not type: 'the orange one' is a colour, not a size.", "Wrong colour = No Bird.", "Compak®: bad weather never justifies a No Bird; Sporting™ referees may pause for a short storm.", "Backlight, flat light, background: translate light words exactly."], "terms": ["target", "no-bird", "blazed-target", "background"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch20-bad-weather", "label": "20 · No NO BIRD for bad weather"}, {"book": "sporting", "id": "ch5-weather-interruption", "label": "5 · Interrupting shooting for bad weather"}], "coach_says": [{"en": "The black one is the midi, the orange one is the standard — don't mix them up.", "meaning": "Two targets on the stand differ in colour and size.", "say": null}, {"en": "You lose it against the trees — pick it up later, in the sky.", "meaning": "The target is hard to see in front of trees; start watching where the sky is behind it.", "say": null}, {"en": "Flat light today — put the yellow lens in.", "meaning": "Grey, contrastless light; a yellow lens helps contrast.", "say": null}], "quiz": [{"q": "What do the rules require of a target's colour?", "options": ["It must always be orange", "It must stand out clearly against the background", "It must be two-coloured", "Any colour: the rules are silent"], "answer": 1, "why": "Visibility against the background is the requirement; two-colour targets are not recommended."}, {"q": "In Compak® Sporting it starts to rain hard and a shooter misses. Can he ask for a No Bird because of the weather?", "options": ["Yes, weather always justifies one", "Only for the first target of a double", "Only if the jury agrees to it", "No, weather never justifies a No Bird"], "answer": 3, "why": "The Compak® Sporting rules state that weather is never a reason for a No Bird."}, {"q": "A coach says 'Watch the orange one.' What is he describing?", "options": ["The colour of a target", "A target size of 90 mm", "A rabbit", "A broken target"], "answer": 0, "why": "Colour is chosen for visibility and says nothing about size or type."}]}, {"id": "targets-traps", "minutes": 5, "title": "Traps, release and the trapper", "body": ["A trap («машинка») is the machine that throws targets. Traps can be manual or automatic (the Compak® Sporting rules also name semi-automatic ones). In Parcours de Chasse – Sporting™ the traps of a stand are lettered A, B, C, D from left to right as seen from the stand; in Compak® Sporting the six traps are A to F, each with a letter panel. Keep the Latin letters when you translate: the menu uses them.", "The shooter releases the target with a call: the rules name 'pull' or 'ready', though in practice shooters' call words vary. In Sporting™ the referee passes the command to the trapper (in Ukrainian «оператор машинки», the person who operates the release) with a sound signal, and the target must leave within three seconds. Do not translate the call itself: it is a command for the machine, not a sentence.", "In Compak® Sporting targets may be released by hand, by remote control or by a voice-activated sonopull. With manual release the target leaves 0 to 3 seconds after the call; a sonopull has a fixed delay of 0.5 seconds. International in-line Compak® Sporting uses only sonopull with electronic refereeing.", "A voice release has a microphone at the station. Your own voice can trigger it. On such a stand, never speak aloud while the shooter is ready: whisper between targets or step back.", "Trap mistakes are No Birds: a target released more than three seconds after the call, a target from the wrong trap, a target thrown without a call, two targets from traps of the same stand in Sporting™, or a target thrown by mistake by a machine of the same Compak."], "key_points": ["Traps: A–D per Sporting™ stand, A–F on a Compak® field; keep Latin letters.", "The call ('pull', 'ready') releases the target; do not translate it.", "Sporting™: referee signals the trapper; target within 3 seconds.", "Compak®: manual 0–3 s, remote, or sonopull with a fixed 0.5 s delay.", "Late, wrong-trap or uncalled targets are No Birds; a microphone can hear you."], "terms": ["trap", "trapper", "call", "sonopull", "manual-release", "tower", "no-bird"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch16-terms", "label": "16 · Other basic terms"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Trap B is throwing lower than in the showing — tell the referee.", "meaning": "The machine's trajectory has changed; the shooter should report it before shooting.", "say": null}, {"en": "It's voice release here — don't chat on the stand.", "meaning": "A microphone releases targets; talking can launch one.", "say": null}, {"en": "The trapper was late on that one — that's a no bird.", "meaning": "The target left more than three seconds after the call.", "say": null}], "quiz": [{"q": "In Sporting™, how long may it take for the target to leave after the referee's signal?", "options": ["Up to 1 second", "Up to 3 seconds", "Up to 10 seconds", "Any time"], "answer": 1, "why": "A target released later than three seconds is a No Bird."}, {"q": "What is the fixed delay of a Compak® sonopull?", "options": ["0 seconds", "3 seconds", "0.5 seconds", "It is set by each shooter"], "answer": 2, "why": "The sonopull must apply a fixed, unchangeable delay of 0.5 seconds."}, {"q": "You are on a stand with voice release and the shooter is ready. What do you do?", "options": ["Translate loudly so that he hears you", "Ask the trapper to wait a moment", "Repeat the call word for him", "Stay silent; whisper only between targets"], "answer": 3, "why": "Your voice can trigger the microphone and release a target nobody called."}]}, {"id": "targets-menu", "minutes": 5, "title": "Reading the target menu", "body": ["The target menu («меню») is the board at the stand that tells the shooter what is coming. Shooters really say 'menu', so keep the word.", "In Parcours de Chasse – Sporting™ the menu lists the traps in shooting order and must show any special targets: 90 mm, 70 mm, 60 mm, battue or rabbit. Referees check beforehand that the machines match the menu. A layout gives 15 singles and 5 doubles, and the doubles may only use targets already shown as singles from the same stand. The squad shoots the singles first, then the doubles.", "A double is marked with its type: on report (the second target leaves on the sound of the first shot), simultaneous (both together) or rafale (two from the same trap, one after the other; Sporting™ only). Menus look different from ground to ground, so read the words, not just the letters. Example for a stand with three traps: singles A, B, C; doubles A + B simultaneous and C + C rafale (at such a stand two doubles on report are not allowed).", "In Compak® Sporting a menu is shown at each of the five stations. Each station has five targets: five singles, three singles and a double, or one single and two doubles. The type of double is the same at all five stations of a Compak, and the first target of each double is the last target of the previous station. FITASC offers 40 ready-made menus for competitions.", "Before your shooter steps up, read the menu aloud to them in their language, letter by letter: 'A, then F, then the pair C and E on report.'"], "key_points": ["Keep the word 'menu'.", "Sporting™ menu: traps in order plus special targets (90, 70, 60 mm, battue, rabbit).", "15 singles + 5 doubles; doubles use targets already shown as singles; singles first.", "Doubles: on report, simultaneous, rafale (Sporting™ only).", "Compak®: five targets per station, same double type on all stations, each double starts with the previous station's last target."], "terms": ["target-menu", "single-target", "double", "double-on-report", "simultaneous-double", "rafale-double"], "sources": [{"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch2-doubles-three-traps", "label": "2 · Doubles at a position with 3 machines"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-annex3-tables", "label": "17 · The 40 pre-established trajectory setting tables"}], "coach_says": [{"en": "Read the menu: on station three you have A, then F, then the pair C and E on report.", "meaning": "The order of targets at station 3, ending with a double on report.", "say": null}, {"en": "Same traps, new menu — don't shoot from memory.", "meaning": "The order has changed since the last round.", "say": null}, {"en": "Three singles, then a simo pair.", "meaning": "'Simo' is short for a simultaneous double.", "say": null}], "quiz": [{"q": "Which special targets must a Sporting™ menu show?", "options": ["Only the colours of the targets", "90 mm, 70 mm, 60 mm, battue or rabbit", "Only rabbits and battues", "None; the referee announces them"], "answer": 1, "why": "The menu must list the traps in order and any special target types."}, {"q": "In Compak® Sporting, with which target does each double start?", "options": ["Always trap A", "A target never seen before", "The last target shot at the previous station", "Any target the shooter chooses"], "answer": 2, "why": "The doubles chain across stations: each begins with the last target of the station before."}, {"q": "Which type of double exists only in Sporting™?", "options": ["Rafale", "On report", "Simultaneous", "None"], "answer": 0, "why": "Compak® doubles are on report or simultaneous; rafale is a Sporting™ double."}]}, {"id": "targets-hit-or-lost", "minutes": 5, "title": "Hit or lost: the visible piece and the 'smoke' trap", "body": ["A target is scored 'one' (a hit, «влучання») when it was properly thrown, the shooter fired by the rules, and at least one piece visibly broke off, or the target was wholly or partly destroyed. Flash targets follow the same rule. A target is 'zero' (lost, «промах») when no visible piece comes off and there is only dust or smoke.", "So the rule turns on one picture: a visible piece. A small chip that flies off counts as a hit. A puff of dust with the target flying on in one piece is lost. On the score sheet a hit is usually marked X and a miss O.", "Only the referee decides. Squad members may not give opinions, and nobody may pick up a target to check it. In Compak® Sporting the referee announces every zero loudly or with a sound signal. In Parcours de Chasse – Sporting™ the shooter must break targets where the referee can see them. By calling the next target the shooter accepts the decision on the previous one, so any objection must come at once.", "Now the trap for interpreters. Coaches praise a perfect hit with 'smoked it', 'inked it' or 'powdered it': the target turned into a black cloud. That is the best possible hit, not a zero. But in the rules, 'only dust or smoke' means lost. 'Dusted it' is risky: it usually means only dust came off, a lost target, but some speakers use it as praise. If you are not sure, ask, because the two meanings are opposite.", "Also: 'dead' means a hit (not «мертва»), 'lost' a miss (not «загублена»)."], "key_points": ["One = at least one visible piece broke off, or the target was wholly or partly destroyed.", "Zero = no visible piece, only dust or smoke.", "Only the referee decides; no picking up targets; calling the next target accepts the decision.", "Coach slang 'smoked it' = perfect hit; rule wording 'only smoke' = lost.", "'Dead' = hit, 'lost' = miss; ask if 'dusted' is unclear."], "terms": ["one", "zero", "visible-piece", "referee", "score-sheet", "smoked-it", "chip"], "sources": [{"title": "Midvalley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "Smoked it! That's the picture.", "meaning": "A perfect hit: the target turned to dust; the shooter should remember that sight picture.", "say": null}, {"en": "Dead — only a chip, but it counts.", "meaning": "A small visible piece broke off, so it is a hit.", "say": null}, {"en": "Lost — you were just behind it.", "meaning": "A miss; the shot went behind the target.", "say": null}, {"en": "Don't argue with me later — say it now, before you call.", "meaning": "An objection must be made at once; calling the next target accepts the ruling.", "say": null}], "quiz": [{"q": "The target flies on whole, but a puff of dust appears. What is the score?", "options": ["Zero (lost)", "One (hit)", "No Bird", "Half a point"], "answer": 0, "why": "Only dust or smoke, with no visible piece, is lost."}, {"q": "A coach shouts 'Smoked it!' How do you translate the meaning?", "options": ["It only smoked, so the target is lost", "The barrels are overheating", "A perfect hit: the target turned to dust", "The trap machine is on fire"], "answer": 2, "why": "In coach slang 'smoked it' is praise for a total break; the rule wording 'only smoke' means the opposite."}, {"q": "A squad member says the last target was hit. Who decides?", "options": ["A vote of the squad", "The coach", "The interpreter", "The referee alone"], "answer": 3, "why": "Target decisions belong to the referee; squad members may not intervene."}]}]}, {"id": "flight", "icon": "trajectory", "title": "How targets fly (presentations)", "intro": "Coaches name every target by how it flies: crosser, incomer, teal, looper, rabbit, report pair. In six short lessons you will learn what each name means, what the shooter has to do with it and which words are easy to mistranslate.", "lessons": [{"id": "flight-crosser", "minutes": 5, "title": "The crosser: a target flying across", "body": ["A crosser flies across in front of the shooter, roughly at a right angle to the line of sight: left to right (written L→R) or right to left (R→L). On a Parcours de Chasse – Sporting™ layout the rules ask for a mix of crossing, quartering, incoming and going-away targets. In Compak® Sporting a left-to-right and a right-to-left crosser are two of the three compulsory trajectories, so every Compak has them.", "A crosser shows you its full sideways speed, so it needs the most lead (forward allowance) of all presentations, and the further away it is, the more lead it needs. A “long crosser” means a far one, not one that flies for a long time.", "Read its line and speed: does it fly flat, climb, or already drop at the break point? Does it show its face (the dome or the belly) or only its edge? Does it slow down? A slowing crosser needs less lead than one at full speed.", "Typical plan: feet set to the break point, eyes picking it up early, then pull-away or maintained lead, with the gun still moving at the shot. A very common coach's verdict on a crosser is “behind”: not enough lead, or a gun that stopped.", "Directions are given from the shooter's point of view. If you stand facing the shooter, their “left to right” is your right to left, so never turn the words round."], "key_points": ["A crosser flies across at about 90° to the line of sight: L→R or R→L.", "It needs the most lead; more distance means more lead.", "“Long crosser” = far away, not long-lasting.", "Compak® Sporting always has an L→R and an R→L crosser.", "Left and right are always from the shooter's point of view."], "terms": ["crosser", "lead", "trajectory", "target-line", "break-point", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["crosser-rl"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}], "coach_says": [{"en": "Long crosser, right to left — trust the lead and keep the gun moving.", "meaning": "The target is far away and flies from the shooter's right to left; give it the planned lead and do not stop the swing.", "say": null}, {"en": "You're behind it — give it more.", "meaning": "The shot passed behind the target: more lead is needed.", "say": null}, {"en": "It's dropping at your break point — stay under the line.", "meaning": "Where the shooter breaks it, the crosser is already falling, so the gun must travel slightly below its path.", "say": null}, {"en": "Pick it up early, it's quick off the trap.", "meaning": "Look for the target closer to the trap than usual, because it leaves the trap fast.", "say": null}], "quiz": [{"q": "Which presentation usually needs the most lead?", "options": ["A target going straight away", "An incomer flying straight at the shooter", "A crosser at the same distance", "A rabbit rolling straight away"], "answer": 2, "why": "A crosser shows its full sideways speed, so the gun must be furthest in front; straight-line targets need little sideways lead."}, {"q": "The coach says “long crosser”. What does “long” mean?", "options": ["The target is far away", "The target flies for a long time", "The target is a long, oval clay", "The shooter should wait a long time"], "answer": 0, "why": "In coaching “long” describes distance. A long crosser is a far crosser, which needs more lead."}, {"q": "What is true of crossers in Compak® Sporting?", "options": ["Crossers are not allowed on a Compak", "Only right-to-left crossers are allowed", "Crossers may only be thrown as rabbits", "An L→R and an R→L crosser are compulsory"], "answer": 3, "why": "The Compak® Sporting rules make three trajectories compulsory: an L→R crosser, an R→L crosser and a going-away target."}]}, {"id": "flight-incomer-going-away", "minutes": 5, "title": "Incomer, going-away, driven and overhead", "body": ["An incomer flies towards the shooter, often from a distant trap or a tower, and usually drops as it comes. It can seem to slow down and hang, which tempts shooters to aim. It is normally taken out in front, before it gets overhead, and the barrels may cover (“blot out”) the target at the shot. That is intended, not a fault.", "A going-away target leaves from near or behind the shooter and flies away. It needs little sideways lead, but it shrinks fast and often rises or drops, so the lead is mostly vertical and timing matters: do not wait. In Compak® Sporting a going-away target over side BC is compulsory; it may come from a trench in front or from a tower behind the stations, at least 4 m above them.", "A driven target is an incomer that passes over the shooter's head, like a pheasant pushed by beaters. Pick it up early, move with it, swing up from behind through it, fire as the barrels cover it and keep swinging. Careful: French “en battue” (Italian “in battuta”) means driven game, not the battue target.", "An overhead from behind comes over the shooter's back and goes away. It is seen late, so the shooter looks back for it early, mounts with it, fires as the muzzle touches its front and follows through.", "“Incoming” and “going away” always describe the target relative to the shooter."], "key_points": ["Incomer: comes towards the shooter, usually dropping; take it in front.", "Going-away: little sideways lead, mostly vertical; shoot promptly.", "Driven: an incomer over the head; swing through from behind and cover it.", "Overhead from behind: look back early, mount with it, follow through.", "Compak® Sporting always includes a going-away target."], "terms": ["incomer", "going-away", "driven-target", "overhead", "tower", "follow-through"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "ShotKam — Master incomers", "url": "https://shotkam.com/blogs/blog-collections/master-incomers"}, {"title": "Sporting Gun — How to shoot going-away targets", "url": "https://sporting-gun.com/shooting/how-to-shoot-going-away-targets/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "flight", "preset": "incomer", "also": ["going-away", "overhead"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch2-trap-placement", "label": "2 · Where traps may be placed; tower"}], "coach_says": [{"en": "Take it out in front, before it gets on top of you.", "meaning": "Break the incomer while it is still in front, not when it is overhead.", "say": null}, {"en": "Blot it out and keep swinging.", "meaning": "Let the barrels cover the target at the shot and do not stop the gun.", "say": null}, {"en": "Don't wait on the going-away — it's getting smaller.", "meaning": "Shoot the going-away target promptly, because it is quickly getting further away.", "say": null}, {"en": "It comes from behind you — look back for it early.", "meaning": "It is an overhead from behind; turn the eyes towards it before calling.", "say": null}], "quiz": [{"q": "The coach says: “Blot it out.” What should the shooter do?", "options": ["Wipe the lenses of the safety glasses", "Let the barrels cover the target at the shot", "Wait until the target disappears from view", "Shoot only at the falling pieces"], "answer": 1, "why": "On incomers, driven and rising targets the gun often covers the clay at the moment of the shot; the coach asks for exactly that."}, {"q": "Why should a going-away target not be left too long?", "options": ["It quickly gets further away and smaller", "The rules allow only three seconds", "It always turns into a crosser", "The referee calls No Bird after the peak"], "answer": 0, "why": "A going-away target gains distance fast, so the longer you wait, the harder it becomes. Three seconds is the release time, not a shooting limit."}, {"q": "What makes a driven target different from an ordinary incomer?", "options": ["It is always a rabbit", "It comes from behind the shooter", "It passes over the shooter's head", "It is thrown only in Compak® Sporting"], "answer": 2, "why": "Driven means an incomer that comes over the head, like driven game. A target coming from behind is an overhead from behind."}]}, {"id": "flight-quartering", "minutes": 5, "title": "Quartering targets: away and towards", "body": ["A quartering target flies at an angle: partly crossing, partly going away or coming in. Quartering away moves away from the shooter at an angle, for example out to the front right. Quartering towards (also “quartering in”) comes towards the shooter at an angle and passes to one side or drops in front. The angle is often around 45°, but anything between a straight target and a full crosser is possible.", "The lead depends on the angle: more than for a straight going-away target, less than for a full crosser. A sharp angle needs little lead, an almost crossing one nearly as much as a crosser.", "Quartering away gets smaller and slower quickly, so take it promptly. Pull-away suits it well, because the gun stays on the target's line. Quartering towards grows bigger and looks slow, which tempts the shooter to wait; it can then pass too close or drop out of sight.", "The same trap gives different presentations from different stands: from one stand a target is a crosser, from the next it is quartering. That is why targets must be read from the exact stand the shooter will use.", "In Ukrainian say «коса від стрільця» and «коса на стрільця» (or «навскіс від стрільця / на стрільця»). A literal word built from “quarter” means nothing to a shooter."], "key_points": ["Quartering = flying at an angle, between straight and crossing.", "Quartering away moves off at an angle; quartering towards (in) comes in at an angle.", "Lead grows with the angle: less than a crosser, more than a straight target.", "One trap looks different from each stand: read it from your own stand.", "Ukrainian: «коса від стрільця / на стрільця»."], "terms": ["quartering-away", "quartering-towards", "crosser", "going-away", "lead", "pull-away"], "sources": [{"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "flight", "preset": "quartering-away", "also": ["quartering-towards"]}, "rule_refs": [{"book": "sporting", "id": "ch2-layout", "label": "2 · What a layout must offer"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "The first one's quartering away to the left — take it quickly before it gets small.", "meaning": "The first target moves away at an angle to the shooter's left; break it early.", "say": null}, {"en": "Quartering in from the right — don't let it get too close.", "meaning": "The target comes towards the shooter at an angle from the right; do not wait for it.", "say": null}, {"en": "Less lead than you think — it's only a slight angle.", "meaning": "The target is nearly straight, so it needs only a small lead.", "say": null}], "quiz": [{"q": "A target comes towards the shooter at an angle and passes to the side. What is it called?", "options": ["Going-away", "Quartering towards", "Teal", "Rafale"], "answer": 1, "why": "Quartering towards (or quartering in) is an angled target coming in; quartering away is the angled target moving off."}, {"q": "How does the lead on a quartering target compare with a full crosser at the same distance and speed?", "options": ["It is the same as the crosser", "It is always zero", "It is larger than the crosser", "It is smaller, depending on the angle"], "answer": 3, "why": "Only the sideways part of the movement needs sideways lead, so the sharper the angle, the smaller the lead."}, {"q": "Why should a target be read from the exact stand you will shoot from?", "options": ["One trap can be a crosser from one stand, quartering from another", "The rules forbid watching from any other place", "Targets change colour from one stand to the next", "Only the referee may stand anywhere else"], "answer": 0, "why": "The angle between the shooter and the target's line changes with the position, so the presentation changes too."}]}, {"id": "flight-teal-chandelle-looper", "minutes": 6, "title": "Teal, chandelle, looper and dropping targets", "body": ["These presentations are about height and curve rather than angle. Their names are course-setters' words, not rulebook terms: the rules list target types, and the Compak® Sporting rules ask for varied trajectories, such as rising, dropping and lofted ones.", "A teal (springing or rising teal, after the small duck) is thrown almost straight up, slows, stalls at the top and falls back. It is taken either on the way up, swinging up through it from below, or at the peak while it stalls. Poking at it at the top is the classic fault. Some setters use 'springing' for a target that climbs at an angle rather than straight up, like a flushed bird.", "A chandelle (French for “candle”) rises steeply on a slight curve, arcs over and drops almost vertically. It is easiest on the way up; on the curl the lead goes to the side and below.", "A looper flies a wide arc across the sky, like a rainbow, often a battue thrown from a tilted trap: it climbs, turns its face and falls. The gun follows the curve, in front and underneath.", "A dropping target is any target in the falling part of its flight. The lead is partly vertical: underneath and in front, with the gun moving.", "Careful: names vary between countries. Many French speakers use “chandelle” for a target that goes almost straight up, which an English coach calls a teal, and Ukrainian shooters may say «свічка» for either. Whenever you hear chandelle, candle or «свічка», ask: straight up or arcing over?"], "key_points": ["Teal: almost vertical up, stalls, falls; take it rising or at the peak.", "Chandelle: steep curving climb, arcs over, drops almost vertically.", "Looper: wide rainbow arc across, often a battue that turns and falls.", "Dropping: lead underneath and in front, never stop the gun.", "Names vary: French speakers often say “chandelle” for a teal; «свічка» is ambiguous too, so clarify."], "terms": ["teal", "springing-target", "chandelle", "looper", "dropping-target", "battue"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "Shotgun Life — How to shoot a chandelle target", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}, {"title": "ShotgunWorld — Target terminology (forum)", "url": "https://www.shotgunworld.com/threads/target-terminology.477902/"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}], "sim": {"type": "flight", "preset": "teal", "also": ["chandelle", "looper", "dropping"]}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "compak", "id": "ch3-targets", "label": "3 · Target types and colour"}], "coach_says": [{"en": "Take the teal on the way up — keep the barrels moving above it.", "meaning": "Break the rising teal before the peak; the gun keeps rising past it.", "say": null}, {"en": "Don't poke at it on the top.", "meaning": "Do not stop and aim at the target while it stalls at the peak.", "say": null}, {"en": "The looper's turning over — underneath and in front.", "meaning": "The target is rolling over the top of its arc and starting to fall; the lead goes below and ahead of it.", "say": null}, {"en": "Second bird's dropping — go under it and keep the gun moving.", "meaning": "The second target of the pair is falling; shoot below it with the gun in motion.", "say": null}], "quiz": [{"q": "Which target is thrown almost straight up, stalls at the top and falls back?", "options": ["Looper", "Quartering away", "Rabbit", "Teal"], "answer": 3, "why": "That is the teal (springing or rising teal). A looper flies a wide arc across the sky."}, {"q": "Where does the lead usually go on a dropping target?", "options": ["Above and behind", "Underneath and in front", "Straight at the target", "Only to the side, never down"], "answer": 1, "why": "A falling target moves down as well as along, so part of the lead is vertical: below and ahead."}, {"q": "A French-speaking coach says “chandelle”. What is the safest thing to do?", "options": ["Check: straight up, or an arc over the top?", "Always translate it as the English looper", "Always translate it as the English teal", "Ignore it, since it is not a rulebook term"], "answer": 0, "why": "French speakers often mean an almost vertical target (an English teal), while an English setter’s chandelle climbs on a curve and arcs over; a quick check avoids a wrong plan."}]}, {"id": "flight-rabbit", "minutes": 5, "title": "The rabbit: rolling, hopping and bolting", "body": ["A rabbit is a 110 mm target with a thick, strong rim, thrown on its edge so that it rolls along the ground like a running hare. It is a special target, so in Parcours de Chasse – Sporting™ it must be shown on the target menu of the stand.", "Coaches describe how it runs: a rolling rabbit runs smoothly; a hopping (bouncing) rabbit jumps on bumps and stones; a bolting rabbit bursts out of cover and runs fast. Rabbits can go across, towards or away from the shooter.", "A rabbit is heavy and slows quickly, so shooters often over-lead it. Coaches ask to keep the muzzle low and shoot the bottom front edge, so that a sudden hop still meets the shot. Often it is visible only in a short gap between bushes, so the break point must be planned exactly.", "Rules: every target, rabbits included, is shot with the gun at the shoulder; firing from the hip is not allowed in either discipline. A special case: if the first shot misses and the rabbit then breaks by itself, for example on a stone, before the second shot, it is a No Bird. On the repeat only a break with the second shot counts.", "“Fur and feather” is English Sporting slang for a pair of a rabbit (“fur”) and an aerial target (“feather”). In Ukrainian you will hear «кролик» or «заєць»; this course uses «кролик»."], "key_points": ["Rabbit: 110 mm, thick rim, rolls on its edge along the ground.", "Rolling, hopping (bouncing), bolting: describe how it runs.", "It slows quickly: do not over-lead; keep the muzzle low.", "Always shot from the shoulder; a rabbit that breaks by itself after a first-shot miss is a No Bird.", "“Fur and feather” = rabbit + aerial target pair."], "terms": ["rabbit", "bolting-rabbit", "fur-and-feather", "target-menu", "no-bird", "break-point"], "sources": [{"title": "Shotgun Life — Mastering the elusive rabbit clay target", "url": "https://www.shotgunlife.com/briefs/mastering-the-elusive-rabbit-clay-target.html"}, {"title": "Gun Tests — Rabbit target clay shooting", "url": "https://www.gun-tests.com/recreational/rabbit-target-clay-shooting/"}, {"title": "Shooting UK — Clay pigeon sizes", "url": "https://www.shootinguk.co.uk/shooting/shotgun/clay-pigeon-sizes-knowing-what-they-are-will-help-you-to-improve-your-score/"}], "sim": {"type": "flight", "preset": "rabbit"}, "rule_refs": [{"book": "sporting", "id": "ch2-targets", "label": "2 · Permitted target types and colours"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch6-nobird-target-single-rabbit", "label": "6 · Target No Bird on a single and on a rabbit"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}], "coach_says": [{"en": "It hops on that bump — stay under it and keep moving.", "meaning": "The rabbit jumps at a known spot; keep the gun low and moving.", "say": null}, {"en": "Shoot its feet.", "meaning": "Put the shot on the bottom edge of the rabbit, not over it.", "say": null}, {"en": "It slows down a lot — less lead than you think.", "meaning": "The rabbit loses speed quickly, so it needs a smaller lead.", "say": null}, {"en": "Fur and feather: rabbit first, before it reaches the bushes.", "meaning": "In the rabbit-plus-bird pair, shoot the rabbit first because it disappears into cover.", "say": null}], "quiz": [{"q": "The first shot misses a rabbit, then it breaks on a stone before the second shot. What happens?", "options": ["It is scored as a hit, since it broke", "It is scored zero for the first miss", "No Bird: repeated, only a second-shot break counts", "The shooter just moves to the next target"], "answer": 2, "why": "Both rulebooks treat this as a No Bird; on the repeat the shooter must deliberately miss with the first shot."}, {"q": "Why do coaches warn against too much lead on a rabbit?", "options": ["The rules limit the lead", "It is heavy and slows quickly", "It always flies upwards", "It is smaller than a mini"], "answer": 1, "why": "A rabbit has a thick rim and rolls on the ground, losing speed fast, so the usual crosser lead puts the shot in front."}, {"q": "What does “fur and feather” mean?", "options": ["A pair of a rabbit and an aerial target", "A hunting dress code", "A target with feathers glued on", "A pair of two rabbits"], "answer": 0, "why": "In English Sporting slang “fur” is the rabbit and “feather” the flying target."}]}, {"id": "flight-pairs", "minutes": 6, "title": "Singles and pairs: report, rafale, simultaneous", "body": ["A single is one target from one trap. In both disciplines two shots may be fired at it, so a miss can be saved with the second barrel. A pair, or double, is two targets shot as one unit after one call.", "Report pair (double on report): the call releases the first target, and the shot at it releases the second. In Parcours de Chasse – Sporting™ the second comes 0 to 3 seconds after that shot. The order is fixed. “Report” means the sound of the shot, not a written report.", "Following pair, which FITASC calls rafale: two targets from the same trap on the same line, the second as fast as the trap reloads; either may be shot first. It exists only in Sporting™: a Compak® Sporting double is on report or simultaneous.", "Simultaneous pair (“simo”; English Sporting “true pair”): both targets leave at the same moment, from one or two traps (in Compak® Sporting always from two different traps), and may be shot in any order.", "Cartridges: in Sporting™ there are two for the pair and both may go at one target; if one shot breaks both, both count. In Compak® Sporting only one cartridge per target is allowed, and both shots at one target score zero-zero; one shot breaking both targets is not simply scored twice either (the Compak® mission explains it).", "On a Sporting™ stand the squad shoots the singles first, then the doubles. Simultaneous and rafale doubles are shown before shooting; report pairs are not."], "key_points": ["Single: one target, two shots allowed.", "Report pair: the shot at the first releases the second; order fixed.", "Rafale (following pair): same trap, same line, Sporting™ only.", "Simultaneous (true pair): both at once, any order.", "Sporting™: both cartridges may go at one target; Compak® Sporting: one per target."], "terms": ["single-target", "double", "double-on-report", "rafale-double", "simultaneous-double", "true-pair", "target-presentation"], "sources": [{"title": "CPSA — English Sporting (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "flight", "preset": "crosser-lr", "also": ["teal"], "pairs": ["report", "simultaneous", "rafale"]}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}], "coach_says": [{"en": "It's on report — finish the first one properly, the second waits for your shot.", "meaning": "The second target only comes when the shooter fires at the first, so there is no need to rush the first.", "say": null}, {"en": "Simo: take the rabbit first, the teal will wait for you.", "meaning": "In the simultaneous pair shoot the rabbit first, because the teal stays in the air longer.", "say": null}, {"en": "Rafale — after the first, come straight back to the trap for the second.", "meaning": "Both targets come from the same trap; after the first shot, return eyes and gun towards the trap to pick up the second.", "say": null}, {"en": "True pair from the tower, five of them.", "meaning": "Five simultaneous pairs thrown from the tower (English Sporting wording).", "say": null}], "quiz": [{"q": "In a report pair, what releases the second target?", "options": ["A second call", "The referee's signal", "The shot at the first target", "A timer of exactly 5 seconds"], "answer": 2, "why": "“On report” means on the sound of the shot: firing at the first target releases the second."}, {"q": "A shooter fires both cartridges at the first target of a simultaneous double in Compak® Sporting. Result?", "options": ["Allowed, as in Sporting™", "Zero-zero", "No Bird and repeat", "Only the second target is zero"], "answer": 1, "why": "Compak® Sporting allows one cartridge per target of a double; deliberately firing both at one target is scored zero-zero. In Sporting™ it would be allowed."}, {"q": "A British coach says “true pair”. How do you translate it?", "options": ["A correct, fair pair", "A pair of real birds", "A rafale", "A simultaneous pair"], "answer": 3, "why": "“True pair” is the English Sporting name for a simultaneous pair; “true” has nothing to do with correctness."}]}]}, {"id": "basics", "icon": "stance", "title": "Fundamentals of a shot", "intro": "Before any talk about lead, a coach fixes the basics: feet, gun mount, eyes, a three-point plan and a gun that keeps moving. These five lessons give you the coach's words for each step and the rules that limit what the shooter may do.", "lessons": [{"id": "basics-stance", "minutes": 5, "title": "Stance: feet to the break point", "body": ["The stance is how the shooter stands before the shot. The space is small: in Parcours de Chasse – Sporting™ the stand is a 1 m square or circle, and both feet must be inside it before the call. In Compak® Sporting each station is a 1 m square with a Firing Angle Limiter, a frame that stops the shooter stepping forward and limits the swing.", "The usual base: feet about shoulder-width apart; for a right-hander the left foot slightly forward (a left-hander mirrors this); knees soft, not locked; weight slightly forward, roughly 60 per cent on the front foot. Coaches say “nose over toes”.", "The key instruction: point the front foot at the break point, where the shooter plans to break the target. The body is then comfortable, “unwound”, exactly where the shot happens. The shooter turns back from the hips to the hold point and unwinds into the shot. If the feet face the trap, coaches warn, the body runs out of turn, and the gun stops or the head lifts.", "The body turns from the hips, not the arms. Feet may be set slightly differently for every target.", "Translate “front foot” and “back foot” as front and back, not left and right: your shooter may be left-handed."], "key_points": ["Sporting™: both feet inside the 1 m stand before the call.", "Compak® Sporting: 1 m station with a Firing Angle Limiter.", "Feet shoulder-width, knees soft, weight slightly forward.", "Front foot points at the break point; turn back from the hips to the hold point.", "Translate front/back foot, not left/right."], "terms": ["stance", "shooting-stand", "break-point", "hold-point", "firing-angle-limiter"], "sources": [{"title": "NSSA-NSCA — Stance and foot position (blog)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "Shotgun Life — Best foot position for clays shooting", "url": "https://www.shotgunlife.com/briefs/best-foot-position-for-clays-shooting.html"}, {"title": "Positive Shooting — Stance", "url": "http://www.positiveshooting.com/StanceMain.html"}], "sim": {"type": "flight", "preset": "crosser-lr", "focus": "stance"}, "rule_refs": [{"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}], "coach_says": [{"en": "Point your front foot at the break point.", "meaning": "Turn the toe of the front foot towards the place where the target will be broken.", "say": null}, {"en": "Set your feet for the break, then wind back to the hold.", "meaning": "First place the feet for the break point, then turn the upper body back to the hold point.", "say": null}, {"en": "Weight forward, soft knees.", "meaning": "Lean slightly onto the front foot and do not lock the knees.", "say": null}, {"en": "Turn from the hips, not the arms.", "meaning": "The whole upper body rotates; the arms do not swing the gun on their own.", "say": null}], "quiz": [{"q": "Where does the coach usually want the front foot to point?", "options": ["At the trap", "At the pick-up point", "At the referee", "At the break point"], "answer": 3, "why": "Feet set to the break point leave the body comfortable where the shot happens; feet facing the trap make the body run out of turn."}, {"q": "What do the Parcours de Chasse – Sporting™ rules require of the feet before the call?", "options": ["Both feet inside the stand", "The front foot on the stand line", "Feet together", "No requirement at all"], "answer": 0, "why": "The ready-position rule asks for both feet inside the 1 m shooting stand before the shooter calls."}, {"q": "A left-handed shooter. The coach says “Open your front foot”. Which foot is it?", "options": ["Always the left one, whatever the hand", "The right one: a left-hander's front foot", "The back foot, nearer the trap", "Both feet together"], "answer": 1, "why": "For a left-hander the front foot is the right one. Translating “front foot” as «передня нога» avoids the mistake."}]}, {"id": "basics-mount", "minutes": 6, "title": "Ready position and gun mount", "body": ["In Parcours de Chasse – Sporting™ the start is gun-down. Before calling, the heel of the stock touches the body and the top rear of the stock stays below a line on the vest, 25 cm under the shoulder axis, in a contrasting colour. The shooter holds this until the target is released and visible. Mounting earlier earns a verbal warning with a yellow card; a repeat on the same layout brings a red card and the target is scored zero.", "In Compak® Sporting the gun position at the call is free, so the gun may already be shouldered. In both disciplines every target is shot with the gun at the shoulder, and in Sporting™ the gun position is free between the two targets of a double.", "The gun mount (Ukrainian «вкидка») brings the gun to cheek and shoulder. Coaches teach “muzzles first”: the front hand starts the muzzles moving along the target's line, the stock rises to the cheek and settles into the shoulder pocket as the gun catches the line. “Move, mount, shoot” is one smooth flow. The gun comes to the face, not the face to the gun; the cheek stays on the comb, because the eye is the rear sight.", "A British coach may say “gun up” or “pre-mount this one”. That is illegal in a FITASC Sporting™ competition, normal in Compak® Sporting, and only a drill in training. Mounting and swinging along an imagined line before calling (mock shooting) is forbidden in Sporting™: a warning first, then a zero."], "key_points": ["Sporting™: stock below the vest line (25 cm under the shoulder axis) until the target is visible.", "Early mount: yellow card, then red card and a lost target on the same layout.", "Compak® Sporting: free gun position at the call; always shoot from the shoulder.", "Muzzles first, gun to face, cheek on the comb: move, mount, shoot.", "“Pre-mount” is a training drill, never in a FITASC Sporting™ competition."], "terms": ["ready-position", "jacket-line", "gun-mount", "move-mount-shoot", "comb", "yellow-card", "mock-shooting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-lr", "focus": "mount"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Gun to your face, not your face to the gun.", "meaning": "Lift the stock to the cheek; do not drop the head to meet the gun.", "say": null}, {"en": "Muzzles first — move, mount, shoot.", "meaning": "Start the barrels moving with the target, mount during the move, fire as the mount is complete.", "say": null}, {"en": "Your mount's late and too fast — start it with the front hand.", "meaning": "The gun comes up too late and with a jerk; the front hand should lead the movement earlier.", "say": null}, {"en": "Low gun on this one, like in competition.", "meaning": "Start with the stock below the vest line, as the FITASC Sporting™ rules require.", "say": null}], "quiz": [{"q": "In Parcours de Chasse – Sporting™, until when must the stock stay below the vest line?", "options": ["Until the shooter has called", "Until the referee gives a nod", "Until the target is out and visible", "Until the first shot is fired"], "answer": 2, "why": "The ready position is held until the target has been released and can be seen; only then may the gun be mounted."}, {"q": "In Compak® Sporting, may a shooter call for the target with the gun already at the shoulder?", "options": ["No: it earns a yellow card", "Only for rabbits and other low targets", "Only between the two targets of a double", "Yes: the gun position at the call is free"], "answer": 3, "why": "Compak® Sporting has no low-gun rule: the gun may be mounted or not at the call, but every target is shot from the shoulder."}, {"q": "Why do coaches insist on the cheek staying on the comb?", "options": ["The eye is the rear sight, so it must sit in one place", "To reduce the noise reaching the ear", "Because the rules of both disciplines require it", "To hide the face from the referee"], "answer": 0, "why": "A shotgun has no rear sight: the eye over the rib is the sight, so a lifted cheek sends the shot high."}]}, {"id": "basics-eyes", "minutes": 5, "title": "Eyes: dominance, both eyes open, hard focus", "body": ["Most people have a dominant (master) eye that the brain trusts more, usually on the same side as the dominant hand. The dominant eye must be the one looking along the rib. Cross-dominance means the dominant eye is on the other side from the shooting shoulder; central vision means neither eye clearly dominates. Either makes the gun point where the shooter does not expect, often to one side.", "A simple test: with both eyes open, frame a distant object in a small triangle made with the hands, then close each eye in turn; the eye that keeps the object in the triangle is dominant. A coach may also stand in front of the shooter and look through the triangle.", "Remedies chosen by the coach: close or squint the other eye as the gun mounts; a small dot on the safety glasses; learning to shoot from the other shoulder; or, more rarely, a cross-over stock. Both eyes open is preferred where possible, because two eyes judge speed, angle and distance better.", "Focus: a soft, wide focus while waiting at the pick-up point, then a hard focus on the target itself, ideally its leading edge. Looking back at the barrel or bead to check the lead stops the gun.", "Safety glasses are compulsory for shooters in both disciplines, so the dot goes on them."], "key_points": ["The dominant eye must look along the rib.", "Cross-dominance and central vision make the gun point off target.", "Test with a hand triangle; the coach chooses the remedy.", "Soft focus at pick-up, hard focus on the leading edge; never look back at the bead.", "Safety glasses are compulsory in both disciplines."], "terms": ["eye-dominance", "master-eye", "cross-dominance", "central-vision", "soft-focus", "hard-focus", "leading-edge", "safety-glasses"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "Paragon School — Eye dominance testing", "url": "https://www.paragonschool.com/blog-post/eye-dominance-testing-and-issues-in-sporting-clays-skeet-and-trap-go-slowly-please"}, {"title": "Shotgun Life — How to shoot a chandelle target (focus on the leading edge)", "url": "https://www.shotgunlife.com/briefs/how-to-shoot-a-chandelle-target.html"}], "sim": {"type": "flight", "preset": "going-away", "focus": "eyes"}, "rule_refs": [{"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}], "coach_says": [{"en": "Close your left eye as the gun comes up.", "meaning": "Shut the left eye during the mount, not before, so the right eye controls the gun.", "say": null}, {"en": "Eyes on the clay, not the barrel.", "meaning": "Keep looking at the target; checking the barrel stops the gun.", "say": null}, {"en": "Look at the leading edge.", "meaning": "Focus on the front edge of the moving target, not its middle.", "say": null}, {"en": "Don't look at the trap — look out to your pick-up point.", "meaning": "Wait with the eyes a little out along the line, where the target is first seen clearly.", "say": null}], "quiz": [{"q": "A right-handed shooter has a left dominant eye. What is this called?", "options": ["Central vision", "Hard focus", "Cross-dominance", "Leading edge"], "answer": 2, "why": "Cross-dominance is a dominant eye on the opposite side to the shooting shoulder."}, {"q": "Why is looking back at the bead to check the lead a fault?", "options": ["It is forbidden by the rules", "It stops the gun and the shot goes behind", "The bead reflects the sun", "It makes the target change colour"], "answer": 1, "why": "When the focus moves to the gun, the swing stops and the target becomes peripheral, so the shot goes behind."}, {"q": "Where does the anti-dominance dot usually go?", "options": ["On the safety glasses, before the eye to block", "On the bead at the end of the rib", "On the rib, halfway along it", "On the vest line, below the shoulder"], "answer": 0, "why": "Safety glasses are compulsory anyway, so a small dot on the lens in front of the non-dominant eye is the simplest remedy."}]}, {"id": "basics-three-points", "minutes": 5, "title": "Pick-up, hold and break point: planning a stand", "body": ["Before every target the shooter sets three points. The pick-up point is where the eyes first see the target clearly, a little out from the trap rather than at its mouth, where the clay is only a blur. The hold point is where the muzzles wait at the call, usually on or just under the target's line, between the pick-up point and the break point. The break point is where the shooter plans to break the target.", "Planning order: choose the break point first, set the feet to it, wind back to the hold point, then put the eyes on the pick-up point. In Parcours de Chasse – Sporting™ the stock is down until the target appears, so the hold point there means where the muzzles point while the gun is low.", "Typical errors: a break point too far away means a fast, uncontrolled swing or a target already dropping; too close means too little movement and a “poke”. A hold point too near the trap makes the gun chase; too far out and the target overtakes the gun.", "Targets are read during the presentation. In Sporting™ all trajectories are shown to the first shooter, and on request the referee repeats the presentation, up to two targets for each target of the menu; in squad Compak® Sporting the singles are shown once in the morning, for the first squad. The target must be broken where the referee can see it, inside the shooting limit.", "“Where are you taking it?” asks for the break point; “kill point” is a neutral synonym."], "key_points": ["Pick-up = eyes; hold = muzzles; break = where the target is broken.", "Plan from the break point backwards: feet, hold, eyes.", "The hold point is usually between pick-up and break, on or just under the line.", "Read targets during the presentation; break them where the referee can see.", "“Where are you taking it?” = where is your break point?"], "terms": ["pick-up-point", "hold-point", "break-point", "target-presentation", "shooting-limit", "target-line"], "sources": [{"title": "Shotgun Life — The proper hold point for sporting clays", "url": "https://www.shotgunlife.com/briefs/what-is-the-proper-hold-point-for-shooting-sporting-clays.html"}, {"title": "Clay Target Instruction — Hold point", "url": "https://claytargetinstruction.com/articles/hold-point/"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "Shotgun Sports USA — How to read sporting clays targets", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "flight", "preset": "quartering-away", "focus": "points"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}], "coach_says": [{"en": "Where are you taking it?", "meaning": "The coach asks where the shooter plans to break the target.", "say": null}, {"en": "Move your hold point halfway back to the trap.", "meaning": "Hold the muzzles closer to the trap, at half of the current distance.", "say": null}, {"en": "Look further out — pick it up where it's sharp.", "meaning": "Move the eyes away from the trap to where the target is first seen clearly.", "say": null}, {"en": "Hold a little lower, just under the line.", "meaning": "Keep the muzzles slightly below the target's path at the call.", "say": null}], "quiz": [{"q": "Which point is about the eyes, not the gun?", "options": ["Hold point", "Break point", "Pick-up point", "Insertion point"], "answer": 2, "why": "The pick-up point is where the eyes first see the target clearly; the hold point is for the muzzles."}, {"q": "What usually happens if the hold point is too close to the trap?", "options": ["The target overtakes the gun", "The referee calls No Bird", "The gun has to chase the target", "The target slows down"], "answer": 2, "why": "Too near the trap, the target leaves at full speed past the muzzles and the shooter has to chase it."}, {"q": "In Parcours de Chasse – Sporting™, the shooter on the stand asks to see the presentation again. What is the maximum per target of the menu?", "options": ["Two targets", "None: no repeats are allowed", "As many as he wants", "Exactly five"], "answer": 0, "why": "The referee repeats the presentation on request, up to a maximum of two targets for each target on the menu."}]}, {"id": "basics-follow-through", "minutes": 5, "title": "Follow-through, gun speed and tempo", "body": ["Follow-through means the gun keeps moving along the target's line after the trigger is pulled, like a golf or tennis swing. There is a small delay between deciding to shoot and the shot leaving the barrels; if the gun stops at the trigger, the shot goes behind. Coaches watch the muzzles after the shot: if they freeze or drop, the follow-through was missing.", "Gun speed is how fast the muzzles move compared with the target, and it defines the lead method: the same speed as the target is maintained lead; faster than the target is swing-through; the same speed, then a short acceleration, is pull-away. A gun that is too slow falls behind; coaches say one that is too fast overshoots, and the shooter then often stops it.", "Tempo is how fast the whole shot is done; rhythm is how even it is. A fast, close target needs a quick tempo, a long, slow crosser a calmer one, but the rhythm stays smooth. Many coaches say that shooters with one tempo for everything lose the targets that need the opposite.", "“Stay in the gun”: cheek on the stock and eyes on the target until it breaks. That also keeps the shooter ready for the second barrel, because two shots may be fired at a single.", "Translate “finish the shot” as continuing the movement, not as stopping."], "key_points": ["Follow-through: the gun keeps moving after the trigger; a stop sends the shot behind.", "Gun speed defines the method: equal (maintained), faster (swing-through), equal then faster (pull-away).", "Tempo = speed of the whole shot; rhythm = its evenness.", "Stay in the gun: ready for the second barrel on a single.", "“Finish the shot” = keep the movement going."], "terms": ["follow-through", "gun-speed", "tempo", "stopping-the-gun", "maintained-lead", "swing-through", "pull-away", "single-target"], "sources": [{"title": "Shooting UK — The overhead clay from behind (follow-through)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "focus": "follow-through"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}], "coach_says": [{"en": "Follow through — the gun keeps moving after the bang.", "meaning": "Do not stop the swing at the shot.", "say": null}, {"en": "You stopped the gun.", "meaning": "The muzzles stopped at the trigger, so the shot went behind.", "say": null}, {"en": "Match the speed of the bird — you're racing it.", "meaning": "The gun is moving much faster than the target; move at the target's speed.", "say": null}, {"en": "Slow the tempo down, this one gives you lots of time.", "meaning": "The target is slow or long, so the whole movement can be calmer.", "say": null}, {"en": "Stay in the gun until you see it break.", "meaning": "Keep the cheek on the stock and eyes on the target until it breaks.", "say": null}], "quiz": [{"q": "The coach says “You stopped the gun”. Where did the shot most likely go?", "options": ["In front", "Over the top", "Exactly on the target", "Behind"], "answer": 3, "why": "The target keeps moving while the stopped gun does not, so the shot passes behind it."}, {"q": "Which gun speed describes maintained lead?", "options": ["Much faster than the target", "The same as the target", "Zero: the gun waits", "Slower than the target"], "answer": 1, "why": "In maintained lead the muzzles move at the target's speed, keeping the gap constant. A waiting gun is ambush; faster is swing-through."}, {"q": "What is the difference between tempo and rhythm?", "options": ["Tempo is the speed of the shot, rhythm its evenness", "They are two words for the same thing", "Tempo is the music played on the ground", "Rhythm is the time limit between targets"], "answer": 0, "why": "Coaches change the tempo for each target while keeping a smooth rhythm, so translate both words separately."}]}]}, {"id": "lead", "icon": "lead", "title": "Lead (forward allowance) and shooting methods", "intro": "Lead is what coaches talk about most: why the gun must point ahead of a moving target, the four ways of getting it there, and the strange units they use to describe it. This mission shows each method step by step and teaches you to translate “four foot”, “half a bird” or “double it” without changing the meaning.", "lessons": [{"id": "lead-why", "minutes": 6, "title": "Why lead exists: actual and perceived lead", "body": ["The shot needs a fraction of a second to reach the target, and in that time the target moves on. A gun pointed straight at a crosser therefore shoots behind it. The gun has to point ahead, so that shot and target meet. That gap is lead, in British English also “forward allowance”.", "Lead grows with the target's speed, its distance and its angle. A full crosser needs the most; a target flying straight at or away from the shooter needs almost no sideways lead, though rising and falling targets need vertical lead (above or below).", "Real numbers are surprising. One shooting website gives about 3 to 4 feet, roughly a metre, of actual lead for a crosser at about 21–25 yards (around 20 m). Many shooters say it grows roughly in proportion with distance, so the same small gap at the muzzle means much more real lead on a far target.", "Actual lead is the real distance in front of the clay in the air. Perceived lead (the “lead picture” or “sight picture”) is the gap the shooter sees between muzzle and target. A metre at 20 m looks like a few centimetres at the muzzle. The method changes the picture: a maintained-lead shooter sees the biggest gap, a swing-through shooter little or none, because gun speed adds lead.", "An American instructor notes that a right-handed shooter often feels a left-to-right crosser needs more lead than a right-to-left one; the real lead is the same, only perception differs. So a coach's “four feet” describes his picture, not a measurement."], "key_points": ["Lead exists because the target moves while the shot travels.", "More speed, distance and angle mean more lead.", "Actual lead (in the air) is far bigger than perceived lead (at the muzzle).", "The method changes the picture: maintained sees most, swing-through least.", "A coach's number is a picture, not a measurement."], "terms": ["lead", "perceived-lead", "crosser", "gun-speed", "maintained-lead", "swing-through"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "NSSA-NSCA — Ask the instructor: leading crossers", "url": "https://nssa-nsca.org/blog/2019/05/10/ask-the-instructor-leading-crossers/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "focus": "perceived-vs-actual"}, "rule_refs": [], "coach_says": [{"en": "Forget the real distance — what matters is your picture.", "meaning": "Do not think in metres in the air; remember the gap you saw at the muzzle when you hit it.", "say": null}, {"en": "That's the picture — remember it.", "meaning": "The lead was right on that hit; keep the same sight picture.", "say": null}, {"en": "Same lead on the right-to-left, it only looks different.", "meaning": "The real lead is equal in both directions; only perception changes.", "say": null}], "quiz": [{"q": "What is perceived lead?", "options": ["The real distance in front of the clay in the air", "The gap the shooter sees between muzzle and target", "The lead written on the target menu", "The distance from the stand to the trap"], "answer": 1, "why": "Perceived lead is the picture at the muzzle; actual lead is the real distance in the air and is much larger."}, {"q": "Which method usually gives the largest perceived lead?", "options": ["Swing-through", "Pull-away", "Maintained lead", "All are identical"], "answer": 2, "why": "With maintained lead the gun moves at the target's speed and gun speed adds nothing, so the shooter must see the whole gap."}, {"q": "Which target needs almost no sideways lead?", "options": ["A target going straight away", "A long crosser", "A quartering-away target at 45°", "A crosser at 40 m"], "answer": 0, "why": "A straight going-away target has no sideways movement; any lead it needs is vertical."}]}, {"id": "lead-maintained", "minutes": 5, "title": "Maintained lead: get in front, stay in front", "body": ["Maintained lead (US: sustained lead; Ukrainian «постійний винос») keeps the muzzles in front of the target from the start to the shot.", "How it looks, step by step on a crosser. 1) Start: the muzzles wait at a hold point well out along the line, ahead of where the target will pass; the eyes look back towards the pick-up point. 2) Insertion: as the target comes, the gun moves and the muzzles join the line in front of it, never behind; this is the insertion point. 3) Tracking: the muzzles move at the target's speed, so the gap stays the same. 4) Shot: the trigger is pulled while the gap is right and the gun is still moving. 5) The gun keeps moving after the shot.", "Strengths: precise, little gun movement, quick between targets, and the lead is easy to adjust. It suits consistent, predictable targets: long crossers, steady high targets.", "Weaknesses: the hardest method to learn; the shooter must know the target's speed and line in advance; and because the gun is not faster than the target, the shooter sees the biggest gap and is tempted to measure it, slow down and stop.", "Coaches say “insert the gun in front”, “stay ahead of it”, “match its speed”."], "key_points": ["Muzzles start ahead and join the line in front of the target.", "Gun speed = target speed; the gap stays constant.", "Trigger while the gap is right and the gun is moving; then follow through.", "Best on long, predictable targets.", "Main risk: measuring the gap and stopping the gun."], "terms": ["maintained-lead", "insertion-point", "hold-point", "gun-speed", "follow-through", "crosser"], "sources": [{"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shotgun Sports USA — How to read sporting clays targets (insertion point)", "url": "https://shotgunsportsusa.com/how-to-read-sporting-clays-targets/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-lr", "muzzle_start": "ahead", "gun_speed": "equal", "trigger": "gap-held", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Get in front and stay in front.", "meaning": "Put the muzzles ahead of the target and keep them there until after the shot.", "say": null}, {"en": "Your insertion point is behind the bird — put the gun in front of it.", "meaning": "The muzzles joined the line behind the target; they must join ahead of it.", "say": null}, {"en": "Match its speed — don't let it catch you.", "meaning": "Move the gun at the target's speed so the gap does not shrink.", "say": null}, {"en": "You're measuring it — trust the picture and pull.", "meaning": "The shooter is slowing down to check the gap; fire as soon as the picture is right.", "say": null}], "quiz": [{"q": "In maintained lead, where do the muzzles join the target's line?", "options": ["Behind the target", "On the target", "In front of the target", "Below the trap"], "answer": 2, "why": "The muzzles are inserted ahead of the target and stay ahead; behind is swing-through, on the target is pull-away."}, {"q": "What is the typical fault of maintained-lead shooters?", "options": ["Starting too far behind", "Measuring the gap and stopping the gun", "Mounting from the hip", "Shooting too early at the trap"], "answer": 1, "why": "The gap is large and visible, so shooters are tempted to check it; the gun slows or stops and the shot goes behind."}, {"q": "For which target is maintained lead often recommended?", "options": ["A long, predictable crosser", "A bouncing rabbit in a short gap", "A surprise target from behind", "A ZZ target"], "answer": 0, "why": "The method needs a known speed and line, which long, steady crossers give; erratic or surprise targets suit other methods."}]}, {"id": "lead-swing-through", "minutes": 5, "title": "Swing-through: from behind, through the bird", "body": ["In swing-through the muzzles start behind the target and overtake it. In Ukrainian you may hear «протяжка» or simply “swing-through”.", "How it looks, step by step. 1) Start: the muzzles join the target's line behind it, on its tail. 2) Overtaking: the gun moves faster than the target, along its line, through its body. 3) Shot: the trigger is pulled as the muzzles pass the front of the target, just ahead of it. Because there is a small delay between decision and shot and the gun is moving faster than the target, the muzzles are already further ahead when the shot leaves: the actual lead at the shot is bigger than the lead the shooter sees, and little or no gap is seen. 4) The swing continues after the shot. The memory aid is “butt, belly, beak, bang”: tail, body, front, fire. In British English you may hear “bum” instead of “butt”; translate it as «хвіст».", "Strengths: natural and fast; good for beginners, for close fast targets, for driven targets and overheads and for erratic or surprise targets.", "Weaknesses: a very short window for the trigger; on long crossers the shooter can run out of time, lose the line or overshoot; slowing down as the muzzles reach the target gives a miss behind.", "Sources disagree on the name “CPSA method”: some describe it as swing-through, while CPSA coaching today is described as teaching pull-away. If a coach says “CPSA method”, ask which one he means."], "key_points": ["Muzzles start behind, on the target's line.", "Gun faster than the target: tail, body, front, bang.", "Trigger as the muzzles pass the front; the actual lead is bigger than the lead seen.", "Good for close, fast, driven and surprise targets; harder on long crossers.", "“CPSA method” is ambiguous: ask which method is meant."], "terms": ["swing-through", "gun-speed", "perceived-lead", "driven-target", "overhead", "follow-through"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "NRA Women — Swing-through, sustained lead and pull-away", "url": "https://www.nrawomen.com/content/shotgun-shooting-swing-through-sustained-lead-and-pull-away"}, {"title": "Shooting UK — The overhead clay from behind", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}], "sim": {"type": "lead", "method": "swing-through", "preset": "crosser-lr", "muzzle_start": "behind", "gun_speed": "faster", "trigger": "passing-front", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "Come from behind, through the bird, and shoot as you see daylight.", "meaning": "Start behind the target, swing through it and fire as a gap appears in front.", "say": null}, {"en": "Butt, belly, beak, bang.", "meaning": "Memory aid: tail, body, front of the target, then fire.", "say": null}, {"en": "You slowed down as you got to it.", "meaning": "The gun lost speed when it reached the target, so the shot went behind.", "say": null}, {"en": "Brush it out and keep going.", "meaning": "Swing through the target as if wiping it out of the sky, without stopping.", "say": null}], "quiz": [{"q": "Where do the muzzles start in swing-through?", "options": ["In front of the target", "On the target's front edge", "At a fixed point at the break point", "Behind the target, on its line"], "answer": 3, "why": "Swing-through starts behind and overtakes the target; starting in front is maintained lead, a fixed point is ambush."}, {"q": "Why does a swing-through shooter see little or no lead?", "options": ["The targets are always slower", "The gun's speed creates the lead", "The rules forbid a visible gap", "The shooter closes both eyes"], "answer": 1, "why": "The gun moves faster than the target, so between deciding and firing it travels ahead by itself."}, {"q": "A coach says “bum, belly, beak, bang”. How should you translate “bum”?", "options": ["As «хвіст» (tail)", "With a rude word, literally", "As «бум» (a sound)", "Leave it out completely"], "answer": 0, "why": "It means the tail of the target; a neutral «хвіст» keeps the meaning and the rhythm of the aid."}]}, {"id": "lead-pull-away", "minutes": 5, "title": "Pull-away: on it, with it, pull away, shoot", "body": ["In pull-away (in Ukrainian sometimes «вихід з мішені»; the pull itself can be called «відрив») the muzzles first join the target, then pull ahead of it. It is widely taught in modern British coaching and is often called the CPSA method today.", "How it looks, step by step. 1) “On it”: the gun is mounted onto the target or its front edge; the muzzles touch it on its line. 2) “With it”: the muzzles track the target for a moment at its speed, matching line and pace. 3) “Pull away”: the gun accelerates smoothly ahead until the right lead picture appears. 4) “Shoot”: the trigger is pulled while the gun is still accelerating or moving. 5) Follow-through: the gun keeps going after the shot.", "Strengths: tracking the target first lets the shooter judge its speed, distance and line before committing, so the line is good. It suits long targets, quartering targets and rising targets. Because of the acceleration, the perceived lead is smaller than with maintained lead.", "Weaknesses: the amount of acceleration varies from target to target, so it takes practice to feel it; tracking for too long becomes “riding the target”, and stopping the push gives a miss behind.", "Coaches say “touch it and go”, “mount on it and push out”, or the four-beat “on it, with it, pull away, shoot”. Keep the four-beat rhythm when you translate: it matters more than the exact words."], "key_points": ["Muzzles start on the target (or its front edge).", "Track at its speed, then accelerate ahead.", "Trigger while the gun is still moving forward; then follow through.", "Good line control; suits long, quartering and rising targets.", "Keep the four-beat rhythm when translating."], "terms": ["pull-away", "insertion-point", "gun-speed", "perceived-lead", "quartering-away", "follow-through"], "sources": [{"title": "CPSA — How to hit series (search summary; page not directly accessible)", "url": "https://www.cpsa.co.uk/how-to-hit-series-3"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "GAIM — Swing-through, pull-away or maintained lead", "url": "https://www.gaim.com/blog/swing-through-pull-away-or-maintained-lead"}], "sim": {"type": "lead", "method": "pull-away", "preset": "crosser-rl", "muzzle_start": "on-target", "gun_speed": "equal-then-faster", "trigger": "during-acceleration", "follow_through": true}, "rule_refs": [], "coach_says": [{"en": "On it, with it, pull away, shoot.", "meaning": "Join the target, track it, accelerate ahead, fire.", "say": null}, {"en": "Touch it and go.", "meaning": "Meet the target with the muzzles and immediately start pulling ahead.", "say": null}, {"en": "You rode it too long.", "meaning": "The shooter tracked the target for too long before pulling away and lost the line or the moment.", "say": null}, {"en": "Mount on it and push out a bit more.", "meaning": "Mount onto the target, then pull a little further ahead before firing.", "say": null}], "quiz": [{"q": "In pull-away, what happens just before the trigger is pulled?", "options": ["The gun stops on the target", "The gun accelerates ahead of the target", "The gun drops below the target", "The gun waits at the break point"], "answer": 1, "why": "The pull-away itself is the acceleration ahead; the shot is fired while the gun is still moving forward."}, {"q": "The coach says “You rode it too long”. What went wrong?", "options": ["He stood too long on the stand before calling", "He mounted the gun far too early", "He tracked it too long before pulling away", "The trapper released the target late"], "answer": 2, "why": "“Riding the target” means following it too long, so it slows, drops or escapes and the line is lost."}, {"q": "Compared with maintained lead, the perceived lead in pull-away is usually…", "options": ["smaller, because the acceleration adds lead", "larger, because the gun starts on the target", "always exactly double", "zero on every target"], "answer": 0, "why": "The brief acceleration carries the gun forward during the shot delay, so less gap needs to be seen."}]}, {"id": "lead-ambush-instinctive", "minutes": 5, "title": "Ambush and instinctive shooting", "body": ["Ambush, or spot shooting (in Ukrainian it can be described as «стрільба в точку» or «на перехоплення»), is the opposite of a swing. 1) The muzzles are placed at a point ahead of the target, on its line, close to the break point. 2) They wait with little or no movement. 3) The trigger is pulled as the target arrives at that spot.", "As a general habit, typical of untrained shooters, it is unreliable: the gun is still and the timing must be perfect. But a deliberate ambush is sometimes the right choice: a target that must be taken very fast, or a rabbit visible only in a short gap between bushes. A related move on edge-on battues at the top of their flight is the “collapse”: hold very close to the break point and make a minimal move. The target must still break where the referee can see it.", "Instinctive shooting means no conscious lead at all. The shooter keeps a hard focus on the target and lets the hands follow; the swing and the mount happen together, and the shot comes as the gun reaches the face. The classic school is the one associated with the English gunmaker Robert Churchill, popular in game shooting.", "Many top Parcours de Chasse – Sporting™ shooters mix methods, choosing per target. “Which method for this one?” is a normal coaching question."], "key_points": ["Ambush: muzzles still at a point ahead; fire as the target arrives.", "Unreliable as a habit, useful deliberately (very fast targets, short gaps).", "“Collapse”: minimal move near the break point on edge-on battues.", "Instinctive: no conscious lead, hard focus, mount and swing together (Churchill school).", "Good shooters choose the method per target."], "terms": ["ambush", "instinctive-shooting", "hard-focus", "break-point", "battue", "rabbit"], "sources": [{"title": "Wikipedia — Clay pigeon shooting (methods)", "url": "https://en.wikipedia.org/wiki/Clay_pigeon_shooting"}, {"title": "NSSA-NSCA — Ask the instructor: battues", "url": "https://nssa-nsca.org/blog/2017/07/18/ask-the-instructor-battues/"}, {"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "Shotgun Life — Wingshooting schools of England", "url": "https://www.shotgunlife.com/travel/places-to-shoot/wingshooting-schools-of-england-3.html"}], "sim": {"type": "lead", "method": "ambush", "preset": "rabbit", "muzzle_start": "at-break-point", "gun_speed": "none-or-minimal", "trigger": "target-arrives", "follow_through": false}, "rule_refs": [{"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}], "coach_says": [{"en": "You're ambushing it — keep the gun moving with the target.", "meaning": "The shooter is waiting at a point; the coach wants a moving method here.", "say": null}, {"en": "Ambush this one in the gap.", "meaning": "Deliberately wait at the opening and fire as the target crosses it.", "say": null}, {"en": "Don't think about the lead, just look at the bird and let the gun go to it.", "meaning": "Shoot instinctively: focus on the target and let the hands follow.", "say": null}, {"en": "Hold right on the break point and just collapse onto it.", "meaning": "Put the muzzles almost at the break point and make only a tiny move as the battue arrives.", "say": null}], "quiz": [{"q": "What characterises ambush (spot shooting)?", "options": ["The gun swings faster than the target", "The gun waits at a point ahead of the target", "The gun tracks the target, then accelerates", "The gun starts behind the target, on its line"], "answer": 1, "why": "Ambush means little or no swing: the muzzles wait on the line and the target flies into the shot."}, {"q": "When can a deliberate ambush be a good choice?", "options": ["On every long, steady crosser", "Never: the rules forbid it", "Only in Compak® Sporting, never in Sporting™", "On a rabbit seen only in a short gap"], "answer": 3, "why": "When the target is visible only briefly, there is no time for a swing, so waiting at the gap can work. No rule forbids any method."}, {"q": "What is instinctive shooting?", "options": ["Hard focus on the target, no conscious lead", "Shooting without safety glasses", "Shooting from the hip, without mounting", "Waiting at the trap for every target"], "answer": 0, "why": "Instinctive shooting relies on eye–hand coordination; it is still done with the gun at the shoulder, as the rules require."}]}, {"id": "lead-how-coaches-say-it", "minutes": 6, "title": "How coaches say lead, and how to translate it", "body": ["Units. British and American coaches talk in feet and yards: “give it four foot” (British for four feet), “two feet in front”. European coaches use metres. One foot is about 30 cm, one yard about 0.9 m. But a lead number is the coach's picture, not a measurement, so keep his number and unit. Never convert in the middle of an instruction; if the shooter asks, explain roughly between targets. Distances to a target (“it's 30 yards”) may be given as “about 27 m”.", "Target widths: “half a bird”, “a bird's width”, “a clay's length”. Bird means target, never a real bird: «пів мішені». Barrel widths: “a barrel's width”, “two barrels” mean the gap seen at the muzzle. Careful: a referee's “two barrels” means both barrels fired together.", "Relative words: “more”, “less”, “a touch more”, “double it”, “half that”, “same lead”. Keep them relative and never invent a number. “Same lead” is vital: the shooter must not add lead.", "Directions: “in front” and “behind” refer to the target's travel; “over” and “high”, “under” and “low” are synonyms. A clock face describes positions: 12 o'clock is up, 3 o'clock right, as the shooter sees it. “You hit it at six” means the bottom edge; “it comes from eleven” gives a direction.", "Method: translate number, unit, reference and direction exactly, short, in the coach's rhythm. If unclear, ask him one word: “Feet?” In competitions coaching is forbidden."], "key_points": ["Keep the coach's number and unit; never convert lead mid-instruction.", "Bird = target: “half a bird” = «пів мішені».", "Relative words stay relative; “same lead” must be translated.", "Clock face: 12 up, 3 right, as the shooter sees it.", "A referee's “two barrels” is a double discharge, not a lead."], "terms": ["lead", "perceived-lead", "clock-face", "double-discharge", "coach"], "sources": [{"title": "Shotgun Life — Does shotgun barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "Shooting UK — The overhead clay from behind (clock-face pick-up)", "url": "https://www.shootinguk.co.uk/shooting/shotgun/the-less-on-overhead-clay-from-behind/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "lead", "method": "maintained", "preset": "crosser-rl", "focus": "lead-units"}, "rule_refs": [{"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Give it four foot.", "meaning": "Give the lead the coach calls “four feet”; it describes his picture, so keep his number and unit.", "say": null}, {"en": "Half a bird more.", "meaning": "Add half a target's width to the lead picture.", "say": null}, {"en": "Double it.", "meaning": "Make the lead picture twice as big as last time.", "say": null}, {"en": "Same lead, just keep it moving.", "meaning": "The lead was right; the miss came from stopping the gun.", "say": null}, {"en": "You were at two o'clock — a touch low and more in front.", "meaning": "The pattern was above and to the right of the target on the clock face; shoot slightly lower and give a little more lead.", "say": null}, {"en": "A barrel's width in front.", "meaning": "Keep a gap the width of the barrel, as seen at the muzzle, ahead of the target.", "say": null}], "quiz": [{"q": "The coach says “Give it four foot” to a shooter who thinks in metres. What do you say?", "options": ["«Дайте 1,22 метра»", "«Дайте приблизно метр»", "«Дайте чотири фути»", "«Дайте чотири метри»"], "answer": 2, "why": "A lead number is the coach's picture; converting it mid-instruction adds false precision or errors, and “four metres” changes the meaning completely. If the shooter asks, explain roughly between targets."}, {"q": "What does “half a bird” mean?", "options": ["Half the width of a target", "A broken target", "A small bird flying near the trap", "Half of the round"], "answer": 0, "why": "In clay shooting “bird” means the target, so the coach asks for half a target's width of lead."}, {"q": "The coach says “Same lead, keep it moving”. Why must “same lead” be translated?", "options": ["It is a call the referee uses", "Otherwise the shooter may add lead and miss", "It is a polite greeting between shooters", "It changes the order of the targets"], "answer": 1, "why": "After a miss most shooters add lead by themselves; “same lead” tells them the cause was the stopped gun, not the lead."}]}]}, {"id": "faults", "icon": "search", "title": "Faults and how coaches diagnose them", "intro": "When a target is missed, the coach names the miss in one or two words and then the cause. This mission teaches the words for misses and faults, what each one really means, and how to pass a coach's diagnosis to the shooter quickly and exactly.", "lessons": [{"id": "faults-behind-in-front", "minutes": 5, "title": "Behind, in front, over, under, chipped", "body": ["Every miss has a direction. A coach watching from behind the shooter usually says first where the shot went compared with the clay, and only then why. Pass it on instantly: the shooter is already preparing for the next target.", "Behind means the shot passed behind a moving target: not enough lead, or a gun that slowed down. It is the most common miss on crossers. In front is the opposite: too much lead, often after the shooter over-corrected. Many coaches like a miss in front: it shows the gun kept moving.", "Over (also 'high', 'over the top') and under ('low') describe the vertical miss. Over is common on dropping targets, rabbits and incomers, and is often linked to the head coming off the stock. Under is typical on rising targets that are still climbing at the shot.", "Chipped means only a small piece came off. For the coach it is half praise, half correction: the clay was on the edge of the pattern. For the referee it is a hit, as long as the piece is visible. The trap is dust: under the rules, a clay that gives off only dust or smoke, with no visible piece, is lost. Yet 'smoked it' in coach slang is a perfect, centred hit, and 'dusted it' is heard in both senses, so ask when unsure.", "Keep the coach's order: direction, cause, fix. If the coach says 'behind, you stopped', the cause matters more: a shooter who hears only 'behind' will add lead, which does not cure a stopped gun."], "key_points": ["Pass on the direction first: behind, in front, over, under.", "Behind = too little lead or a slowing gun; in front = too much lead.", "A visible chip is a hit for the referee; dust or smoke only is lost.", "'Smoked it' is coach praise, not the 'smoke' of the rules: never mix them up.", "Keep the coach's order: direction, cause, fix."], "terms": ["lead", "crosser", "dropping-target", "visible-piece", "one", "zero", "miss-behind", "miss-in-front", "miss-over", "miss-under", "chip", "smoke-ball"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}], "coach_says": [{"en": "Behind, give it more.", "meaning": "The shot passed behind the clay; increase the lead.", "say": null}, {"en": "Just over the top, it was already dropping.", "meaning": "The shot went above because the clay was falling; shoot lower and in front.", "say": null}, {"en": "In front this time, good, now a touch less.", "meaning": "Too much lead, but the gun was moving; reduce the lead slightly.", "say": null}, {"en": "You just chipped it, a little more in front.", "meaning": "Hit on the edge of the pattern; a bit more lead centres it.", "say": null}, {"en": "Smoked it! Same again.", "meaning": "A perfect centred hit (slang, not the rules' 'smoke'); repeat exactly.", "say": null}, {"en": "Behind, but you stopped, so don't just add lead.", "meaning": "The cause is a stopped gun; more lead alone will not help.", "say": null}], "quiz": [{"q": "The coach calls: 'Behind, you stopped!' What is the most important part to translate?", "options": ["The cause: the gun stopped", "Only the direction 'behind'", "Nothing: the shooter saw the miss", "A request to add a lot more lead"], "answer": 0, "why": "Adding lead does not cure a stopped gun; the cause is what the shooter has to fix."}, {"q": "A small but clearly visible piece breaks off the clay. The coach says 'just chipped it'. How does the referee score it?", "options": ["Lost, because most of the clay flew on", "No Bird", "Hit (one)", "Hit only if the coach agrees"], "answer": 2, "why": "At least one visible piece makes the target a hit in both Sporting™ and Compak® Sporting; the referee decides alone."}, {"q": "After a hit the coach shouts 'Smoked it!'. What does he mean?", "options": ["Only dust came off, so it is lost", "A perfect, centred hit", "It was a flash target", "The shooter should change cartridges"], "answer": 1, "why": "In coach slang 'smoked it' is praise for a clay turned to dust; in the rules, dust or smoke without a visible piece is a miss."}]}, {"id": "faults-head-lift-stopping", "minutes": 5, "title": "Head lift, stopping, riding, poking", "body": ["After the direction, the coach names the cause. Four causes come up every training day, each with its own short word. Learn them in pairs: the fault and the cure.", "Head lift: the cheek leaves the stock at or just before the shot, often because the shooter wants to see the clay break. The eye is the rear sight, so lifting it moves the picture, and the shot usually goes over. Cure: 'head down', 'cheek on the stock', 'stay in the gun'.", "Stopping the gun: the muzzles halt at the shot, usually because the shooter checks the lead on the barrel. The shot goes behind. A lighter version is checking: the swing hesitates for a split second. Cure: 'keep the gun moving', 'follow through', 'finish the shot'.", "Riding the target: following the clay too long before firing, so it slows, drops or curls away and the shooter loses the line. Cure: 'take it earlier', 'commit to it'. Poking (also 'aiming', 'measuring'): pointing the shotgun slowly like a rifle, eyes on the bead instead of the clay. It is typical when the break point is too close, or on a teal at the top. Cure: 'eyes on the clay', 'let the gun go'.", "Coaches often name the cause before the shooter has even lowered the gun. Translate it in the same breath and with the same verb: 'you stopped' is not 'you missed'. A word like 'aiming' is almost always a criticism, so never turn it into advice such as 'aim better'."], "key_points": ["Head lift: shot usually over; cure: head down, stay in the gun.", "Stopping or checking: shot behind; cure: keep the gun moving, follow through.", "Riding: the clay slows or drops away; cure: take it earlier, commit.", "Poking or aiming: slow rifle-like pointing; cure: eyes on the clay.", "Translate the cause at once, with the coach's own verb."], "terms": ["head-lift", "stopping-the-gun", "follow-through", "break-point", "teal", "checking", "riding-the-target", "poking"], "sources": [{"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}, {"title": "Shooting UK — How to hold a shotgun", "url": "https://www.shootinguk.co.uk/news/how-to-hold-a-shotgun/"}, {"title": "The Field — Improve your game and clay shooting: 20 top tips", "url": "https://www.thefield.co.uk/shooting/improve-your-game-and-clay-shooting-20-top-tips-45462"}, {"title": "Clay Target Nation — 5 major shooting mistakes", "url": "https://www.claytargetnation-digital.com/articles/5-major-shooting-mistakes"}], "sim": null, "rule_refs": [], "coach_says": [{"en": "You lifted your head, that's why it went over.", "meaning": "The cheek left the stock, so the shot went above the clay.", "say": null}, {"en": "Keep the gun moving, you stopped on it.", "meaning": "The swing halted at the shot; continue moving through and after it.", "say": null}, {"en": "You checked just before the shot, commit to it.", "meaning": "A brief hesitation before firing; decide and shoot without slowing.", "say": null}, {"en": "Stop aiming, look at the bird and let the gun go.", "meaning": "Criticism: the shooter is pointing like a rifle; focus on the target and swing freely.", "say": null}, {"en": "You rode it too long, take it earlier.", "meaning": "The shooter followed the clay too long; break it sooner.", "say": null}, {"en": "Stay in the gun.", "meaning": "Keep the cheek on the stock until after the shot.", "say": null}], "quiz": [{"q": "The coach says 'You lifted your head'. Where did the shot most likely go?", "options": ["Behind", "Over the top", "Under", "In front"], "answer": 1, "why": "The eye is the rear sight: when the head lifts, the shot usually goes over."}, {"q": "A coach shouts 'Stop aiming!'. What does he want?", "options": ["Don't point like a rifle: look at the target and swing", "Aim more precisely", "Cease fire at once", "Lower the gun"], "answer": 0, "why": "'Aiming' in a coach's mouth is a fault (poking); the cure is eyes on the clay and a free swing."}, {"q": "'You rode it too long' means…", "options": ["The shooter fired too early", "The trap was too slow", "The shooter started too far behind", "The shooter followed the clay too long before firing"], "answer": 3, "why": "Riding the target means following it too long, so it slows or drops and the line is lost."}]}, {"id": "faults-mount-errors", "minutes": 5, "title": "Mount errors: late, face to the gun, canting", "body": ["Many misses start before the swing, in the gun mount: the movement that brings the gun to cheek and shoulder. The coach's words for it are short and physical.", "Late mount: the gun reaches the shoulder after the moment the shot should have been fired, so the shooter rushes or fires before the cheek is down. The opposite fault is a mount finished too early, after which the gun waits, still and heavy. Cure: 'move, mount, shoot', where the muzzles start with the target and the mount is completed as the shot comes.", "Face to the gun: instead of bringing the stock up to the face, the shooter drops the head to meet it. The eye ends up in a different place every time, and recoil hits the cheek. Coaches say: 'bring the gun to your face, not your face to the gun'. A stock landing on the arm instead of the shoulder pocket hurts too.", "Canting: the gun is tilted sideways at the shot, and the shot drifts off the line. It often comes with a dropped shoulder. Cure: 'keep the gun level', 'turn from the hips'.", "In FITASC Parcours de Chasse – Sporting™ competitions the gun may not be mounted before the target appears, so 'pre-mount this one' is a training drill only. Mounting early in a Sporting™ competition brings a warning and a yellow card. In Compak® Sporting the gun may already be at the shoulder at the call. Translate the drill as a drill and add nothing of your own."], "key_points": ["Late mount: a rushed shot; cure: move, mount, shoot.", "Face to the gun: the eye moves and recoil hurts; bring the gun to the face.", "Canting: the shot drifts off the line; keep the gun level, turn from the hips.", "Pre-mounting is a drill: not allowed before the target appears in a Sporting™ competition, allowed at the call in Compak® Sporting."], "terms": ["gun-mount", "ready-position", "recoil", "comb", "gun-fit", "dry-mounting", "late-mount", "canting"], "sources": [{"title": "Ducks Unlimited — Shotgunning: the Churchill method", "url": "https://www.ducks.org/hunting/shooting-tips/shotgunning-the-churchill-method"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}], "coach_says": [{"en": "Bring the gun to your face, not your face to the gun.", "meaning": "Lift the stock to the cheek; do not lower the head to the stock.", "say": null}, {"en": "Move, mount, shoot, all in one.", "meaning": "Start moving with the target, finish the mount as you fire, in one flowing action.", "say": null}, {"en": "You canted the gun, keep it level.", "meaning": "The gun was tilted sideways at the shot.", "say": null}, {"en": "Mount on the line.", "meaning": "The gun should come up already on the target's path.", "say": null}, {"en": "Pre-mount this one, just for practice.", "meaning": "Training drill with the gun already at the shoulder; not allowed in a Sporting™ competition.", "say": null}], "quiz": [{"q": "In training, a coach tells a shooter preparing for a FITASC Sporting™ competition: 'Pre-mount this one.' What is true?", "options": ["It is allowed in every FITASC competition", "The interpreter should refuse to translate it", "It is a training drill; in a Sporting™ competition the gun may not be mounted before the target appears", "It means mounting after the shot"], "answer": 2, "why": "Sporting™ requires the gun-down ready position until the target appears; a pre-mount in competition earns a warning with a yellow card."}, {"q": "'You canted the gun' means…", "options": ["The gun was tilted sideways at the shot", "The gun was mounted too late", "The gun stopped", "The safety catch was on"], "answer": 0, "why": "Canting is a sideways tilt of the gun, which pulls the shot off the line."}, {"q": "Which instruction cures 'face to the gun'?", "options": ["Push the head down harder", "Bring the gun to your face", "Close one eye", "Hold the gun lower on the arm"], "answer": 1, "why": "The stock should come up to the face, so the eye is in the same place every time."}]}, {"id": "faults-pairs-transition", "minutes": 5, "title": "Pairs: the second target", "body": ["On a pair (double) many shooters break the first target and miss the second. The coach then talks about transition, moving from the first target to the second, and recovery, getting gun and head back under control after the first shot.", "The golden rule is 'eyes first, then the gun'. The eyes leave the broken first clay and find the second; the gun follows. A shooter who watches the first clay break, or swings the gun before finding the second, loses time. Coaches say 'eyes to the second' or simply point.", "Recovery: recoil lifts the muzzles and sometimes the head. 'Let the gun recover, then go' means: cheek back down and gun back on line before going after the second target. A good stance with the weight forward makes recovery faster.", "Planning: while reading the pair, the coach decides which target to take first and where to break it so the second is easy to pick up. Typical phrases: 'take the dropping one first', 'break the first early', 'stick to the plan'. A shooter who changes the order on the stand 'went for the wrong one'.", "Rules matter here. In Parcours de Chasse – Sporting™ the gun position is free between the two targets of any double, and the shooter has two cartridges for a double, both of which may go at the same target. In Compak® Sporting only one cartridge per target is allowed in a double. Do not explain penalties yourself: translate the coach and leave rule questions to the referee."], "key_points": ["Eyes first, then the gun.", "Recovery: cheek back on the stock and gun on line before the second target.", "The coach plans the order and the break points of a pair while reading it.", "Sporting™: free gun position between the targets, and both cartridges may go at one target; Compak® Sporting: one cartridge per target."], "terms": ["double", "double-on-report", "simultaneous-double", "rafale-double", "recoil", "stance", "dropping-target", "transition", "recovery"], "sources": [{"title": "Shooting UK — How to shoot an on-report pair of springing teal", "url": "https://secure.shootinguk.co.uk/shooting/clay-shooting/how-to-shoot-an-on-report-pair-of-springing-teal-90197"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Eyes first to the second bird, then the gun.", "meaning": "Find the second target with the eyes before moving the gun.", "say": null}, {"en": "Let the gun recover, then go to the second.", "meaning": "After the recoil, settle gun and cheek before the second shot.", "say": null}, {"en": "Take the dropping one first.", "meaning": "Shoot first the target that will disappear or fall soonest.", "say": null}, {"en": "Don't watch the first one break.", "meaning": "Move the eyes on to the second target at once.", "say": null}, {"en": "You went for the wrong one first, stick to the plan.", "meaning": "The shooter changed the planned order; a technique remark, not a rule breach.", "say": null}], "quiz": [{"q": "What does 'eyes first, then the gun' mean on a pair?", "options": ["Close the eyes after the first shot", "Look at the barrel before the second shot", "Mount the gun before calling for the pair", "Find the second target with the eyes before moving the gun to it"], "answer": 3, "why": "In a good transition the eyes lead and the gun follows."}, {"q": "In a Compak® Sporting double, the shooter misses the first target and wants to fire the second cartridge at it too. Is that allowed?", "options": ["Yes, as in Sporting™", "Yes, but only on a simultaneous double", "No: in a Compak® Sporting double only one cartridge per target is allowed", "Only with the referee's permission"], "answer": 2, "why": "Compak® Sporting forbids doubling the first target in a double; Sporting™ allows both cartridges at one target."}, {"q": "In a Sporting™ double, may the shooter lower the gun between the first and the second target?", "options": ["Yes, the gun position is free between the two targets", "No, the gun must stay mounted", "Only on a double on report", "Only if the referee allows it"], "answer": 0, "why": "The free position applies between the targets of any double, but not before the first one."}]}, {"id": "faults-reading-the-coach", "minutes": 5, "title": "Reading the coach: short commands and signals", "body": ["On the stand a coach speaks in fragments: 'Behind.' 'Head.' 'More.' 'Again.' There are only a few seconds between targets, so short is deliberate. Your translation should be just as short; a long sentence arrives after the next call.", "Many coaches ask before they tell: 'Where did it go?' or 'What did you see?' This is a teaching question, not a test of the interpreter. Translate the question, let the shooter answer, and translate the answer back exactly, even if it sounds wrong. The coach needs to know what the shooter perceived.", "Hand signals carry a lot. Common ones: hands moving apart or together for more or less lead, a flat hand moving down for 'lower', a tap on the cheek for 'head down', a finger tracing the target's line, a thumbs-up for 'same again'. Signals differ between coaches, so agree on them before the session, and do not translate a gesture the shooter has already seen.", "Some words are pure rhythm and encouragement: 'commit', 'trust it', 'smooth', 'good, same again'. Keep the tone. 'Bad luck' after a miss is kindness, not a comment on the referee.", "In competition coaching is forbidden: the referee gives the competitor a yellow card and sends the coach out of the shooting area. The rules do not say whether an interpreter may relay a coach's advice during a competition: it is an open question for FITASC. The safe practice: in competition, interpret only for the referee, the jury and the organiser."], "key_points": ["Coaches speak in fragments; translate just as briefly.", "'Where did it go?' is a teaching question: translate the shooter's answer exactly.", "Agree on hand signals before the session.", "No coaching in competition; interpret only for the referee, jury and organiser."], "terms": ["coach", "referee", "jury", "yellow-card", "hand-signal"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}], "coach_says": [{"en": "Where did it go?", "meaning": "The coach asks where the shooter thinks the shot went; a teaching question.", "say": null}, {"en": "What did you see?", "meaning": "Describe the picture at the moment of the shot.", "say": null}, {"en": "More.", "meaning": "In context almost always 'more lead'.", "say": null}, {"en": "Good, same again.", "meaning": "Repeat exactly what you just did.", "say": null}, {"en": "Trust it, commit to it.", "meaning": "Stop hesitating; decide and fire.", "say": null}, {"en": "Bad luck.", "meaning": "Sympathy after a miss; not a complaint about the referee.", "say": null}], "quiz": [{"q": "The coach asks the shooter 'Where did it go?'. What should the interpreter do?", "options": ["Answer for the shooter", "Translate the question, then the shooter's answer exactly", "Explain the miss in your own words", "Say nothing: it is a rhetorical question"], "answer": 1, "why": "The coach wants the shooter's own perception, so the answer must reach him unchanged."}, {"q": "During a competition the shooter's coach asks you to pass on: 'Give the next one more lead.' What is the safe practice?", "options": ["Pass it on quietly", "Pass it on only between stands", "Do not relay coaching in competition; interpret only for the referee, jury and organiser", "Ask the other shooters first"], "answer": 2, "why": "Coaching in competition is forbidden, and the rules do not say whether an interpreter may relay it; staying out of it protects the shooter."}, {"q": "What happens under the rules if the referee judges that a competitor is being coached?", "options": ["Yellow card for the competitor; the coach is sent out of the shooting area", "Nothing: coaching is allowed", "The target is repeated", "The whole squad is disqualified"], "answer": 0, "why": "Both rulebooks give the competitor a yellow card, with heavier penalties for repeats, and remove the coach."}]}]}, {"id": "sporting", "icon": "flag", "title": "Parcours de Chasse – Sporting™ rules", "intro": "Parcours de Chasse – Sporting™ is the FITASC discipline that imitates hunting over natural ground. This mission walks you through its rules the way a referee applies them: rounds and stands, the gun-down start, singles and doubles, target viewing, malfunctions and time limits. Everything here is a paraphrase; the rule references open ClayArena's rules guide.", "lessons": [{"id": "sporting-rounds-stands", "minutes": 5, "title": "Rounds, stands and the order of shooting", "body": ["A Parcours de Chasse – Sporting™ competition is counted in rounds of 25 targets. An international event is 200 targets, so eight rounds; each round is shot on one layout (a set of shooting stands) or one line.", "Every layout gives 15 singles and 5 doubles. The number of stands and traps depends on the system: the old system uses 5 traps for 3 stands, while new-system lines have 4 or 5 stands with 3 or 4 traps each. Traps are lettered A, B, C, D from left to right as seen from the stand. The target menu in front of the stand lists them in shooting order, together with any special targets: 90, 70 or 60 mm, battue, rabbit.", "The stand itself is a 1 m square or a circle 1 m across. Each trajectory has a difficulty class: A (an average shooter breaks more than 80%), B (60 to 80%) or C (40 to 60%).", "Shooters go round in squads of up to six, formed by draw. At each stand everyone shoots the singles first and then the doubles, and the order of shooting rotates at each stand and again for the doubles. The others wait close by, without distracting the person shooting.", "The referee, or a person the referee supervises, keeps the scorecard, marking each target under its trap letter. When leaving each stand, every shooter checks the score; a disagreement must be raised with the referee at once, and the referee's decision is final."], "key_points": ["Round = 25 targets on one layout: 15 singles + 5 doubles; international event = 200 targets.", "Traps A, B, C, D from left to right as seen from the stand; the menu gives the order and special targets.", "Squads of up to six; singles first, then doubles; the order rotates.", "Check your score when leaving each stand; the referee decides."], "terms": ["round", "layout", "shooting-stand", "trap", "target-menu", "single-target", "double", "squad", "rotation", "score-sheet", "referee", "difficulty-class"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch2-traps-table", "label": "2 · Number of traps and targets per layout type"}, {"book": "sporting", "id": "ch2-trap-letters", "label": "2 · Trap types and letters"}, {"book": "sporting", "id": "ch2-target-menu", "label": "2 · Target menu at the stand"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-singles-then-doubles", "label": "16 · Singles first, then doubles"}, {"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}], "coach_says": [{"en": "Singles first, then doubles.", "meaning": "The standard order at every stand.", "say": null}, {"en": "Read the menu: the traps go A, B, C.", "meaning": "The menu board lists the traps in the order they will be shot.", "say": null}, {"en": "Next shooter.", "meaning": "The referee calls the next person onto the stand.", "say": null}, {"en": "Check your score before you leave the stand.", "meaning": "Any disagreement must be raised now, not later.", "say": null}], "quiz": [{"q": "How many targets does one Sporting™ layout give, and how are they split?", "options": ["20: 10 singles and 5 doubles", "25: all singles", "25: 15 singles and 5 doubles", "50: 25 singles and 25 doubles"], "answer": 2, "why": "Every layout type gives 15 singles plus 5 doubles, which is 25 targets."}, {"q": "In what order does a squad shoot at a stand?", "options": ["Doubles first, then singles", "Everyone shoots the singles first, then the doubles, and the order rotates", "Each shooter shoots the whole layout in one go", "The shooters choose freely"], "answer": 1, "why": "Singles come first, then doubles, in rotation, unless the jury decides otherwise."}, {"q": "Leaving the stand, a shooter sees that a hit was marked as a miss. What should he do?", "options": ["Wait for the end of the round and appeal to the jury", "Correct the card himself", "Ask the squad to vote", "Tell the referee at once; the referee decides"], "answer": 3, "why": "Scores are checked when leaving each stand; the referee alone decides, and there is no appeal afterwards."}]}, {"id": "sporting-gun-position", "minutes": 5, "title": "The gun-down start", "body": ["The most visible rule of Parcours de Chasse – Sporting™ is the gun-down start. Before calling, the shooter stands with both feet inside the stand, the heel of the stock touching the body and the top rear point of the stock below a line on the vest. This ready position is held until the target has been released and can be seen.", "The line is marked on the vest or jacket 25 cm below the shoulder axis, parallel to it, in a colour that contrasts with the vest so the referee can see it. The rule covers every stock type, adjustable combs included.", "The gun may come up only when the target appears. Every target, rabbits included, is shot with the gun at the shoulder; firing from the hip is not allowed. Between the first and second targets of any double the gun position is free, but before the first target the ready position applies.", "Penalties: the first time a shooter calls in a wrong position or mounts before the target appears, the referee gives a verbal warning with a yellow card. Any further offence on the same layout brings a red card, and the target is scored zero on a single, zero and No Bird on a double on report, zero and zero on a simultaneous or rafale double.", "Mounting and swinging along the imagined line before calling (mock shooting) is forbidden too: a warning first, then a zero. If a coach drills a gun-up start before a FITASC event, translate the word 'drill' too."], "key_points": ["Before the call: both feet in the stand, stock touching the body, top of the stock below the vest line.", "The vest line is 25 cm below the shoulder axis, in a contrasting colour.", "Mount only when the target appears; always shoot from the shoulder; free position between the targets of a double.", "First offence: warning + yellow card; next on the same layout: red card and the target scored."], "terms": ["ready-position", "gun-mount", "shooting-stand", "shooting-vest", "adjustable-comb", "mock-shooting", "yellow-card", "red-card", "jacket-line"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}], "coach_says": [{"en": "Gun down, please.", "meaning": "Referee: bring the stock below the vest line before calling.", "say": null}, {"en": "Your stock was above the line. This is a warning.", "meaning": "First gun-position offence: verbal warning with a yellow card.", "say": null}, {"en": "Don't mount before the target appears.", "meaning": "The gun may come up only once the target is visible.", "say": null}, {"en": "Red card, zero.", "meaning": "A repeat offence on the same layout; the single is lost.", "say": null}], "quiz": [{"q": "First stand. A shooter calls with the gun already at the shoulder. It is his first offence on this layout. What is the referee's decision?", "options": ["The target is scored zero", "A verbal warning with a yellow card", "No Bird and nothing else", "Expulsion"], "answer": 1, "why": "The first gun-position offence is a verbal warning backed by a yellow card."}, {"q": "Same layout, two stands later: the same shooter calls for a single with the stock above the vest line. Decision?", "options": ["Another yellow card", "No Bird", "Red card, and the target is repeated", "Red card, and the single is scored zero"], "answer": 3, "why": "After the warning, a further offence on the same layout is a red card: zero on a single."}, {"q": "Double on report. After breaking the first target, the shooter lowers the gun slightly before the second. Decision?", "options": ["Allowed: the gun position is free between the two targets", "Yellow card", "Zero on the second target", "No Bird"], "answer": 0, "why": "The free position applies between the targets of any double; the ready position is required only before the first one."}]}, {"id": "sporting-singles-doubles", "minutes": 5, "title": "Singles and doubles", "body": ["A single is one target from one trap. In Parcours de Chasse – Sporting™ the shooter may fire two cartridges at it, so a first-barrel miss can still be saved with the second. Every single must leave time for two shots.", "A double is two targets, and the shooter has only two cartridges for it; both may go at the same target. There are three kinds. On report: the second target leaves 0 to 3 seconds after the shot at the first, released by that shot. Simultaneous: both leave at the same moment, from one or two traps. Rafale: two targets from the same trap on the same line, the second as fast as the trap reloads. In simultaneous and rafale doubles the targets may be taken in either order. Doubles use only targets already shown as singles from the same stand.", "Decisions the referee often has to make: if one shot breaks both targets of any double, both count, one and one. If the shooter does not fire at a rafale or simultaneous double without a valid reason, it is zero and zero.", "On a double on report, an irregular first target means the double is repeated; if the first target or its pieces break the second before the second shot, or the second is irregular, the double is repeated and the first result is kept. On simultaneous and rafale doubles, an irregular target means a repeat with no score recorded.", "Tip: pass on a double's result as a pair, in the referee's order."], "key_points": ["Single: two cartridges allowed.", "Double: two cartridges in total, both may go at one target; kinds: on report, simultaneous, rafale.", "One shot breaks both targets: one and one.", "Not firing at a simultaneous or rafale double without reason: zero and zero."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "trap", "trajectory", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch4-single-target", "label": "4 · Single target"}, {"book": "sporting", "id": "ch2-trajectories-ethics", "label": "2 · Hunting ethics and shooting distances"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch2-doubles-composition", "label": "2 · How doubles are composed"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-target-doubles", "label": "6 · Target No Bird in doubles"}], "coach_says": [{"en": "Report pair: the second comes on your shot.", "meaning": "Coach: the second target is released by the shot at the first.", "say": null}, {"en": "On the rafale, take either one first.", "meaning": "Order is free in a rafale double.", "say": null}, {"en": "One and one.", "meaning": "Referee: both targets of the double are hits.", "say": null}, {"en": "No Bird, repeat the double.", "meaning": "Irregular target; the double is thrown again.", "say": null}], "quiz": [{"q": "Simultaneous double. One shot breaks both targets. What is the referee's decision?", "options": ["One and one", "One and No Bird", "No Bird, the double is repeated", "One and zero"], "answer": 0, "why": "In Sporting™, two targets broken with one shot in any double score one and one (Compak® Sporting differs)."}, {"q": "Double on report. The shooter breaks the first target, and a piece of it smashes the second before the second shot. Decision?", "options": ["One and one", "The double is repeated and the first result is kept", "Zero on the second target", "One and zero"], "answer": 1, "why": "When the first target or its pieces break the second before the second shot, the double is repeated and the first result stands."}, {"q": "Rafale double. Both targets fly correctly, but the shooter lowers the gun and fires at neither, giving no valid reason. Decision?", "options": ["No Bird", "Zero and No Bird", "A yellow card only", "Zero and zero"], "answer": 3, "why": "A correct target not fired at without a valid reason is lost; on a rafale or simultaneous double that means zero and zero."}]}, {"id": "sporting-viewing", "minutes": 5, "title": "Viewing the targets", "body": ["Before a squad shoots a stand, the referee has the targets shown. The presentation is for reading the targets: line, speed, distance and what the clay does. All trajectories are shown to the first shooter of the squad, who must be standing ready on the stand.", "The shooter on the stand may ask the referee to repeat the presentation, up to two targets for each target of the menu sequence.", "Doubles on report are not shown, because the second target only leaves on the sound of the shot. Simultaneous and rafale doubles are shown to the first shooter of each squad and, on request, repeated up to two shown doubles.", "During the presentation guns are open and unloaded, as at every interruption, and they are closed again only when the referee allows it. Shooting or mock shooting during the presentation is forbidden and is penalised like a gun-position offence: a warning first, then a red card.", "If a trap breaks down or shooting stops for more than ten minutes, the referee shows that stand's targets again. Before the event nobody may practise on the competition layouts.", "In training, viewing is the coach's favourite moment: 'watch where it turns'. In competition the presentation is part of the event, so the coaching ban applies here as well: stay quiet unless the referee or the shooter needs a procedural translation."], "key_points": ["All trajectories are shown to the first shooter, standing ready on the stand.", "Repeats on request: up to two per target of the menu.", "Doubles on report are never shown; simultaneous and rafale doubles are.", "Guns open during the presentation; no firing or mock shooting.", "Interruption over 10 minutes: targets shown again."], "terms": ["target-presentation", "target-menu", "double-on-report", "simultaneous-double", "rafale-double", "mock-shooting", "practice", "red-card"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch16-presentation-doubles", "label": "16 · Which doubles are shown"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch16-long-interruption", "label": "16 · Interruption over 10 minutes"}, {"book": "sporting", "id": "ch15-no-practice", "label": "15 · No practice on competition layouts"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}], "coach_says": [{"en": "Show me the targets, please.", "meaning": "Shooter to referee: start the presentation.", "say": null}, {"en": "Again, please, B only.", "meaning": "Request to repeat one target of the menu.", "say": null}, {"en": "Guns open during the show.", "meaning": "Referee: open and unload until he allows closing.", "say": null}, {"en": "Watch where it turns.", "meaning": "Coach in training: notice the point where the clay changes direction or shape.", "say": null}], "quiz": [{"q": "Which doubles are NOT shown at the presentation?", "options": ["Simultaneous", "Rafale", "On report", "None: all are shown"], "answer": 2, "why": "The second target of a report pair leaves only on the shot, so these doubles are not presented."}, {"q": "How many repeats of a target may the shooter on the stand ask for?", "options": ["None", "Up to two for each target of the menu", "As many as needed", "One per stand"], "answer": 1, "why": "On request the referee repeats the presentation, up to two targets for each target in the menu sequence."}, {"q": "During the presentation a shooter closes his gun and swings along a target's line. What applies?", "options": ["It is forbidden: the gun-position penalties apply, a warning and then a red card", "Nothing: viewing is free", "The target is shown again", "Only the coach is warned"], "answer": 0, "why": "Guns stay open during the presentation, and firing or mock firing is penalised under the warning and red-card rules."}]}, {"id": "sporting-malfunctions", "minutes": 5, "title": "Gun and cartridge malfunctions", "body": ["A malfunction is a failure of gun or cartridge: a misfire, a dead second barrel, or both barrels firing together (double discharge). In Parcours de Chasse – Sporting™ incidents are counted per round of 25 targets.", "First, what the shooter must do: stay in place, gun pointing down the range, without opening it or touching the safety until the referee has examined it. Opening the gun or touching the safety first means the target or targets are scored zero.", "The first incident in a round is a No Bird with a warning, and the target is repeated. From the second incident in the same round, the target is no longer repeated but scored zero.", "Details of a first incident: if the first shot fails, a single or any double is repeated, but if the shooter still fires the second shot, that result stands. If the second shot fails on a single, the target is repeated and may then only be broken with the second shot; a first-shot break scores zero. On a double on report the first result is kept and the double repeated. A double discharge on a single, or on the first target of any double, is a No Bird with nothing recorded.", "If the gun is fixed before the squad finishes the stand, the shooter may shoot last with the referee's permission; otherwise he may continue at once with another gun, or finish in another squad with the jury's approval. Gun, choke or barrel may not be changed once he is on the stand."], "key_points": ["After a failure: stay put, gun down range, do not open it or touch the safety.", "First incident in a round: No Bird + warning, target repeated.", "Second incident in the same round: zero, no repeat.", "Second-shot failure on a single: on the repeat only a second-shot break counts."], "terms": ["malfunction", "double-discharge", "no-bird", "zero", "safety-catch", "round", "choke", "barrel"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}, {"book": "sporting", "id": "ch6-malfunction-first-shot", "label": "6 · Malfunction on the first shot"}, {"book": "sporting", "id": "ch6-malfunction-second-shot", "label": "6 · Malfunction on the second shot"}, {"book": "sporting", "id": "ch6-second-malfunction", "label": "6 · Second malfunction in the same round"}, {"book": "sporting", "id": "ch6-double-discharge", "label": "6 · Double discharge (both barrels fire together)"}, {"book": "sporting", "id": "ch7-double-discharge", "label": "7 · Double discharge due to a gun fault"}, {"book": "sporting", "id": "ch7-malfunction-procedure", "label": "7 · What happens after a gun malfunction"}, {"book": "sporting", "id": "ch7-borrow-replace", "label": "7 · Borrowing or replacing a gun, choke or barrel"}, {"book": "sporting", "id": "ch7-no-changes-on-stand", "label": "7 · No changes once on the stand"}], "coach_says": [{"en": "Stay there, don't open the gun.", "meaning": "Referee: wait for the inspection; opening first costs the target.", "say": null}, {"en": "Let me see the gun.", "meaning": "The referee examines the gun or cartridge.", "say": null}, {"en": "Malfunction. No Bird, first warning.", "meaning": "First incident in the round: the target is repeated.", "say": null}, {"en": "Second malfunction this round. Zero.", "meaning": "No repeat this time; the target is lost.", "say": null}], "quiz": [{"q": "First gun problem of the round: on a single the first cartridge misfires. The shooter waits, gun down range, for the referee. Decision?", "options": ["Zero", "No Bird with a warning; the target is repeated", "One", "Yellow card and zero"], "answer": 1, "why": "The first gun or ammunition incident in a round is a No Bird with a warning, and the single is repeated."}, {"q": "The cartridge misfires, and the annoyed shooter breaks the gun open to look at the primer before the referee arrives. Decision?", "options": ["No Bird", "The target is repeated after a warning", "Zero", "Red card, and the target is repeated"], "answer": 2, "why": "Opening the gun or touching the safety before the referee's check means the target is scored zero."}, {"q": "Single, first incident: the first shot misses and the second cartridge misfires, so the target is repeated. On the repeat the shooter breaks it with the first shot. Decision?", "options": ["One", "No Bird again", "One, with a warning", "Zero: on this repeat only a second-shot break counts"], "answer": 3, "why": "After a second-shot failure the repeated single may only be broken with the second shot, so the first shot must be a deliberate miss."}]}, {"id": "sporting-time-and-lateness", "minutes": 5, "title": "Time limits and lateness", "body": ["Parcours de Chasse – Sporting™ runs on a tight rhythm, and several rules protect it. When the shooter calls 'pull' or 'ready', the referee relays the call to the trapper by an audio signal, and the target must leave within three seconds; a later target is a No Bird.", "Between singles, or between doubles, the shooter has at most 15 seconds. The first time this is exceeded the referee gives a warning; after that the red-card penalties apply. After a final decision on a protest, the shooter must resume within 15 seconds, otherwise it counts as refusal to comply; deliberate stalling is treated the same way.", "Lateness: when a shooter is missing, the referee calls the name and number three times within one minute. Arriving before one's turn on the singles of the first stand costs nothing. After that, every target not shot is zero; joining at a later stand means all targets of earlier stands are zero. A layout with missed stands can never be shot again in another squad.", "A shooter late for reasons outside their control must not rejoin the squad in that round but appeal to the jury in writing. If the jury accepts, the round is shot in another squad; if not, 25 zeros for each layout not shot.", "Stepping onto the stand without hearing protection or safety glasses counts as being absent. For an unscheduled shoot-off, shooters must be ready within 15 minutes of being called.", "For you: never hold the squad up with a long translation. Short now, details after the stand."], "key_points": ["Target within 3 seconds of the referee's signal, otherwise No Bird.", "Max 15 seconds between singles or doubles: warning, then red card.", "Resume within 15 seconds after a final ruling, or it is refusal to comply.", "Late: name and number called three times in one minute; missed targets are zero."], "terms": ["call", "trapper", "no-bird", "firing-time", "red-card", "jury", "hearing-protection", "safety-glasses", "shoot-off"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch10-deliberate-delay", "label": "10 · Deliberate delay or unfair behaviour"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch16-late-excuse", "label": "16 · Lateness beyond the shooter's control"}, {"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}], "coach_says": [{"en": "Shooter number twenty-three!", "meaning": "Referee calling a missing shooter (three times within a minute).", "say": null}, {"en": "Watch your time.", "meaning": "Reminder of the 15-second limit between targets.", "say": null}, {"en": "Over fifteen seconds. This is a warning.", "meaning": "First time over the limit: warning; next time a penalty.", "say": null}, {"en": "Glasses on, or you can't shoot.", "meaning": "Without eye protection the shooter is treated as absent.", "say": null}], "quiz": [{"q": "The shooter calls, the referee relays the signal, but the target leaves about five seconds later. The shooter fires and misses. Decision?", "options": ["Zero", "No Bird", "One", "A warning for the shooter"], "answer": 1, "why": "A target released more than three seconds after the referee's signal is a No Bird."}, {"q": "A shooter arrives while his squad is still shooting singles on stand 1, before his turn has come. What happens?", "options": ["He joins without penalty", "25 zeros", "Zero on all singles of stand 1", "He must shoot with another squad"], "answer": 0, "why": "Arriving before missing one's turn on the singles of the first stand carries no penalty."}, {"q": "Between two singles a shooter takes about 25 seconds, for the first time today. Decision?", "options": ["Zero on the next target", "Red card", "No consequence at all", "A warning from the referee"], "answer": 3, "why": "The limit is 15 seconds; the first time it is exceeded the referee warns, and only then do penalties follow."}]}]}, {"id": "compak", "icon": "grid", "title": "Compak® Sporting rules", "intro": "Compak® Sporting packs the variety of Parcours de Chasse – Sporting™ into a small field: five stations in a line, six traps and a fixed rectangle the targets must fly over. Many rules look the same, but gun position, time limits, doubles and penalties differ. An interpreter who mixes the two disciplines up gives a shooter wrong information.", "lessons": [{"id": "compak-layout-rotation", "minutes": 5, "title": "Layout, menu and rotation", "body": ["A Compak® Sporting layout is compact by design. The targets must fly over a marked rectangle 35 to 40 m wide and 25 m deep, with a flag or marker at each corner. Facing it are five shooting stations, each a 1 m square, in a line 4 to 8 m behind the front side; station 3 sits in the middle.", "There are six traps, lettered A to F from left to right, each with a sign. Every Compak® must include a left-to-right crosser, a right-to-left crosser and a going-away target; the other trajectories are the organiser's choice. Each station has a firing angle limiter, a frame that stops the gun swinging too far and keeps the shooter inside the station.", "A round is 25 targets, five at each station: five singles, three singles and a double, or one single and two doubles. On one Compak® the double type is the same at all stations. The menu, the order of targets, is posted at every station, and the first target of each double is the last target shot at the previous station.", "Rotation in a squad of up to six: station 1 always starts, and the sixth shooter waits behind it. When the shooter on station 5 finishes, he goes to wait behind station 1, everyone moves one station to the right, and the waiting shooter steps onto station 1. Stations are changed with the gun open and unloaded, without disturbing anyone still shooting.", "In-line Compak® works differently: each shooter of a group goes from station 1 to station 5."], "key_points": ["Rectangle 35–40 m × 25 m; five 1 m stations; six traps A–F.", "Compulsory: left-to-right crosser, right-to-left crosser, going-away target.", "Round = 25 targets, 5 per station; one double type per Compak®.", "Each double starts with the last target of the previous station.", "After station 5: wait behind station 1; everyone moves one station right."], "terms": ["trap", "target-menu", "round", "squad", "rotation", "crosser", "going-away", "shooting-stand", "double", "fly-over-rectangle", "firing-angle-limiter", "waiting-position"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}, {"title": "Wikipedia — Compak Sporting", "url": "https://en.wikipedia.org/wiki/Compak_Sporting"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch2-terrain", "label": "2 · The target fly-over rectangle"}, {"book": "compak", "id": "ch2-shooting-positions", "label": "2 · Five shooting positions: size and spacing"}, {"book": "compak", "id": "ch2-traps", "label": "2 · Six traps, A to F"}, {"book": "compak", "id": "ch3-compulsory-trajectories", "label": "3 · Three compulsory trajectories"}, {"book": "compak", "id": "ch3-free-trajectories", "label": "3 · Free trajectories"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch17-menu", "label": "17 · The menu card at each station"}, {"book": "compak", "id": "ch17-double-chain", "label": "17 · Each double starts with the last target of the previous station"}, {"book": "compak", "id": "ch17-squads-groups", "label": "17 · Size of squads and groups"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Move one station to the right.", "meaning": "Rotation after the shooter on station 5 has finished.", "say": null}, {"en": "Gun open when you change stations.", "meaning": "Between stations the gun is open and unloaded.", "say": null}, {"en": "Your double starts with the last target of the previous station.", "meaning": "The chain rule of the Compak® menu.", "say": null}, {"en": "You're waiting behind one.", "meaning": "The sixth shooter stands behind station 1.", "say": null}], "quiz": [{"q": "How many traps and stations does a Compak® Sporting layout have?", "options": ["4 traps, 3 stations", "6 traps, 5 stations", "5 traps, 5 stations", "8 traps, 6 stations"], "answer": 1, "why": "A Compak® uses six traps, A to F, and five shooting stations."}, {"q": "The shooter on station 5 has finished his menu. Where does he go?", "options": ["To station 1", "He stays on station 5", "Behind station 1, to wait", "To the referee to sign the sheet"], "answer": 2, "why": "He becomes the waiting shooter behind station 1 while everyone else moves one station to the right."}, {"q": "On a Compak®, the first target of each double is…", "options": ["any target the shooter chooses", "always trap A", "a target shown only on request", "the last target shot at the previous station"], "answer": 3, "why": "The menu chains the stations: each double begins with the target that ended the station before."}]}, {"id": "compak-gun-and-call", "minutes": 5, "title": "Gun position, the call and time", "body": ["Here Compak® Sporting differs most visibly from Parcours de Chasse – Sporting™. At the call the gun position is free: the gun may already be at the shoulder, or not. There is no gun-down start and no line on the vest. Every target is still shot with the gun at the shoulder.", "Release: traps are freed by hand, by remote control or by a voice-activated sonopull. With manual release the target must leave 0 to 3 seconds after the call; a sonopull has a fixed delay of 0.5 seconds. International in-line events use sonopull only. A target released more than 3 seconds after the call, or one the shooter did not call for, is a No Bird.", "Time: the shooter has at most 10 seconds to call after the previous station's target has been shot, shorter than the 15 seconds in Sporting™. The first time, the referee notes a warning on the score sheet; if it happens again in the same round, it is a red card and the targets are scored: single zero, double on report zero and No Bird, simultaneous double zero and zero.", "Viewing: in squad shooting the targets are shown once in the morning, to the first squad. The shooter on station 1 calls each single, A to F; then the referee shows the simultaneous doubles and says 'start' or 'competition'. After an interruption of more than 10 minutes, the six singles are shown again.", "Loading: only on your own station, gun open and pointing down range inside the angle limiter; close it only when it is your turn."], "key_points": ["Gun position at the call is free; shots always from the shoulder.", "Manual release 0–3 s after the call; sonopull fixed 0.5 s; later than 3 s = No Bird.", "Max 10 seconds to call: warning noted, then targets scored zero.", "Targets are shown once in the morning to the first squad; again after a break over 10 minutes."], "terms": ["ready-position", "call", "sonopull", "no-bird", "firing-time", "score-sheet", "target-presentation", "loading"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch2-trigger-inline", "label": "2 · Equipment for Compak in line"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}], "coach_says": [{"en": "Start! / Competition!", "meaning": "Referee: the presentation is over and scored shooting begins.", "say": null}, {"en": "Gun up or down, your choice here.", "meaning": "Coach: in Compak® the gun position at the call is free.", "say": null}, {"en": "Ten seconds, call your target.", "meaning": "Reminder of the 10-second limit to call.", "say": null}, {"en": "Warning: time.", "meaning": "First time over 10 seconds; noted on the score sheet.", "say": null}], "quiz": [{"q": "In Compak® Sporting a shooter calls with the gun already at the shoulder. What is the referee's decision?", "options": ["Yellow card", "Allowed: the gun position at the call is free", "Zero", "Allowed only on doubles"], "answer": 1, "why": "Compak® Sporting has no gun-down start and no vest line; only the shot itself must be fired from the shoulder."}, {"q": "Manual release. The target leaves about four seconds after the call, and the shooter misses. Decision?", "options": ["Zero", "One", "A warning for the trapper only, zero stands", "No Bird"], "answer": 3, "why": "A target released more than 3 seconds after the call is a No Bird and is thrown again."}, {"q": "For the second time in the same round, a shooter takes more than 10 seconds to call. The target is a single. Decision?", "options": ["Zero", "Another warning only", "No Bird", "Expulsion"], "answer": 0, "why": "After the first warning, a repeat in the same round is penalised by the table: a single is scored zero."}]}, {"id": "compak-singles-doubles", "minutes": 5, "title": "Singles and doubles in Compak®", "body": ["Compak® Sporting uses the same words as Parcours de Chasse – Sporting™, but its doubles follow different rules. An interpreter who carries the Sporting™ rules over will give wrong answers.", "Singles: every single must allow two shots from each of the five stations, so the second barrel is a legitimate second chance.", "The Compak® rulebook defines two kinds of double: on report (the call releases the first target, the shot releases the second; one or two traps) and simultaneous (two targets on one call, always from two different traps, taken in either order). There is no rafale.", "The key difference: in a Compak® double only one cartridge may be fired at each target. Firing both shots at the first target is prohibited, and the referees' quick guide scores a deliberate double shot at one target zero and zero. In Sporting™ both cartridges may go at one target.", "Two targets with one shot: on a double on report the first result stands, the second is a No Bird, and the double is shot again. On a simultaneous double it is a No Bird with nothing scored and the double repeated; the same the second time; the third time it is zero and zero. In Sporting™ the same shot simply scores one and one.", "Irregular targets: if the first target of a report pair, or either target of a simultaneous double, is irregular, a new double is thrown. If the second target of a report pair is irregular or broken by the first, the first result stands and the double is repeated."], "key_points": ["Two kinds of double only: on report and simultaneous; no rafale.", "One cartridge per target in a double; both at one target = zero and zero (quick guide).", "Report pair, two with one shot: first result kept, second No Bird, double repeated.", "Simultaneous, two with one shot: No Bird twice, zero and zero the third time."], "terms": ["single-target", "double", "double-on-report", "simultaneous-double", "rafale-double", "no-bird", "one", "zero"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch3-trajectory-variety", "label": "3 · Varied trajectories, safe from all five stations"}, {"book": "compak", "id": "ch3-double-on-report", "label": "3 · Double on report"}, {"book": "compak", "id": "ch3-simultaneous-double", "label": "3 · Simultaneous double"}, {"book": "compak", "id": "ch17-round-combinations", "label": "17 · A round: 25 targets, 5 per station"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}, {"book": "compak", "id": "ch3-two-with-one-report", "label": "3 · Double on report: both targets broken with one shot"}, {"book": "compak", "id": "ch3-two-with-one-simultaneous", "label": "3 · Simultaneous double: both targets broken with one shot"}, {"book": "compak", "id": "ch20-target-no-bird-actions", "label": "20 · What happens after a target NO BIRD"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "sporting", "id": "ch6-two-with-one-shot", "label": "6 · Two targets broken with one shot"}], "coach_says": [{"en": "One shot per bird on the pairs here.", "meaning": "Coach: in Compak® each target of a double gets only one cartridge.", "say": null}, {"en": "Both with one shot. No Bird, shoot the double again.", "meaning": "Referee on a simultaneous double: nothing scored, repeat.", "say": null}, {"en": "Choose your order on the show.", "meaning": "Coach: decide which simultaneous target to take first while watching the presentation.", "say": null}, {"en": "Zero, zero.", "meaning": "Referee: neither target of the double is scored.", "say": null}], "quiz": [{"q": "Simultaneous double in Compak®. One shot breaks both targets; it is the first time this has happened. Decision?", "options": ["One and one", "No Bird, nothing scored, the double is repeated", "One and No Bird", "Zero and zero"], "answer": 1, "why": "In Compak® a simultaneous double broken with one shot is a No Bird the first and second time, and zero and zero the third time."}, {"q": "Double on report in Compak®. One shot breaks both targets. Decision?", "options": ["One and one", "Zero and zero", "The first result stands, the second is a No Bird, and the double is repeated", "No Bird, nothing scored"], "answer": 2, "why": "On a report pair the first target's result is recorded and the double is shot again to score the second."}, {"q": "In a Compak® double, a shooter misses the first target and deliberately fires the second cartridge at it as well. How does the referees' quick guide score it?", "options": ["Zero and zero", "It is allowed, as in Sporting™", "The double is repeated", "Only the second shot counts"], "answer": 0, "why": "Only one cartridge per target is allowed in a Compak® double; a deliberate double shot at one target is zero and zero."}]}, {"id": "compak-malfunctions", "minutes": 5, "title": "Malfunctions in Compak®", "body": ["In Compak® Sporting, as in Parcours de Chasse – Sporting™, gun and cartridge failures are counted per round of 25 targets: the first incident brings a No Bird and a yellow card; with a second incident of the same type, the targets not shot at are scored zero, with a red card.", "What the shooter must do: stay in place, gun pointed down range, without opening it or touching the safety catch until the referee has inspected it. Opening it first costs the target or targets: zero.", "First incident, when both barrels fire together or the first cartridge fails: a single is thrown again, a double on report or a simultaneous double is thrown again, and nothing is scored from the failed attempt. When the second cartridge fails: on a single the target is thrown again, but only the second shot can score, so the first must be a deliberate miss; on a report pair the first result stands and the double is repeated for the second; on a simultaneous double, a new double.", "After a malfunction the shooter has two minutes to repair or replace the gun. As an exception he may borrow a gun from a shooter outside his own squad, with the owner's and the referee's agreement. Without a working gun, the remaining targets are zero. Otherwise no gun, choke or barrel may be changed within a round.", "The same logic covers a rabbit missed with the first shot that breaks before the second: No Bird, and on the repeat only the second shot counts."], "key_points": ["First incident in a round: No Bird + yellow card; second of the same type: zero + red card.", "Do not open the gun or touch the safety before the referee's inspection.", "Second-cartridge failure on a single: on the repeat only the second shot counts.", "Two minutes to repair or replace; borrow only from outside your squad, with owner's and referee's consent."], "terms": ["malfunction", "double-discharge", "safety-catch", "no-bird", "zero", "yellow-card", "red-card", "rabbit", "choke"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": {"type": "call"}, "rule_refs": [{"book": "compak", "id": "ch20-gun-failure-principle", "label": "20 · Gun or cartridge failures: first and second incident"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-malfunction", "label": "21 · Malfunction: inspection, 2 minutes, replacement gun"}, {"book": "compak", "id": "ch20-gun-failure-first-shot", "label": "20 · Both barrels fire together or the first cartridge fails"}, {"book": "compak", "id": "ch20-gun-failure-second-shot", "label": "20 · The second cartridge fails"}, {"book": "compak", "id": "ch12-borrowing", "label": "12 · Borrowing a gun after a breakdown"}, {"book": "compak", "id": "ch13-shared-gun", "label": "13 · No sharing a gun within a group"}, {"book": "compak", "id": "ch18-gun-change", "label": "18 · No changing gun, chokes or barrels during a round"}, {"book": "compak", "id": "ch20-rabbit", "label": "20 · A rabbit that breaks between the shots"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "sporting", "id": "ch6-nobird-gun-rules", "label": "6 · Gun or ammunition fault: first incident in a round"}], "coach_says": [{"en": "Don't move, keep the gun closed.", "meaning": "Referee: wait for the inspection after a failure.", "say": null}, {"en": "First malfunction. Yellow card, No Bird.", "meaning": "First incident of this type in the round; the target is thrown again.", "say": null}, {"en": "You have two minutes.", "meaning": "Time to repair or replace the gun.", "say": null}, {"en": "Only the second shot counts on this one.", "meaning": "Repeat after a second-cartridge failure: miss with the first shot on purpose.", "say": null}], "quiz": [{"q": "First incident of the round in Compak®: the first cartridge fails on a single. The shooter waits correctly. Decision?", "options": ["No Bird with a yellow card; a new target is thrown", "Zero", "Red card and zero", "One"], "answer": 0, "why": "The first gun or cartridge incident in a round is a No Bird with a first warning shown by a yellow card."}, {"q": "A shooter's gun breaks down. He wants to borrow a squad-mate's gun. Is it allowed?", "options": ["Yes, with the owner's consent", "Yes, if the referee agrees", "Yes, without conditions", "No: the lender must be outside his squad, and both owner and referee must agree"], "answer": 3, "why": "Compak® forbids sharing a gun within a group; exceptional borrowing is only from outside it, with both agreements."}, {"q": "Second gun failure of the same type in this round, on a single the shooter could not shoot at. Decision?", "options": ["No Bird again", "No Bird and a warning", "Zero, with a red card", "The target is shown again"], "answer": 2, "why": "From the second incident of the same type, targets not shot at are scored zero."}]}, {"id": "compak-dress-and-conduct", "minutes": 5, "title": "Dress and conduct", "body": ["Compak® Sporting events are public, so dress must be suitable and practical. Short shorts are banned, but Bermudas ending no more than 5 cm above the knee are fine. Tops need at least short sleeves and must reach the neck; a T-shirt is fine, but not a bare chest under the vest. Sandals are forbidden in practice and in competition. The number is worn on the back, fully visible; a first breach brings a warning, then sanctions.", "Ear and eye protection are compulsory. Arriving at the station without them counts as absence: no shooting.", "Punctuality: report to the referee in time. In squad shooting, arriving after the first shooter of the squad has called for the first target costs 25 zeros for the round; an appeal goes to the jury in writing on the same day.", "Conduct: coaching during competition is forbidden; the competitor gets a yellow card and the coach is removed from the shooting area. Disputing a final decision after shooting resumes, or openly criticising a decision as a shooter or spectator, is an attempt to influence the referee and can lead to exclusion. At the end of every round the shooter signs the score sheet; refusing to sign means losing the right to complain.", "Near the stand you are part of the public: wear protection, keep quiet during the call, never comment on a decision. Whether you may relay a coach's words in competition is an open question for FITASC; the safe practice is to interpret only for the referee, jury and organiser."], "key_points": ["No short shorts, no bare chest under the vest, no sandals (also in practice); number on the back.", "No ear or eye protection at the station = absent, no shooting.", "Late after the squad's first call: 25 zeros; same-day written appeal possible.", "No coaching; no public criticism of decisions; sign the score sheet."], "terms": ["dress-code", "competitor-number", "hearing-protection", "safety-glasses", "conduct", "yellow-card", "score-sheet", "protest", "quiet-on-stand"], "sources": [{"title": "FITASC — Sports disciplines: presentation", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-late-appeal", "label": "9 · Appealing a lateness penalty"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}], "coach_says": [{"en": "Number on your back, please.", "meaning": "Referee: the competition number must be fully visible on the back.", "say": null}, {"en": "Ears and eyes on.", "meaning": "Put on hearing protection and glasses before the station.", "say": null}, {"en": "Sign the sheet, please.", "meaning": "End of round: the shooter signs the score sheet.", "say": null}, {"en": "No coaching on the stand.", "meaning": "Referee warning: coaching is forbidden in competition.", "say": null}], "quiz": [{"q": "A shooter comes to the station in sandals for a practice round. Is it allowed?", "options": ["Yes, in practice only", "No: sandals are forbidden in practice and in competition", "Yes, with socks", "Only with the referee's permission"], "answer": 1, "why": "The Compak® dress code bans sandals for safety in practice and in competition."}, {"q": "Squad shooting. A shooter arrives just after the first shooter of his squad has called for the first target. Result?", "options": ["No penalty", "Zero on the first target only", "He shoots at the end of the squad", "25 zeros for the round; a same-day written appeal to the jury is possible"], "answer": 3, "why": "The deadline is the squad's first call; after it the late shooter gets 25 zeros unless the jury accepts a valid reason."}, {"q": "After the round a shooter refuses to sign the score sheet because he disagrees with one call. What is the consequence?", "options": ["He loses the right to make any complaint", "The referee must change the result", "The round is shot again", "Nothing happens"], "answer": 0, "why": "Signing the sheet at the end of every round is compulsory; refusing to sign makes any complaint inadmissible."}]}]}, {"id": "referee", "icon": "whistle", "title": "Referee, scoring and penalties", "intro": "In a competition the referee is the person whose words you will translate most often and most carefully. This mission gives you the spoken calls, the score card, the cards and penalties, the protest procedure and the age categories, so that every decision reaches your shooter exactly as it was made.", "lessons": [{"id": "referee-calls", "minutes": 5, "title": "What the referee says on the stand", "body": ["A stand has its own short language. The shooter gives the call when ready, usually “Pull!” or “Ready!”. In Parcours de Chasse – Sporting™ the referee passes that call to the trapper with a sound signal, and the target must leave within three seconds; a later target is a No Bird. In Compak® Sporting a manual release must also come within three seconds of the call, and a voice release (sonopull) has a fixed half-second delay.", "Before anyone shoots, the referee controls the gun. Loading is allowed only on the stand, gun pointing down the range, once the referee has said shooting may start. While targets are being shown, and whenever shooting stops, guns are open and empty and are closed again only on the referee’s word. In Compak® the referee starts the round with “Start” or “Competition”.", "After each target the rules know three results: “one” (hit), “zero” (lost) and “No Bird” (the target does not count and is thrown again). Around the world you will also hear “dead”, “good”, “lost” or simply silence for a hit. In Compak® the referee must announce every zero aloud or with a sound signal, so a shooter who disagrees can protest at once.", "The shooter has one formal word too: with a raised hand, “Protest!” or “Appeal!”. When you interpret, keep these calls short and identical every time. Agree with your shooter before the round which words you will use, and never add anything of your own between the call and the shot."], "key_points": ["The shooter calls “Pull!” or “Ready!”; the target must come within 3 seconds", "Load only on the stand and only when the referee allows it; guns open during viewing and stops", "Rule words: one = hit, zero = lost, No Bird = thrown again", "Compak®: every zero is announced aloud or by a sound signal", "Protest = raised hand + “Protest!” or “Appeal!”"], "terms": ["call", "referee", "trapper", "sonopull", "one", "zero", "no-bird", "loading", "target-presentation", "protest"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": {"type": "call"}, "rule_refs": [{"book": "sporting", "id": "ch5-call-and-release", "label": "5 · Calling for the target and the 3-second release"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch5-referee-oath", "label": "5 · Referee's commitments"}, {"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "compak", "id": "ch2-trigger-manual", "label": "2 · Releasing targets: manual, remote, sonopull"}, {"book": "compak", "id": "ch17-squad-show-targets", "label": "17 · Squad: showing the targets"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}], "coach_says": [{"en": "You may load.", "meaning": "The referee allows shooting to start: put cartridges in now, gun pointing down the range.", "say": null}, {"en": "No bird!", "meaning": "That target does not count; do not shoot at it. It will be thrown again.", "say": null}, {"en": "Lost.", "meaning": "The referee scored the target as a miss (zero).", "say": null}, {"en": "Dead. / Good.", "meaning": "The target is a hit (one).", "say": null}, {"en": "Guns open, please — we’re showing the targets.", "meaning": "Everyone opens and unloads; the referee will throw the targets for viewing.", "say": null}, {"en": "Start. / Competition.", "meaning": "Compak®: viewing is over, the round counts from now.", "say": null}], "quiz": [{"q": "In Parcours de Chasse – Sporting™ the target leaves five seconds after the referee’s signal. What is the call?", "options": ["It counts as normal", "No Bird", "Zero, because the shooter called too early", "A warning for the trapper only"], "answer": 1, "why": "A target must leave within three seconds of the referee’s signal; a later one is a No Bird and is thrown again."}, {"q": "When may a shooter load the gun?", "options": ["While walking to the stand", "Behind the stand while waiting", "On the stand, gun pointing down the range, after the referee allows shooting", "Whenever the coach says so"], "answer": 2, "why": "Loading is allowed only on the stand, pointing down the range, and only once the referee has authorised the start."}, {"q": "Which word starts a formal protest on the stand?", "options": ["“Protest!” or “Appeal!” with a raised hand", "“Pull!”", "“No bird!”", "“Referee, look!”"], "answer": 0, "why": "Both rulebooks name “protest” or “appeal” with a raised hand; “No bird” belongs to the referee alone."}]}, {"id": "referee-scoring", "minutes": 5, "title": "Score cards, results and ties", "body": ["Every target ends up on a score card. In Parcours de Chasse – Sporting™ the referee keeps the card, or someone the referee supervises. The FITASC model shows the trap letter of every target, with X for a hit and O for a miss, a total and a signature column. Before the squad moves on, the referee photographs the card.", "Shooters must check their score when leaving each stand. A disagreement goes to the referee at once; the referee decides, possibly after asking others, and after that there is no appeal. In Compak® Sporting the shooter signs the score sheet at the end of the round, and a shooter who refuses to sign loses the right to complain. Translate “check your card” as an urgent instruction, not a polite remark.", "An international event is 200 targets in rounds of 25. When shooters tie for the first three places, they shoot a shoot-off of 25 targets; if they are still level, sudden death follows, where the first zero eliminates. Below third place there is no shoot-off: tied shooters share the place and are ordered by countback, from the last (eighth) layout or Compak® back to the first. Teams never shoot off.", "Shoot-offs bring one more interpreter trap. If no time was fixed, the shooters must be ready within fifteen minutes of the call. A missing shooter is “disqualified” in the Sporting™ rules and “considered withdrawn” in the Compak® rules. Use the word of the discipline you are at."], "key_points": ["X = hit, O = miss on FITASC score cards", "Sporting™: check your score when leaving each stand; Compak®: sign the sheet or lose the right to complain", "Ties for places 1–3: 25-target shoot-off, then sudden death", "Below 3rd: countback from the 8th layout or Compak®; no team shoot-offs", "Ready within 15 minutes of a shoot-off call"], "terms": ["score-sheet", "round", "one", "zero", "shoot-off", "countback", "team", "referee"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch14-who-keeps-score", "label": "14 · Who keeps the scorecard"}, {"book": "sporting", "id": "ch14-model", "label": "14 · Scorecard model"}, {"book": "sporting", "id": "ch16-results-check", "label": "16 · Recording results and checking your score"}, {"book": "sporting", "id": "ch16-format", "label": "16 · 200 targets in rounds of 25"}, {"book": "sporting", "id": "ch18-top-three", "label": "18 · Shoot-off for the top three; ties below"}, {"book": "sporting", "id": "ch18-sudden-death", "label": "18 · Shoot-off format and sudden death"}, {"book": "sporting", "id": "ch18-squad-and-timing", "label": "18 · Shoot-off squads, call-up and postponement"}, {"book": "sporting", "id": "ch18-team-ties", "label": "18 · Team ties"}, {"book": "compak", "id": "ch15-who-keeps", "label": "15 · Who keeps the score sheet"}, {"book": "compak", "id": "ch15-zero-announce", "label": "15 · Announcing zeros; marks O and X"}, {"book": "compak", "id": "ch15-signing", "label": "15 · Signing the score sheet"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}, {"book": "compak", "id": "ch14-shootoff-availability", "label": "14 · Staying available for a shoot-off"}, {"book": "compak", "id": "ch14-countback", "label": "14 · Ties below third place: countback"}, {"book": "compak", "id": "ch14-team-ties", "label": "14 · Ties between national teams"}], "coach_says": [{"en": "Check your card before you leave the stand.", "meaning": "Look at your marks now; later objections are not accepted.", "say": null}, {"en": "Sign here, please.", "meaning": "Compak®: signing confirms the score; refusing means losing the right to complain.", "say": null}, {"en": "Twenty-three — you dropped two.", "meaning": "Score 23 of 25; two targets were lost.", "say": null}, {"en": "There’s a tie for third — shoot-off in fifteen minutes.", "meaning": "Be at the named layout and ready to shoot within fifteen minutes.", "say": null}, {"en": "Sudden death: first zero is out.", "meaning": "After the 25-target shoot-off, the first shooter to miss (with an equal number of targets shot) is eliminated.", "say": null}], "quiz": [{"q": "On a FITASC score card, what does O mean?", "options": ["A hit", "A No Bird", "A miss", "An empty stand"], "answer": 2, "why": "The FITASC model marks a hit with X and a miss with O."}, {"q": "Two shooters tie for 7th place. What happens?", "options": ["A 25-target shoot-off", "Sudden death at once", "A coin toss by the jury", "They share the place and are ordered by countback"], "answer": 3, "why": "Shoot-offs are only for places 1–3; below that, tied shooters are listed by countback from the eighth layout or Compak®."}, {"q": "In Compak® Sporting your shooter refuses to sign the score sheet. What is the consequence?", "options": ["He loses the right to make any complaint", "The round is shot again", "The referee signs and nothing changes", "He gets 25 zeros automatically"], "answer": 0, "why": "The Compak® rules say a shooter who refuses to sign loses the right to complain."}]}, {"id": "referee-cards", "minutes": 5, "title": "Warnings, cards and penalties", "body": ["FITASC penalties climb a ladder. By entering a competition a shooter accepts the rules and the sanctions. The first breach of a rule normally brings a warning, shown with a yellow card. In Parcours de Chasse – Sporting™ a classic example is the gun position: a stock above the line on the vest, or a gun mounted before the target appears, earns a verbal warning and a yellow card.", "A repeat on the same layout (or the same Compak®) brings a red card, and the target is scored by a table: zero on a single, zero and No Bird on a double on report, zero and zero on a simultaneous or rafale double. The same scale applies to shooting at a declared No Bird and, in Sporting™, to exceeding fifteen seconds between targets. In Compak® Sporting the limit is ten seconds to call.", "Coaching during a competition is penalised too: the shooter gets a yellow card, repeats lead to further sanctions, and the referee sends the person who coached out of the shooting area. For an interpreter this is the most important card in the book.", "For repeat offences, refusal to comply or attempts to influence a referee, the jury can take away one target, a whole round of 25, or expel the shooter. Throwing a gun, abuse or violence, and deliberately shooting at live animals can mean immediate expulsion. An expulsion is recorded by FITASC for five years and brings no refund. Translate “warning”, “yellow card” and “red card” literally, calmly, and at once."], "key_points": ["First breach: warning with a yellow card", "Repeat on the same layout or Compak®: red card + target scored by the table", "Coaching in competition: yellow card for the shooter, coach removed", "Jury scale: one target, one round, or expulsion", "Expulsion: kept on record 5 years, no refund"], "terms": ["yellow-card", "red-card", "penalty", "ready-position", "firing-time", "jury", "conduct"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch13-acceptance", "label": "13 · Acceptance of rules; first breach = warning"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "sporting", "id": "ch12-red-card", "label": "12 · Red card on repeat at the same layout"}, {"book": "sporting", "id": "ch12-shooting-nobird", "label": "12 · Shooting at a declared No Bird"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch13-jury-penalties", "label": "13 · Jury penalty scale"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "sporting", "id": "ch13-immediate-expulsion", "label": "13 · Immediate expulsion"}, {"book": "sporting", "id": "ch13-expulsion-record", "label": "13 · Expulsion record and lifetime ban"}, {"book": "sporting", "id": "ch13-no-refund", "label": "13 · No refund after expulsion"}, {"book": "compak", "id": "ch23-yellow-card", "label": "23 · Accepting the rules; first a yellow card"}, {"book": "compak", "id": "ch21-firing-time", "label": "21 · 10 seconds to call: warning, then penalty"}, {"book": "compak", "id": "ch21-penalty-table", "label": "21 · Penalty table after a first warning"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch23-jury-sanctions", "label": "23 · Sanctions for reoffending or influence"}, {"book": "compak", "id": "ch23-exclusion-record", "label": "23 · Exclusions: record, repeat, no refund"}], "coach_says": [{"en": "Warning — your stock was above the line.", "meaning": "Sporting™: the gun was too high before the target appeared; next time on this layout it costs the target.", "say": null}, {"en": "That’s a yellow card.", "meaning": "An official first warning; it is recorded.", "say": null}, {"en": "Red card — the target is zero.", "meaning": "A repeat offence: the target is scored as lost.", "say": null}, {"en": "You’re over time.", "meaning": "The shooter took longer than allowed (15 s in Sporting™, 10 s to call in Compak®).", "say": null}, {"en": "Sir, please leave the shooting area.", "meaning": "The referee is removing someone, for example a person caught coaching.", "say": null}], "quiz": [{"q": "Sporting™: after a yellow card for a mounted gun, the shooter mounts early again on the same layout, on a single. What is the result?", "options": ["Another warning", "Red card and the target is zero", "No Bird", "Immediate expulsion"], "answer": 1, "why": "After the first warning, a further offence on the same layout brings a red card; on a single the target is zero."}, {"q": "The referee sees a coach giving advice to a shooter during a competition. What do the rules say?", "options": ["Nothing, coaching is allowed between stands", "The coach gets a red card", "The shooter gets a yellow card and the coach is removed from the shooting area", "The round is cancelled"], "answer": 2, "why": "Both rulebooks give the competitor a yellow card and have the referee send the person coaching out of the shooting area."}, {"q": "Which of these can the jury NOT impose under the penalty scale?", "options": ["Loss of one target", "Loss of a round of 25", "Expulsion", "A cash fine paid to the referee"], "answer": 3, "why": "The jury’s scale is loss of a target, loss of a round, or expulsion; there is no fine to the referee."}]}, {"id": "referee-appeals", "minutes": 5, "title": "Protests, deposits and the jury", "body": ["A protest must happen on the spot. The shooter raises a hand and says “Protest!” or “Appeal!” on the stand, before calling the next target (in Compak® Sporting, before the next shooter calls). The referee stops the shooting and listens to the reason. By calling the next target the shooter accepts the previous ruling, so as an interpreter you must be fast here.", "If the referee is sure, the decision is confirmed and becomes final. If in doubt, the referee may ask another referee, the trapper or the squad’s shooters, purely for advice, and then decides alone. Shooters may never walk out or pick up a target to check it, and a target broken behind a natural obstacle or beyond a shooting limit is the referee’s call.", "Some decisions can never go to the jury: whether a target was one or zero, a No Bird, and whether a trajectory was correct. Other decisions can be appealed to the jury in writing with a deposit: in Parcours de Chasse – Sporting™ it is 40% of the entry fee; in Compak® the amount in force on the day, and only about incidents of the same day. If the appeal succeeds, the deposit is returned.", "After the final ruling the shooter must resume within fifteen seconds in Sporting™ and ten in Compak®; otherwise it is a refusal to comply. Continuing to argue, challenging the referee for show, or other people openly criticising a ruling counts as an attempt to influence the referee. Your job is to translate the protest and the answer accurately, not to argue the case."], "key_points": ["Protest immediately, on the stand, hand raised: “Protest!” / “Appeal!”", "Calling the next target = accepting the previous ruling", "Never appealable: one/zero, No Bird, correct trajectory", "Written appeal to the jury with a deposit (Sporting™: 40% of the entry fee)", "Resume within 15 s (Sporting™) or 10 s (Compak®); further arguing = influencing the referee"], "terms": ["protest", "appeal", "jury", "referee", "entry-fee", "no-bird", "trajectory"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch9-how-to-appeal", "label": "9 · How to protest on the stand"}, {"book": "sporting", "id": "ch9-no-checking-targets", "label": "9 · No checking targets; calling the next accepts the ruling"}, {"book": "sporting", "id": "ch9-visible-break", "label": "9 · Break targets where the referee can see"}, {"book": "sporting", "id": "ch9-consultation", "label": "9 · Referee in doubt: consultation"}, {"book": "sporting", "id": "ch9-jury-appeal", "label": "9 · What can go to the jury and the 40% deposit"}, {"book": "sporting", "id": "ch9-deposit-outcome", "label": "9 · Outcome of a jury appeal"}, {"book": "sporting", "id": "ch10-resume-15s", "label": "10 · Resume shooting within 15 seconds"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch15-appeal-jury", "label": "15 · Appeal jury"}, {"book": "compak", "id": "ch19-protest", "label": "19 · How to protest a referee's call"}, {"book": "compak", "id": "ch19-consultation", "label": "19 · Referee in doubt: who may be consulted"}, {"book": "compak", "id": "ch4-complaint-limits", "label": "4 · What you cannot complain about"}, {"book": "compak", "id": "ch4-complaint-procedure", "label": "4 · How to lodge a complaint and the deposit"}, {"book": "compak", "id": "ch21-refusal-to-comply", "label": "21 · Refusal to comply: 10 seconds to resume"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Protest! The target was broken before I fired.", "meaning": "The shooter formally challenges the ruling and gives the reason (here: a broken target was thrown).", "say": null}, {"en": "I’m certain — the decision stands.", "meaning": "The referee confirms; the ruling is final.", "say": null}, {"en": "Did anyone see a piece come off?", "meaning": "The referee is in doubt and asks the squad for advice only; the referee still decides.", "say": null}, {"en": "You can take it to the jury in writing, with the deposit.", "meaning": "This decision is appealable; a written appeal and a deposit are needed.", "say": null}, {"en": "Please carry on shooting.", "meaning": "The ruling is final; resume now or it becomes a refusal to comply.", "say": null}], "quiz": [{"q": "Your shooter thinks a target scored zero was hit, but has already called the next target. Can he still protest that ruling?", "options": ["Yes, at the end of the round", "Yes, in writing to the jury", "No: calling the next target means accepting the previous ruling", "Yes, if the squad agrees"], "answer": 2, "why": "By calling the next target the shooter accepts the previous ruling, and one/zero decisions never go to the jury anyway."}, {"q": "Which decision CAN be appealed to the jury?", "options": ["Whether a target was one or zero", "A No Bird", "Whether a trajectory was correct", "Another referee decision, such as a lateness penalty"], "answer": 3, "why": "One/zero, No Bird and trajectory decisions are final; other referee decisions may go to the jury in writing with a deposit."}, {"q": "In Parcours de Chasse – Sporting™, how big is the deposit for a written appeal to the jury?", "options": ["40% of the entry fee", "The full entry fee", "A fixed 50 euros", "No deposit is needed"], "answer": 0, "why": "The Sporting™ rules set the deposit at 40% of the entry fee; it is returned if the jury agrees with the shooter."}]}, {"id": "referee-categories", "minutes": 5, "title": "Categories: Junior, Lady, Men, Senior, Veteran, Master", "body": ["Besides the open ranking, where everyone competes together, FITASC events rank shooters in categories by age and sex. From 1 January 2027 the international table for Parcours de Chasse – Sporting™ and Compak® Sporting has six categories: Junior (13–20), Lady (from 13), Men (21–55), Senior (56–65), Veteran (66–72) and Master (from 73, men and women). For events before that date, check the table then in force on the FITASC website.", "What counts is the year of birth, not the birthday. A shooter moves into a new category on 1 January of the year in which he or she reaches the age. For the 2027 season this means: Junior born 2007–2014, Men born 1972–2006, Senior 1962–1971, Veteran 1955–1961, Master born before 1955. The limits move on by one year every season.", "The biggest interpreter trap is “Senior”. In everyday English it sounds like “adult”, but in FITASC Senior means the 56–65 age group; the main adult category is Men. Do not translate it as «дорослі». “Master” is another trap: the FITASC age category from 73 has nothing to do with the NSCA “Master class”, which is a skill level.", "Teams have their own rules: usually three shooters, but the Men team in Sporting™ has four. A junior placed in the Men team, or a junior girl in the Lady team, must also enter that category individually. National federations and clubs may use their own categories, so always check the competition programme, and in shoot-offs remember that categories have their own top three."], "key_points": ["Six FITASC categories from 2027: Junior, Lady, Men, Senior, Veteran, Master", "Year of birth decides; the new category starts on 1 January", "Senior = 56–65, not “adults”; the main adult category is Men", "FITASC Master (73+) ≠ NSCA Master class", "Teams of 3; Men team in Sporting™ = 4; national programmes may differ"], "terms": ["category", "veteran", "team", "shoot-off", "entry"], "sources": [{"title": "FITASC — Categories", "url": "https://www.fitasc.com/competitions/categories"}], "sim": null, "rule_refs": [{"book": "categories", "id": "junior", "label": "Junior"}, {"book": "categories", "id": "lady", "label": "Lady"}, {"book": "categories", "id": "men", "label": "Men"}, {"book": "categories", "id": "senior", "label": "Senior"}, {"book": "categories", "id": "veteran", "label": "Veteran"}, {"book": "categories", "id": "master", "label": "Master"}, {"book": "compak", "id": "ch14-shootoff-medals", "label": "14 · Shoot-offs for the top three: 25 targets, then sudden death"}], "coach_says": [{"en": "Which category are you shooting in?", "meaning": "Asked at registration: Junior, Lady, Men, Senior, Veteran or Master.", "say": null}, {"en": "He’s a Senior now.", "meaning": "He is in the 56–65 group this season.", "say": null}, {"en": "She won the Lady category and was fourth overall.", "meaning": "First among ladies, fourth in the open ranking.", "say": null}, {"en": "There’s a shoot-off for Veteran bronze.", "meaning": "Two or more Veterans are tied for third in their category.", "say": null}], "quiz": [{"q": "A shooter born in 1971 enters a FITASC competition in 2027. Which category?", "options": ["Men", "Senior", "Veteran", "Master"], "answer": 1, "why": "He turns 56 in 2027, so he is Senior from 1 January, whatever his birthday."}, {"q": "How should you translate the FITASC category “Senior” for a client?", "options": ["“Adults”", "“Experienced shooters”", "“Top class”", "“The 56–65 age group”"], "answer": 3, "why": "In FITASC Senior is an age group of 56–65; the main adult category is Men."}, {"q": "How many shooters are in a Men team in Parcours de Chasse – Sporting™?", "options": ["Four", "Three", "Six", "Five"], "answer": 0, "why": "Teams usually have three shooters, but the Men team in Sporting™ has four."}]}]}, {"id": "etiquette", "icon": "shield", "title": "Safety and etiquette", "intro": "On a shooting ground safety comes before any translation, and good manners keep the squad calm and focused. This mission shows how guns are handled, how people behave around the stand and in a squad, and what everyone, including you, must wear.", "lessons": [{"id": "etiquette-gun-safety", "minutes": 5, "title": "Gun safety: open, empty, muzzles safe", "body": ["Every gun is treated as dangerous, even when it is empty. Off the stand it is carried open: an over-and-under broken over the forearm, a semi-automatic with the breech open, muzzles straight up or straight down. Slings are not allowed. When nobody is using it, the gun stands upright in a gun rack. Nobody touches another shooter’s gun without permission.", "Cartridges go into the gun only on the stand, with the muzzles pointing down the range, and only when the referee or instructor allows it. A semi-automatic holds no more than two. Before turning round on the stand, the shooter opens the gun and takes out every cartridge, fired or not. While targets are being shown, and during any stop, guns stay open.", "If the gun fails to fire, the shooter stays in place, gun pointing down the range, and does not open it or touch the safety until the referee has checked it. This is a safety rule and a scoring rule at once: opening early costs the target. Mounting and swinging along an imagined target off the stand, or while someone else is shooting, is not allowed either, and guns are tested only at a test stand, never on the competition stand.", "When anyone shouts “Stop!” or “Cease fire!”, everyone stops at once and opens the gun. Do not translate this into a sentence: repeat “Stop!” loudly in your guests’ language and check that their guns are open. If a guest turns towards you with a gun to ask something, point the muzzles down with a gesture first and translate afterwards."], "key_points": ["Off the stand: gun open, empty, muzzles up or down, no slings", "Load only on the stand, pointing down the range, with permission; semi-auto max 2", "Open and unload before turning round; guns open during viewing and stops", "After a misfire: stay put, do not open, wait for the referee", "“Stop!” is repeated, not explained"], "terms": ["safety", "gun-handling", "muzzle", "gun-rack", "loading", "malfunction", "mock-shooting", "gun-test", "cease-fire", "semi-automatic"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}, {"book": "sporting", "id": "ch7-touching-sharing", "label": "7 · Other shooters' guns; sharing a gun"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch8-turning-empties", "label": "8 · Turning around; empty cases"}, {"book": "sporting", "id": "ch8-presentation-interruption", "label": "8 · Gun open during presentation and interruptions"}, {"book": "sporting", "id": "ch8-malfunction-stay-put", "label": "8 · After a misfire: do not open the gun"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "sporting", "id": "ch3-testing-guns", "label": "3 · No test shots on the stand"}, {"book": "compak", "id": "ch24-carrying", "label": "24 · Carrying and storing guns"}, {"book": "compak", "id": "ch24-on-the-stand", "label": "24 · Safe procedure on the shooting position"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch24-malfunction-zero", "label": "24 · Malfunction: opening before inspection costs the target"}, {"book": "compak", "id": "ch21-open-gun", "label": "21 · Keep the gun open: turning round, target viewing, interruptions"}, {"book": "compak", "id": "ch11-testing-guns", "label": "11 · Where to test your gun"}], "coach_says": [{"en": "Guns open and empty between stands, please.", "meaning": "Walking to the next stand, the gun is broken with no cartridges inside.", "say": null}, {"en": "Break your gun and show me it’s clear.", "meaning": "Open the gun (not damage it!) so I can see the chambers are empty.", "say": null}, {"en": "Don’t load until you’re on the stand and I say so.", "meaning": "No cartridges in the gun while walking or waiting.", "say": null}, {"en": "Muzzles down when you turn round.", "meaning": "Never let the barrels point at people, even with an open gun.", "say": null}, {"en": "Stop! Stop! Guns open!", "meaning": "Emergency stop: stop shooting, open the gun, wait.", "say": null}], "quiz": [{"q": "How is a semi-automatic carried between stands?", "options": ["Closed, safety on", "With the breech open, muzzle straight up or down", "On a sling over the shoulder", "Loaded with one cartridge"], "answer": 1, "why": "Guns are carried open, semi-automatics with the breech open, muzzles straight up or down; slings are not allowed."}, {"q": "The gun clicks but does not fire. What must the shooter do?", "options": ["Open it at once and look", "Turn round to show the coach", "Stay in place, gun down the range, not open it or touch the safety until the referee checks", "Put the safety on and call again"], "answer": 2, "why": "Both rulebooks require the shooter to stay put until the referee inspects; opening or touching the safety first scores zero."}, {"q": "Someone shouts “Cease fire!”. What is the interpreter’s first job?", "options": ["Repeat “Stop!” loudly and check that guests open their guns", "Explain why shooting stopped", "Ask the coach what happened", "Wait until the guest asks"], "answer": 0, "why": "An emergency stop is repeated at once; explanations come only when every gun is open."}]}, {"id": "etiquette-on-the-stand", "minutes": 5, "title": "Around the stand: silence, distance, stillness", "body": ["A shooter on the stand needs total concentration, from loading to opening the gun after the last shot. The rules put the waiting places close to the stand but say they must not distract the shooter. In practice that means: quiet voices or none, no sudden movement in the shooter’s field of view, guns open, and phones silent and in a pocket. The rules do not mention phones, but every ground expects this courtesy.", "Stay behind the shooter, never beside or in front of the stand. In Compak® Sporting a Firing Angle Limiter frame limits the swing of each shooter; in Parcours de Chasse – Sporting™ the stands on many grounds have a cage. Everyone else waits behind it, out of any possible line of the barrels. In Compak® the waiting shooter stands behind station 1, and a shooter who has finished waits without disturbing the next one.", "Disturbing a shooter has rule consequences. If the referee sees that a shooter was clearly disturbed, the target is a No Bird and is thrown again. Simulated shooting while a squad member shoots is not allowed. Only the shooter whose turn it is shoots, and only at his or her own target.", "For you this lesson is practical. Stop talking when your guest steps onto the stand, even in the middle of a sentence. Do not answer questions while the gun is closed. Speak again only when the gun is open: between targets, between pairs, or after the stand. A missed piece of advice costs less than a pair spoiled by your voice."], "key_points": ["Quiet, still, guns open, phones silent behind the shooter", "Stand behind the stand, cage or F.A.L., never beside or in front", "A clearly disturbed shooter gets a No Bird", "No simulated shooting while someone else shoots", "Interpreter: speak only when the gun is open"], "terms": ["quiet-on-stand", "shooting-stand", "conduct", "no-bird", "mock-shooting", "rotation"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "sporting", "id": "ch8-own-turn-live-animals", "label": "8 · Shoot only in turn; not at others' targets or animals"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch8-mock-shooting", "label": "8 · Mock shooting and accidental shots"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}, {"book": "compak", "id": "ch24-dry-mounting", "label": "24 · No simulated shooting off the stand; no shooting animals"}, {"book": "compak", "id": "ch21-shooting-conduct", "label": "21 · When you may shoot and load"}], "coach_says": [{"en": "Quiet behind, please — she’s on.", "meaning": "The shooter is on the stand; everyone stops talking.", "say": null}, {"en": "Wait until he’s opened his gun.", "meaning": "Nobody talks or moves until the shooter has finished and opened the gun.", "say": null}, {"en": "Stand right behind me so you can see what I see.", "meaning": "In training the coach wants you directly behind, out of the swing.", "say": null}, {"en": "Keep out of his line, please.", "meaning": "You are in the shooter’s view or near the barrels’ path; move back.", "say": null}], "quiz": [{"q": "Where does the interpreter stand while the guest is shooting?", "options": ["Beside the shooter, to see his face", "In front of the stand, to see the target", "Behind the stand, out of any line of the barrels", "Wherever the referee cannot see"], "answer": 2, "why": "Everyone waits behind the stand or cage; beside the shooter is the most dangerous place."}, {"q": "A loud phone call behind the stand clearly disturbs the shooter at the moment of the shot. What may the referee decide?", "options": ["No Bird: the target is thrown again", "Zero for the shooter", "Nothing, phones are not in the rules", "Yellow card for the shooter"], "answer": 0, "why": "If the referee sees the shooter was clearly disturbed, the target is a No Bird."}, {"q": "When is the right moment to pass on the coach’s comment?", "options": ["While the shooter is calling", "Between the call and the shot", "Whenever the coach finishes speaking", "When the gun is open: between targets, pairs or after the stand"], "answer": 3, "why": "The shooter’s routine must not be interrupted; speak only once the gun is open."}]}, {"id": "etiquette-squad", "minutes": 5, "title": "Manners in a squad", "body": ["A squad is up to six shooters drawn by lot who shoot together. Punctuality is the first courtesy and also a rule. In Parcours de Chasse – Sporting™ a missing shooter is called three times within one minute, and targets not shot are scored zero. In Compak® Sporting a shooter who arrives after the first shooter of the squad has called gets 25 zeros for the round, and reporting to the referee beforehand is compulsory.", "Order matters. In Sporting™ the order rotates at each stand and for the doubles; in Compak® shooters move one station to the right after each series. Nobody steps onto the stand until the previous shooter has left it. When called, a shooter is ready at once, with enough cartridges for the whole round.", "The referee decides alone. Squad members do not comment on whether a target was hit unless the referee asks them. Open criticism of a ruling, from shooters or spectators, counts as an attempt to influence the referee. Losing self-control, such as throwing a gun or abusing anyone, goes to the jury and can mean expulsion.", "Beyond the rules there are customs. Shooters usually greet the referee and squad at the start, say “good shot” or “well shot” after a good stand, and “bad luck” after a miss, but never comment on a stranger’s technique. A word of thanks to the trapper and referee at the end, a handshake, and calm when results go up are common on many grounds. Translate these courtesies warmly; they matter."], "key_points": ["Be on time and report to the referee; lateness costs zeros", "Follow the rotation; step up only when the stand is free", "Only the referee rules; no comments on hits", "Losing self-control can mean expulsion", "Customs: greet, “well shot”, thank the trapper and referee"], "terms": ["squad", "rotation", "referee", "trapper", "conduct", "round"], "sources": [{"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}, {"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch16-squads", "label": "16 · Squads of six and rotation"}, {"book": "sporting", "id": "ch16-late-shooter", "label": "16 · Late or absent shooter"}, {"book": "sporting", "id": "ch8-ready-when-called", "label": "8 · Be ready; wait for the stand to clear"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "sporting", "id": "ch8-loss-of-control", "label": "8 · Loss of self-control"}, {"book": "compak", "id": "ch8-shooting-times", "label": "8 · Shooting schedule: the shooter's responsibility"}, {"book": "compak", "id": "ch9-late-squad", "label": "9 · Late in squad shooting: 25 zeros"}, {"book": "compak", "id": "ch9-ready", "label": "9 · Be ready with a full round of equipment and ammunition"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}, {"book": "compak", "id": "ch21-loss-of-control", "label": "21 · Loss of self-control"}], "coach_says": [{"en": "Number twelve — last call!", "meaning": "The referee is calling a missing shooter; if he does not come, his targets will be zeros.", "say": null}, {"en": "You’re next — get ready.", "meaning": "Prepare now: glasses, ears, cartridges, but do not step up until the stand is free.", "say": null}, {"en": "Well shot!", "meaning": "Sincere praise after a good target or stand.", "say": null}, {"en": "Bad luck.", "meaning": "Friendly sympathy after a miss, not criticism.", "say": null}, {"en": "Thanks, ref — thanks for pulling.", "meaning": "Thanking the referee and the trapper at the end of the round.", "say": null}], "quiz": [{"q": "Compak® Sporting, squad shooting: your guest arrives after the first shooter of his squad has called for the first target. What happens?", "options": ["He joins at the next station", "He gets 25 zeros for that round", "He shoots last without penalty", "The round is restarted"], "answer": 1, "why": "In Compak® squad shooting the deadline is the first call of the squad; after it the late shooter scores 25 zeros (an appeal to the jury is possible)."}, {"q": "A squad-mate loudly tells the referee he is wrong about a hit. How do the rules see this?", "options": ["As helpful information", "As a formal protest", "As an attempt to influence the referee", "As nothing at all"], "answer": 2, "why": "Others openly criticising a ruling without the referee’s permission count as an attempt to influence; only the shooter concerned may protest."}, {"q": "In Parcours de Chasse – Sporting™, how does the shooting order work in a squad?", "options": ["It rotates at each stand and for the doubles", "It is fixed for the whole day", "The best shooter always starts", "The referee chooses freely"], "answer": 0, "why": "Squads of six are drawn, and the order rotates at each stand and also for the doubles."}]}, {"id": "etiquette-protection-and-dress", "minutes": 5, "title": "Ears, eyes and dress — yours too", "body": ["Hearing protection is compulsory for everyone on or near a layout: shooters, referees, staff and spectators. In Parcours de Chasse – Sporting™ safety glasses are compulsory, without exception, for shooters, referees, staff and anyone close to a stand. In Compak® Sporting the eyewear rule names competitors, referees and staff. A shooter who comes onto the stand without either is treated as absent.", "That includes you. Standing behind the stand, you are “near a layout”. Electronic ear muffs are the interpreter’s best tool: they soften the shot but let voices through, so you hear the coach and the referee. Clear or tinted shooting glasses also protect you from falling target fragments; a cap helps too.", "The dress code is about safety and respect. No short shorts: only long Bermuda-type shorts ending no more than 5 cm above the knee. Shirts need at least short sleeves and a collar or a round, T-shirt-style neck; a vest over a bare chest is not allowed. Sandals are banned, and in Compak® this applies in practice as well as in competition. The competitor number is worn on the back, between the shoulders and the waist, fully visible, not folded or cut.", "A first breach of dress or number rules brings a warning; if it is not corrected, penalties follow up to exclusion by the jury. At ceremonies team members wear the national team outfit or smart trousers and a blazer, and all prize winners must attend the prize-giving. Dress like a calm professional: closed shoes, neutral clothes, nothing that flaps or shines in the shooter’s eyes."], "key_points": ["Ear protection for everyone near a layout, spectators and interpreters included", "Glasses: Sporting™ — anyone close to a stand; Compak® — competitors, referees, staff", "Without them a shooter is treated as absent", "Bermudas max 5 cm above the knee, sleeves, no bare chest under the vest, no sandals", "Number on the back, fully visible; first breach = warning"], "terms": ["hearing-protection", "electronic-ear-muffs", "earplugs", "safety-glasses", "dress-code", "competitor-number", "shooting-vest", "prize-giving"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-hearing-protection", "label": "8 · Hearing protection is compulsory"}, {"book": "sporting", "id": "ch8-safety-glasses", "label": "8 · Safety glasses are compulsory"}, {"book": "sporting", "id": "ch17-dress-code", "label": "17 · Dress code for competitors"}, {"book": "sporting", "id": "ch17-competitor-number", "label": "17 · Competitor number on the back"}, {"book": "sporting", "id": "ch17-dress-penalties", "label": "17 · Penalties for dress and number violations"}, {"book": "sporting", "id": "ch17-ceremonies", "label": "17 · Dress at the opening and closing ceremonies"}, {"book": "compak", "id": "ch18-hearing", "label": "18 · Hearing protection is compulsory"}, {"book": "compak", "id": "ch18-eyewear", "label": "18 · Protective glasses are compulsory"}, {"book": "compak", "id": "ch7-dress-code", "label": "7 · What to wear at the shooting position"}, {"book": "compak", "id": "ch7-competition-numbers", "label": "7 · Competition number on the back"}, {"book": "compak", "id": "ch7-ceremonies", "label": "7 · Dress for opening and closing ceremonies"}], "coach_says": [{"en": "Eyes and ears on before you leave the clubhouse.", "meaning": "Put on glasses and hearing protection before walking out to the layouts.", "say": null}, {"en": "Where are your ears?", "meaning": "“Ears” = hearing protection, not the ears themselves.", "say": null}, {"en": "You can’t shoot in sandals here.", "meaning": "Closed shoes are required for safety.", "say": null}, {"en": "Your number’s folded — it has to be fully visible.", "meaning": "The competitor number on the back must be complete and visible; otherwise a warning.", "say": null}], "quiz": [{"q": "Your shooter walks onto the stand without safety glasses. How do the rules treat him?", "options": ["He gets a warning and may shoot", "He may shoot if the coach agrees", "He loses one target", "He is treated as absent"], "answer": 3, "why": "In both disciplines a shooter without eye or ear protection on the stand is treated as absent."}, {"q": "Which shorts are allowed?", "options": ["Any sports shorts", "Bermuda-type shorts ending no more than 5 cm above the knee", "Shorts only in Compak®", "No shorts at all"], "answer": 1, "why": "Short shorts are banned; long Bermuda-type shorts no higher than 5 cm above the knee are accepted."}, {"q": "Why are electronic ear muffs a good choice for an interpreter?", "options": ["They soften the shot but let voices through", "They are not required for interpreters", "They block all sound completely", "They record the coach"], "answer": 0, "why": "Hearing protection is compulsory near a layout, and electronic muffs let you hear the coach and referee."}]}]}, {"id": "interpreter", "icon": "speech", "title": "The interpreter at work", "intro": "Everything you have learned comes together here: what you may and may not say, where to stand, the words that trick even experienced linguists, numbers and units, British and American vocabulary, and finally a full training session from the first “good morning” to the debrief.", "lessons": [{"id": "interpreter-role", "minutes": 5, "title": "Your role: training versus competition", "body": ["In training you are the coach’s voice. Render every instruction completely, in the coach’s order and tone: firm when it is about safety, warm when it is praise. Do not soften criticism, do not add reasons the coach did not give, and never add technique tips of your own, even when you know the answer. If you did not hear a word, ask before you translate.", "A competition is different. Coaching a competitor during the competition is forbidden in both Parcours de Chasse – Sporting™ and Compak® Sporting: the shooter gets a yellow card, repeats bring further sanctions, and the referee removes the person who was coaching from the shooting area. The referee also decides alone: nobody in the squad comments on hits, and open criticism of a ruling counts as an attempt to influence the referee.", "Here is the honest part. The FITASC rulebooks do not mention interpreters at all. Whether passing on a coach’s advice word for word during a competition counts as coaching, and where an interpreter may stand, the rules do not say. It is an open question for FITASC, and you should not present any answer as official.", "Until FITASC answers, use the safe practice. In competition interpret only communication with the referee, the jury and the organiser: calls, decisions, warnings, protests, times and squads. Before the event, tell the referee or organiser who you are and agree where you will stand. If a coach asks you to pass on advice during the competition, decline politely and explain why. It protects your shooter from a yellow card."], "key_points": ["Training: the coach’s voice — complete, same tone, nothing of your own", "Competition: coaching is forbidden (yellow card, coach removed)", "Open FITASC question: rulebooks do not mention interpreters", "Safe practice: interpret only referee, jury and organiser communication in competition", "Introduce yourself to the referee and agree where you stand"], "terms": ["coach", "referee", "jury", "yellow-card", "conduct", "interpreter", "coaching"], "sources": [{"title": "FITASC — Sports disciplines (presentation page)", "url": "https://www.fitasc.com/en/sports-disciplines/presentation"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch8-coaching", "label": "8 · No coaching during competition"}, {"book": "sporting", "id": "ch6-referee-alone", "label": "6 · The referee decides alone"}, {"book": "sporting", "id": "ch11-influence", "label": "11 · What counts as influencing the referee"}, {"book": "compak", "id": "ch21-coaching", "label": "21 · No coaching during competition"}, {"book": "compak", "id": "ch19-referee-powers", "label": "19 · What the referee decides"}, {"book": "compak", "id": "ch22-influence", "label": "22 · What counts as an attempt to influence"}], "coach_says": [{"en": "Tell her she’s lifting her head on the second bird.", "meaning": "Training: pass it on fully when the gun is open.", "say": null}, {"en": "Quick — tell him to give the crosser more.", "meaning": "Competition: this is coaching. Decline politely; do not pass it on.", "say": null}, {"en": "Who are you with?", "meaning": "The referee asks why you are near the stand; introduce yourself and your role.", "say": null}, {"en": "Ask the referee if I can still change chokes.", "meaning": "A procedural question to the referee: you may interpret it.", "say": null}], "quiz": [{"q": "During a competition round the coach asks you to tell the shooter “more lead on the crosser”. What do you do?", "options": ["Whisper it quickly", "Translate it after the next target", "Politely decline: it would be coaching, which is forbidden", "Ask the referee to pass it on"], "answer": 2, "why": "Coaching during competition is forbidden and the shooter would get a yellow card; the rules do not say whether relaying advice is allowed, so stay safe."}, {"q": "What do the FITASC rulebooks say about interpreters?", "options": ["They may stand on the stand", "They need a referee’s licence", "They count as coaches", "Nothing: it is an open question"], "answer": 3, "why": "The rulebooks do not mention interpreters, so their exact position in competition is an open question for FITASC."}, {"q": "In training, the coach says “Not bad, but you stopped the gun.” How do you translate?", "options": ["Fully and in the same tone, both parts", "Only the praise, to keep the guest happy", "Only the fault, to save time", "Add your own tip on how to fix it"], "answer": 0, "why": "You neither soften nor inflate: the whole message, in the coach’s tone, with nothing of your own."}]}, {"id": "interpreter-position", "minutes": 5, "title": "Where to stand and when to speak", "body": ["In training, stand directly behind the shooter, next to the coach, behind the stand or cage and out of any line of the barrels. From there you see what the coach sees, the target and the muzzles together, and the coach can talk to you quietly. Beside the shooter is the most dangerous place; in front of the stand is out of the question.", "Choose the mode for the moment. Consecutive interpreting (the coach speaks, pauses, you speak) suits the safety briefing, the walk between stands and the debrief. Whispered interpreting, chuchotage, lets the coach keep talking while you whisper into the shooter’s ear from behind; it is tiring, so alternate the two. Agree on a “pause, I’m translating” sign, such as a raised palm.", "Timing is everything. The shooter’s routine runs from closing the gun to the shot. Speak only when the gun is open: between targets, between pairs, after the stand. Between pairs, mirror the coach’s short cues, “more in front”, “head down”, “same again”, and keep the long explanations for later. Remember the clock: in Parcours de Chasse – Sporting™ a shooter has at most 15 seconds between targets or doubles, and in Compak® Sporting 10 seconds to call. Your words use that time too.", "In competition, wait where the squad waits, close to the stand but never distracting the shooter: a clearly disturbed shooter gets a No Bird, and nobody wants to be the cause. Learn the coach’s hand signals at the start and translate them once for your guests; after that they will need you less, and that is a good sign."], "key_points": ["Training: directly behind the shooter, next to the coach, out of the barrels’ line", "Consecutive for briefings and debriefs; chuchotage on the stand; alternate", "Speak only when the gun is open", "Short cues between pairs; time limits 15 s (Sporting™) and 10 s (Compak®)", "Competition: wait with the squad, never distract"], "terms": ["quiet-on-stand", "shooting-stand", "coach", "firing-time", "no-bird", "chuchotage", "consecutive-interpreting", "hand-signals"], "sources": [{"title": "Let’s Go Shooting — Discover Sporting Clays: NSCA beginner’s guide", "url": "https://www.letsgoshooting.org/resources/articles/shotgun/discover-sporting-clays-nsca-beginners-guide/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch2-waiting-positions", "label": "2 · Waiting positions"}, {"book": "sporting", "id": "ch7-fifteen-seconds", "label": "7 · 15 seconds between targets"}, {"book": "sporting", "id": "ch6-nobird-target-cases", "label": "6 · When the target itself is a No Bird"}, {"book": "compak", "id": "ch2-fal", "label": "2 · Firing Angle Limiters (F.A.L.)"}, {"book": "compak", "id": "ch17-call-time-and-changeover", "label": "17 · 10 seconds to call; change stations with the gun open"}, {"book": "compak", "id": "ch17-squad-rotation", "label": "17 · Squad rotation through the stations"}, {"book": "compak", "id": "ch20-target-no-bird-cases", "label": "20 · When a NO BIRD is given because of the target"}], "coach_says": [{"en": "Stand right behind me.", "meaning": "Behind the coach and the shooter, out of the swing.", "say": null}, {"en": "Head on the stock — just whisper it to him, I’ll keep going.", "meaning": "Switch to chuchotage and pass the cue on quietly; the coach will not pause.", "say": null}, {"en": "When I do this — hands apart — it means more in front.", "meaning": "The coach explains a hand signal; translate it once for the group.", "say": null}, {"en": "Wait — let him finish the pair.", "meaning": "Hold the advice until the gun is open again.", "say": null}, {"en": "Sorry — did you say “under it” or “on it”?", "meaning": "Ask back with the two options you heard; faster than “repeat please”.", "say": null}], "quiz": [{"q": "Where should you stand during a training session on a Sporting™ stand?", "options": ["Beside the shooter, to see the eyes", "Behind the shooter next to the coach, out of the barrels’ line", "In front of the cage, facing the shooter", "Next to the trap"], "answer": 1, "why": "From behind you see what the coach sees and stay safe; beside or in front is dangerous."}, {"q": "What is chuchotage?", "options": ["Interpreting after the speaker pauses", "Written translation of the rules", "Translating hand signals", "Whispered simultaneous interpreting into the listener’s ear"], "answer": 3, "why": "Chuchotage is whispered simultaneous interpreting; consecutive is the pause-and-speak mode."}, {"q": "In Compak® Sporting, how long does a shooter have to call after the previous station’s target was shot?", "options": ["10 seconds", "15 seconds", "30 seconds", "No limit"], "answer": 0, "why": "Compak® gives at most 10 seconds to call; Sporting™ allows 15 seconds between targets or doubles."}]}, {"id": "interpreter-false-friends", "minutes": 6, "title": "False friends on the shooting ground", "body": ["The worst trap is smoke. A coach’s “Smoked it!” (or “inked it”, “powdered it”) means a perfect hit: the target vanished in a cloud. But in the rules a target that gives off only dust or smoke, with no visible piece, is a zero. A “chip”, a small visible piece, is a hit. So translate the coach’s “smoked it” as «розбили вщент», and the referee’s “only dust” as «лише пил — нуль».", "Scoring words are not literal. “Dead” and “kill” mean a hit («є», «збита»), never «мертва» or «вбивство». “Lost” is a miss («промах», «нуль»), not «загублена». “Dropped two” means two targets missed. “Straight” in “25 straight” means a perfect run, not «прямо».", "Equipment and place words. A “trap” is the throwing machine («машинка»), not «пастка» (Trap is also an Olympic discipline). A “stand” is one position, not «стенд»; a “peg” is the marked spot, not a stake; a “broken gun” is an open gun. “Pull!” is the call, “pull-away” a lead method, “length of pull” a stock size. A “card” is a score card or a yellow or red card. “On report” means at the sound of the shot. A “squad” is the FITASC group of up to six; in ClayAway it also names a sub-group of a tour.", "Other languages add traps. French “chandelle” is a near-vertical target (an English teal), not the English chandelle. French “en battue” and Italian “in battuta” mean driven game, not the battue target; Portuguese “batida” is the battue target, “de batida” means driven. For a hit a French referee says “Bon”, an Italian “Buono”; the trapper is a “pulleur” or “puller”. Italian rules use different words for a squad: batteria in Parcours de Chasse – Sporting™, squadra di tiro in Compak®."], "key_points": ["Coach “smoked it” = perfect hit; rules “only dust or smoke” = zero", "Dead / kill = hit; lost / dropped = miss; straight = perfect run", "Trap = machine; stand = one position; peg = the spot; broken gun = open gun", "Pull, card, report and squad each have more than one meaning", "French chandelle and “en battue” differ from the English words"], "terms": ["one", "zero", "visible-piece", "trap", "shooting-stand", "squad", "call", "double-on-report", "pull-away", "length-of-pull", "yellow-card", "score-sheet", "battue", "teal", "false-friend", "peg", "smoked-it"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch6-target-one", "label": "6 · When a target is scored 'one' (hit)"}, {"book": "sporting", "id": "ch6-target-zero", "label": "6 · When a target is scored 'zero' (lost)"}, {"book": "sporting", "id": "ch4-glossary", "label": "4 · Glossary of basic terms"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "compak", "id": "ch20-one", "label": "20 · When a target is a hit (ONE)"}, {"book": "compak", "id": "ch20-zero", "label": "20 · When a target is a miss (ZERO)"}, {"book": "compak", "id": "ch16-squad-group", "label": "16 · Squad and group"}], "coach_says": [{"en": "Smoked it!", "meaning": "Perfect hit, the target turned to dust. Not the rules’ “smoke only”.", "say": null}, {"en": "Only dust — zero.", "meaning": "Referee: no visible piece came off, so it is a miss.", "say": null}, {"en": "Just a chip, but it’s dead.", "meaning": "A small visible piece broke off: it counts as a hit.", "say": null}, {"en": "Break your gun.", "meaning": "Open the gun. Nothing to do with breaking it.", "say": null}, {"en": "Step into the peg.", "meaning": "Stand on the marked shooting spot.", "say": null}, {"en": "The second one’s on report.", "meaning": "The second target is released by the sound of your first shot.", "say": null}], "quiz": [{"q": "The coach shouts “Smoked it!” after a shot. What happened?", "options": ["Only smoke came off: a zero", "The target was destroyed: a perfect hit", "The cartridge misfired", "The target was a flash target"], "answer": 1, "why": "In coach slang “smoked it” is a perfect hit; in the rules “only dust or smoke” is a zero — opposite meanings."}, {"q": "Best Ukrainian for the referee’s “Lost.”?", "options": ["«Загублена»", "«Втрачено час»", "«Промах»", "«Мішень зникла»"], "answer": 2, "why": "“Lost” is the scoring word for a miss (zero), not something lost."}, {"q": "A French guest says he loves shooting “en battue”. What does he mean?", "options": ["Driven game (birds driven over the guns)", "The flat battue target", "A target thrown in a pair", "A broken target"], "answer": 0, "why": "French “en battue” (Italian “in battuta”) means driven game; the battue target is a separate thing."}]}, {"id": "interpreter-numbers-and-units", "minutes": 5, "title": "Numbers and units: feet, yards, gauges, shot sizes", "body": ["British and American coaches measure lead in feet: “give it three feet”, “a yard in front”, “half a bird”, “a barrel’s width”. This is a picture, not a measurement. Translate the unit as said, «три фути», and do not convert it in the middle of an instruction: 0.9 m sounds precise and changes the meaning. Explain once, before the session, that coaches’ feet are an impression, and keep “more”, “less”, “double it” exactly as said.", "Distances to targets are another matter. “It’s about thirty yards” can be given in metres with “about” («приблизно 27 метрів»), because a yard is a little less than a metre. Directions often come as a clock face: straight ahead is 12, so “pick it up at eleven o’clock” is slightly left. Keep the clock; do not turn it into degrees.", "Gauge works backwards. A “12-bore” or “12 gauge” is not 12 mm; the smaller the number, the wider the barrel, so a 20 gauge is thinner. Both FITASC rulebooks allow calibre 12 at most, with barrels of at least 66 cm (26 inches). The vest line in Parcours de Chasse – Sporting™ is 25 cm, which British shooters may call just under ten inches.", "Cartridges: FITASC allows at most 28 g of lead, close to the “one-ounce load” British shooters mention, with shot of 2.0 to 2.5 mm. Shot numbers are not the same in every country: a No. 9 is about 2 mm almost everywhere, but other numbers can differ slightly between British, American and continental systems. When it matters, ask for millimetres. Chokes may come as names, fractions or “thou” (thousandths of an inch); translate the system the coach used."], "key_points": ["Lead in feet is a picture: keep the unit, never convert mid-instruction", "Target distance: yards may become “about … metres”", "Clock face for directions: 12 = straight ahead", "12 gauge ≠ 12 mm; FITASC max calibre 12, barrels ≥ 66 cm (26 in)", "28 g ≈ one ounce; shot 2.0–2.5 mm; shot numbers differ by country — ask for mm"], "terms": ["lead", "gauge", "barrel-length", "shot-size", "load-weight", "choke", "cartridge", "clock-face"], "sources": [{"title": "Shotgun Life — Does barrel length impact target lead?", "url": "https://www.shotgunlife.com/briefs/does-shotgun-barrel-length-impact-target-lead.html"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch7-permitted-guns", "label": "7 · Permitted shotguns"}, {"book": "sporting", "id": "ch7-cartridges", "label": "7 · Cartridge rules"}, {"book": "sporting", "id": "ch3-jacket-line", "label": "3 · The 25 cm marking line on the jacket"}, {"book": "compak", "id": "ch18-gun", "label": "18 · Which guns are allowed"}, {"book": "compak", "id": "ch18-cartridge-load", "label": "18 · Cartridges: 28 g lead, shot 2-2.5 mm"}], "coach_says": [{"en": "Give it three feet.", "meaning": "The lead picture the coach wants; a perceived gap, not a measured distance.", "say": null}, {"en": "Half that.", "meaning": "Use half of the previous lead.", "say": null}, {"en": "Pick it up at eleven o’clock.", "meaning": "Look for the target slightly left of straight ahead.", "say": null}, {"en": "It’s about forty yards out.", "meaning": "The target is roughly 37 metres away.", "say": null}, {"en": "Put a nine in the bottom barrel.", "meaning": "Load a No. 9 shot cartridge (about 2 mm) in the lower barrel, which usually fires first.", "say": null}], "quiz": [{"q": "The coach says “Give it four feet.” What is the best interpretation?", "options": ["«Винос — приблизно 1,22 метра»", "«Винос — чотири фути»", "«Стріляйте на чотири метри далі»", "«Чотири мішені вперед»"], "answer": 1, "why": "Lead in feet is a picture; converting it mid-instruction adds false precision and changes the message."}, {"q": "What is the largest calibre allowed in FITASC Sporting™ and Compak®?", "options": ["10", "16", "20", "12"], "answer": 3, "why": "Both rulebooks allow calibre 12 at most; a smaller gauge number means a wider bore, so 10 is not allowed."}, {"q": "A British guest asks whether his “one-ounce” cartridges are legal at a FITASC event. What do you know?", "options": ["The FITASC limit is 28 g of lead (+2%), which is about one ounce", "FITASC allows 36 g", "Any load is allowed", "Only 24 g is allowed"], "answer": 0, "why": "The rules allow up to 28 g of lead with a +2% tolerance; one ounce is about 28 g. Shot size (2.0–2.5 mm) must also fit."}]}, {"id": "interpreter-english-sporting-vs-fitasc", "minutes": 5, "title": "British and American words versus FITASC", "body": ["Many coaches you will work with grew up with English Sporting, governed in England by the CPSA, or with American Sporting Clays under the NSCA. The words are similar to FITASC, but the rules behind them are not, and the biggest difference is the gun position.", "In English Sporting and NSCA a shooter may start “gun up”, already mounted, before calling. In Parcours de Chasse – Sporting™ that is not allowed: the stock stays below the line on the vest until the target appears, and every target is shot from the shoulder. Compak® Sporting is in between: the gun position at the call is free. So “pre-mount this one” is a drill in training, but a yellow card at a FITASC Sporting™ competition. Translate it, and if the guest is about to compete, ask the coach whether to mention the rule.", "Pairs have different names. A “true pair” (English and American) is a FITASC simultaneous double. A “report pair” is a double on report. A “following pair” is a FITASC rafale. A “show pair” is the viewing of targets before shooting. A “peg” is the shooting stand, a “station” is the American word for a stand, and a “cage” is the frame around it.", "Results talk differs too. “HOA”, High Over All, is the overall winner. Classes such as AA, A, B or C are national skill levels from averages, not FITASC age categories, and not the FITASC difficulty classes A, B and C, which grade trajectories. Even within FITASC, pairs differ: in Sporting™ both cartridges may go at one target of a double, in Compak® only one cartridge per target. Always ask yourself which rulebook the speaker has in mind."], "key_points": ["Gun up: allowed in English Sporting and NSCA, forbidden in FITASC Sporting™, free in Compak®", "True pair = simultaneous; report pair = on report; following pair = rafale", "Peg = shooting spot; station = stand (US); cage = protective frame", "HOA = overall winner; AA/A/B/C classes are not FITASC categories or difficulty classes", "Sporting™: both shots at one target allowed; Compak®: one per target"], "terms": ["ready-position", "gun-mount", "simultaneous-double", "double-on-report", "rafale-double", "target-presentation", "shooting-stand", "english-sporting", "nsca", "cpsa", "gun-up", "true-pair", "peg", "cage", "hoa", "shooter-class"], "sources": [{"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "CPSA — English Sporting", "url": "https://www.cpsa.co.uk/disciplines/esp"}, {"title": "Wikipedia — Sporting clays", "url": "https://en.wikipedia.org/wiki/Sporting_clays"}, {"title": "Mid Valley Clays — Terminology", "url": "https://midvalleyclays.com/terminology/"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch12-yellow-card", "label": "12 · Yellow card for gun position"}, {"book": "compak", "id": "ch17-gun-position", "label": "17 · Gun position when calling"}, {"book": "sporting", "id": "ch4-simultaneous-double", "label": "4 · Simultaneous double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch4-rafale-double", "label": "4 · Rafale double"}, {"book": "sporting", "id": "ch16-presentation", "label": "16 · Presentation of targets"}, {"book": "sporting", "id": "ch2-shooting-stands", "label": "2 · Size and surface of the shooting stand"}, {"book": "sporting", "id": "ch2-difficulty-classes", "label": "2 · Difficulty classes A, B and C"}, {"book": "sporting", "id": "ch4-doubles-general", "label": "4 · Doubles: two cartridges only"}, {"book": "compak", "id": "ch3-one-cartridge-per-target", "label": "3 · Doubles: one cartridge per target, no doubling the first"}], "coach_says": [{"en": "Pre-mount this one for now.", "meaning": "Training drill: start with the gun in the shoulder. Not allowed in FITASC Sporting™ competition.", "say": null}, {"en": "It’s a true pair.", "meaning": "Both targets leave at the same time (FITASC: simultaneous double).", "say": null}, {"en": "Following pair off the left trap.", "meaning": "Two targets from the same trap one after the other (FITASC: rafale).", "say": null}, {"en": "Let’s see a show pair.", "meaning": "Throw the pair once so everyone can watch it before shooting.", "say": null}, {"en": "He’s AA class and won HOA last year.", "meaning": "A high national skill class, and overall winner of the event.", "say": null}], "quiz": [{"q": "A British coach says “It’s a true pair.” What is the FITASC term?", "options": ["A double on report", "A rafale double", "A simultaneous double", "A correct double"], "answer": 2, "why": "“True pair” is the English and American name for two targets released together, a FITASC simultaneous double."}, {"q": "In which discipline is a “gun up” start NOT allowed?", "options": ["Parcours de Chasse – Sporting™ (FITASC)", "Compak® Sporting", "English Sporting (CPSA)", "Sporting Clays (NSCA)"], "answer": 0, "why": "FITASC Sporting™ requires the stock below the vest line until the target appears; Compak® leaves the gun position free."}, {"q": "A guest reads “Class C” in British results. What is it?", "options": ["A FITASC age category", "A national skill level based on averages", "The hardest FITASC trajectory class", "A type of cartridge"], "answer": 1, "why": "In British and American results classes are skill levels; FITASC uses A/B/C only for trajectory difficulty and has age categories instead."}]}, {"id": "interpreter-session-script", "minutes": 8, "title": "A whole training session, step by step", "body": ["Before the session, meet the coach for five minutes. Agree on a pause sign, ask which method the coach teaches and which words he uses for lead, and learn his hand signals. Then the group gathers for the safety briefing: interpret it consecutively, sentence by sentence, firmly and completely.", "On the first stand the coach usually starts without cartridges: an eye-dominance check, then stance and the ready position. In a FITASC context the gun starts low, below the line on the vest. Whisper his corrections from behind while he moves feet and hands.", "Next comes reading the target. The coach shows it, asks where the shooter first sees it clearly, and sets the pick-up point, the hold point and the break point. Keep these three terms consistent all day, «точка підхоплення», «точка утримання», «точка пострілу», so the guest learns them.", "Now the shooting. Between targets the coach gives two- to five-word cues; you mirror them, same length, same order, while the gun is open. When a miss is diagnosed, “behind”, “over the top”, “you stopped”, translate the diagnosis and the fix together. Praise is translated with the same energy.", "Then the pairs: which target first, “eyes first, then the gun”, the second shot. Finally the debrief, consecutive again, where the coach sums up two or three points. Write them down in both languages and give the guest the note. Below is a real-world chain of phrases in the order you will hear them."], "key_points": ["Before: pause sign, method, lead words, hand signals", "Safety briefing: consecutive, firm, complete", "Same three terms all day: pick-up, hold, break point", "Cues between targets: same length, gun open; diagnosis + fix together", "Debrief: write the key points in both languages"], "terms": ["coach", "safety", "eye-dominance", "master-eye", "stance", "ready-position", "gun-mount", "pick-up-point", "hold-point", "break-point", "lead", "maintained-lead", "pull-away", "head-lift", "stopping-the-gun", "follow-through", "double-on-report", "crosser", "rabbit", "choke"], "sources": [{"title": "Shooting UK — Issues with eye dominance", "url": "https://www.shootinguk.co.uk/shooting/instruction/issues-with-eye-dominance-15475/"}, {"title": "NSSA-NSCA — Foot position (Ask the instructor)", "url": "https://nssa-nsca.org/blog/2019/02/18/4037/"}, {"title": "The Country Girls UK — Clay shooting terminology", "url": "https://thecountrygirlsuk.com/coachs-corner/clay-shooting-terminology/"}, {"title": "Ducks Unlimited — The big five wingshooting mistakes", "url": "https://www.ducks.org/hunting/shooting-tips/the-big-five-wingshooting-mistakes"}], "sim": null, "rule_refs": [{"book": "sporting", "id": "ch3-ready-position", "label": "3 · Ready position: feet and gun"}, {"book": "sporting", "id": "ch3-mounting", "label": "3 · When the gun may be mounted"}, {"book": "sporting", "id": "ch3-between-doubles", "label": "3 · Gun position between the two targets of a double"}, {"book": "sporting", "id": "ch4-double-on-report", "label": "4 · Double on report"}, {"book": "sporting", "id": "ch8-loading", "label": "8 · When and how to load"}, {"book": "sporting", "id": "ch7-gun-handling", "label": "7 · Carrying and storing guns"}], "coach_says": [{"en": "Morning, everyone. Before we load anything, a quick safety briefing.", "meaning": "Start of the session; interpret the briefing consecutively and completely.", "say": null}, {"en": "Guns stay open until you’re on the stand and I say “load”.", "meaning": "No closed guns off the stand; loading only on the coach’s word.", "say": null}, {"en": "Point at my nose, both eyes open. Now close your left eye.", "meaning": "Eye-dominance check: if the finger jumps, the right eye is not the master eye.", "say": null}, {"en": "Front foot pointing at the break point, weight forward.", "meaning": "Stance: set the feet for where the target will be broken; lean slightly forward.", "say": null}, {"en": "Gun down, stock under the line. Mount only when you see it.", "meaning": "FITASC ready position: the gun comes up only after the target appears.", "say": null}, {"en": "Watch this one. Where do you first see it clearly?", "meaning": "The coach is setting the pick-up point.", "say": null}, {"en": "Hold your muzzles about halfway back, just under the line.", "meaning": "Hold point between pick-up and break point, slightly below the target’s path.", "say": null}, {"en": "Behind it. Give it more.", "meaning": "The shot passed behind the target: more lead.", "say": null}, {"en": "Call it three feet — that’s the picture you want.", "meaning": "The lead picture to see at the shot; feet as an impression, keep the unit.", "say": null}, {"en": "Over the top. You lifted your head — stay in the gun.", "meaning": "Miss above, caused by the cheek leaving the stock.", "say": null}, {"en": "Smoked it! Same again.", "meaning": "Perfect hit; repeat exactly what you did.", "say": null}, {"en": "You stopped the gun. Keep it moving through the shot.", "meaning": "Miss behind because the swing stopped; follow through.", "say": null}, {"en": "Next is a report pair: crosser first, then the rabbit.", "meaning": "The rabbit is released by the sound of the shot at the crosser.", "say": null}, {"en": "Eyes first, then the gun.", "meaning": "On the second target, find it with the eyes before moving the muzzles.", "say": null}, {"en": "Keep the muzzles under the rabbit.", "meaning": "Stay low on a rolling target so a hop still meets the shot.", "say": null}, {"en": "Change to quarter and half for this stand.", "meaning": "Fit 1/4 and 1/2 chokes (open, then a little tighter).", "say": null}, {"en": "Let’s call it a day. Three things for tomorrow: feet, head, follow-through.", "meaning": "End of session; the coach sums up — write these down for the guest.", "say": null}], "quiz": [{"q": "When is the safety briefing interpreted, and how?", "options": ["Briefly in chuchotage while guests load", "At the start, consecutively, sentence by sentence and completely", "Only if a guest asks", "After the first stand"], "answer": 1, "why": "Safety comes first and must not be shortened; consecutive mode lets every rule land."}, {"q": "The coach says “Behind it. Give it more.” What is the best short rendering between targets?", "options": ["«Ви трохи запізнилися, спробуйте ще раз, можливо, швидше»", "«Позаду. Більший винос.»", "«Стріляйте раніше»", "«Добре, так само»"], "answer": 1, "why": "Mirror the coach: same length, same order, diagnosis plus fix, nothing added."}, {"q": "Why keep “pick-up point”, “hold point” and “break point” in the same Ukrainian words all day?", "options": ["The rules require it", "So the coach can understand Ukrainian", "So the guest learns three stable concepts and does not confuse them", "It does not matter"], "answer": 2, "why": "Consistent terms build the guest’s mental map of a stand; changing words makes three concepts look like six."}]}]}]};
